// Native results can arrive after page load but before a large library finishes
// restoring. Queue them until the real import handlers and initial view are ready.
const pendingStartupMedia = [];
for (const name of ['onNativePhotoCaptured', 'onNativePhotosImported', 'onNativePhotosImportedToAlbum']) {
  window[name] = (...args) => pendingStartupMedia.push({ name, args });
}

function escapeHtml(str) {
  if (str == null) return '';
  return String(str)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

function escapeJs(str) {
  if (str == null) return '';
  return String(str)
    .replace(/\\/g, '\\\\')
    .replace(/'/g, "\\'")
    .replace(/"/g, '\\"')
    .replace(/\n/g, '\\n')
    .replace(/\r/g, '\\r');
}

