// -------------------------------------------------------------
// Custom Color Studio Modal Controller (With OK & Cancel)
// -------------------------------------------------------------
let customColorPickerState = {
  isOpen: false,
  activeColor: '#f43f5e',
  originalColor: '#f43f5e',
  callbackName: null,
  callbackFn: null
};

function openCustomColorPickerModal({ initialColor, onApply, onApplyName }) {
  const norm = normalizeHex(initialColor || state.accentColor || '#f43f5e');
  customColorPickerState.activeColor = norm;
  customColorPickerState.originalColor = norm;
  customColorPickerState.callbackName = onApplyName || (typeof onApply === 'string' ? onApply : null);
  customColorPickerState.callbackFn = typeof onApply === 'function' ? onApply : (window[onApplyName] || null);
  customColorPickerState.isOpen = true;

  setModalPickerLiveColor(norm, true);

  const origIndicator = document.getElementById('modalPickerOriginalColor');
  if (origIndicator) {
    origIndicator.style.background = norm;
    origIndicator.onclick = () => setModalPickerLiveColor(customColorPickerState.originalColor);
  }

  const modal = document.getElementById('customColorPickerModal');
  if (modal) modal.style.display = 'flex';
}

function closeCustomColorPickerModal() {
  const modal = document.getElementById('customColorPickerModal');
  if (modal) modal.style.display = 'none';
  customColorPickerState.isOpen = false;
  customColorPickerState.callbackFn = null;
  customColorPickerState.callbackName = null;
}

function setModalPickerLiveColor(color, syncNative = true) {
  const norm = normalizeHex(color);
  customColorPickerState.activeColor = norm;

  const preview = document.getElementById('modalPickerColorPreview');
  if (preview) {
    preview.style.backgroundColor = norm;
    preview.style.boxShadow = `inset 0 -12px 24px rgba(0,0,0,0.25), 0 0 24px ${norm}40`;
  }

  const badge = document.getElementById('modalPickerHexBadge');
  if (badge) badge.textContent = norm.toUpperCase();

  const hexInput = document.getElementById('modalPickerHexInput');
  if (hexInput && document.activeElement !== hexInput) {
    hexInput.value = norm.replace('#', '').toUpperCase();
  }

  const nativeInput = document.getElementById('modalPickerNativeInput');
  if (nativeInput && syncNative) {
    nativeInput.value = norm;
  }
}

function handleModalPickerInput(color) {
  if (!color) return;
  setModalPickerLiveColor(color, false);
}

function handleModalPickerHexInput(val) {
  if (!val) return;
  let clean = val.replace(/[^0-9a-fA-F]/g, '').slice(0, 6);
  if (clean.length === 6 || clean.length === 3) {
    setModalPickerLiveColor('#' + clean, true);
  }
}

function applyCustomColorFromModal() {
  const color = customColorPickerState.activeColor || '#f43f5e';
  addCustomColor(color);

  const fnName = customColorPickerState.callbackName;
  let fn = customColorPickerState.callbackFn;
  if (!fn && fnName && typeof window !== 'undefined' && window[fnName]) {
    fn = window[fnName];
  }
  if (!fn && fnName) {
    if (fnName === 'selectNewTagColor') fn = selectNewTagColor;
    else if (fnName === 'selectRenameColor') fn = selectRenameColor;
    else if (fnName === 'setAppAccentColor') fn = setAppAccentColor;
    else if (fnName === 'selectModalAlbumColor') fn = window.selectModalAlbumColor;
    else if (fnName === 'selectFusionColor') fn = window.selectFusionColor;
    else if (fnName === 'selectShakeWaveColor') fn = selectShakeWaveColor;
    else if (fnName === 'selectStudioBackdropColor') fn = window.selectStudioBackdropColor || selectStudioBackdropColor;
  }

  if (typeof fn === 'function') {
    fn(color, true);
  }

  closeCustomColorPickerModal();
  showToast(`Color ${color.toUpperCase()} saved & selected!`);
}

// In-App Theme Accent Color Palette
const ACCENT_PRESETS = [
  '#f43f5e', '#ec4899', '#8b5cf6', '#6366f1', '#0284c7', '#10b981', '#f59e0b', '#ea580c'
];

/**
 * Reusable Categorized Color Palette Builder
 * Renders two distinct sections:
 * 1. Curated Presets
 * 2. Your Color Palettes (with Custom Color Picker + saved user colors with individual delete options)
 * The tick mark strictly and animatedly reflects the active selection across both sections.
 */
function buildCategorizedPaletteHtml({
  presetColors,
  selectedColor,
  savedColors,
  onSelectFn,
  customInputId,
  customSwatchId
}) {
  const curVal = normalizeHex(selectedColor || presetColors[0]);
  const userColors = Array.isArray(savedColors) ? savedColors : [];

  const presetsHtml = presetColors.map(c => {
    const norm = normalizeHex(c);
    const isSelected = curVal === norm;
    return `
      <div class="color-option ${isSelected ? 'selected' : ''}" style="background:${c};" onclick="${onSelectFn}('${c}', true)" title="Preset: ${c}">
        ${isSelected ? '<i class="fa-solid fa-check"></i>' : ''}
      </div>
    `;
  }).join('');

  const savedSwatchesHtml = userColors.map(c => {
    const norm = normalizeHex(c);
    const isSelected = curVal === norm;
    return `
      <div class="saved-swatch-wrapper">
        <div class="color-option saved-custom-option ${isSelected ? 'selected' : ''}" style="background:${c};" onclick="${onSelectFn}('${c}', true)" title="Your Color: ${c}">
          ${isSelected ? '<i class="fa-solid fa-check"></i>' : ''}
        </div>
        <button type="button" class="swatch-delete-btn" onclick="event.stopPropagation(); deleteSavedCustomColor('${c}', event, '${onSelectFn}')" title="Delete ${c}">
          <i class="fa-solid fa-xmark"></i>
        </button>
      </div>
    `;
  }).join('');

  const lblCurated = window.t ? window.t('palette_curated_presets') : 'Curated Presets';
  const lblYourPalettes = window.t ? window.t('palette_your_palettes') : 'Your Color Palettes';
  const lblSavedCustom = window.t ? window.t('palette_saved_custom') : 'Saved & Custom';
  const lblOpenStudio = window.t ? window.t('palette_open_studio') : 'Open Color Studio';

  return `
    <div class="palette-category-block">
      <div class="palette-category-header">
        <span class="palette-category-title"><i class="fa-solid fa-sparkles"></i> ${lblCurated}</span>
      </div>
      <div class="palette-swatches-strip">
        ${presetsHtml}
      </div>
    </div>

    <div class="palette-category-block" style="margin-top: 10px;">
      <div class="palette-category-header">
        <span class="palette-category-title"><i class="fa-solid fa-swatchbook"></i> ${lblYourPalettes}</span>
        <span class="palette-category-hint">${lblSavedCustom}</span>
      </div>
      <div class="palette-swatches-strip">
        <div class="color-option custom-color-option" id="${customSwatchId}" onclick="openCustomColorPickerModal({ initialColor: '${selectedColor || '#f43f5e'}', onApplyName: '${onSelectFn}' })" title="${lblOpenStudio}">
          <i class="fa-solid fa-plus"></i>
        </div>
        ${savedSwatchesHtml}
      </div>
    </div>
  `;
}

function setAppAccentColor(color, notify = true, isFinal = true, persist = true) {
  if (!color) return;
  state.accentColor = color;

  // Dynamically update CSS custom properties on document element
  document.documentElement.style.setProperty('--primary', color);
  document.documentElement.style.setProperty('--accent-rose', color);
  document.documentElement.style.setProperty('--primary-hover', color);
  document.documentElement.style.setProperty('--primary-light', color);
  document.documentElement.style.setProperty('--border-glow', `${color}40`);
  document.documentElement.style.setProperty('--primary-container', `${color}20`);

  if (persist) saveState();
  renderThemeAccentPalette();
  if (notify) {
    showToast(window.t('settings_accent_applied', { color: color.toUpperCase() }));
  }
}

function renderThemeAccentPalette() {
  const palette = document.getElementById('themeAccentPaletteContainer');
  if (!palette) return;

  const markup = buildCategorizedPaletteHtml({
    presetColors: ACCENT_PRESETS,
    selectedColor: state.accentColor || '#f43f5e',
    savedColors: state.savedCustomColors || [],
    onSelectFn: 'setAppAccentColor',
    customInputId: 'themeCustomColorInput',
    customSwatchId: 'themeCustomColorSwatch'
  });
  if (palette._settingsMarkup !== markup || !palette.childElementCount) {
    palette.innerHTML = markup;
    palette._settingsMarkup = markup;
  }
}

// In-App Theme Switcher
function setAppTheme(theme, notify = true, persist = true) {
  state.themePref = theme;
  try { window.AndroidApp?.setStartupAppearance?.(theme); } catch (_) {}
  let resolvedMode = theme;

  if (theme === 'system') {
    const prefersDark = window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches;
    resolvedMode = prefersDark ? 'dark' : 'light';
  }

  // Paint the Settings palette together instead of fading each card separately.
  const settingsScreen = document.getElementById('settingsScreen');
  const batchSettingsThemePaint = settingsScreen?.classList.contains('active') &&
    document.body.classList.contains('light-mode') !== (resolvedMode === 'light');
  if (batchSettingsThemePaint) {
    if (settingsScreen._themePaintFrame) cancelAnimationFrame(settingsScreen._themePaintFrame);
    settingsScreen.classList.add('settings-theme-paint');
  }

  if (resolvedMode === 'light') {
    document.body.classList.remove('dark-mode');
    document.body.classList.add('light-mode');
  } else {
    document.body.classList.remove('light-mode');
    document.body.classList.add('dark-mode');
  }

  // Synchronize desktop top navbar theme toggle button
  const topThemeBtn = document.getElementById('themeToggleBtn');
  if (topThemeBtn) {
    topThemeBtn.innerHTML = resolvedMode === 'light'
      ? '<i class="fa-solid fa-sun"></i><span>Theme</span>'
      : '<i class="fa-solid fa-moon"></i><span>Theme</span>';
  }

  // Update active state on Settings screen theme cards
  document.getElementById('themeOptDark')?.classList.toggle('active', theme === 'dark');
  document.getElementById('themeOptLight')?.classList.toggle('active', theme === 'light');
  document.getElementById('themeOptSystem')?.classList.toggle('active', theme === 'system');

  if (batchSettingsThemePaint) {
    // Keep normal control transitions after one frame of the complete new theme.
    settingsScreen._themePaintFrame = requestAnimationFrame(() => {
      settingsScreen._themePaintFrame = requestAnimationFrame(() => {
        settingsScreen.classList.remove('settings-theme-paint');
        settingsScreen._themePaintFrame = null;
      });
    });
  }

  if (persist) saveState();

  if (notify) {
    const label = window.t(theme === 'system' ? 'settings_theme_system' : theme === 'light' ? 'settings_theme_light' : 'settings_theme_dark');
    showToast(window.t('settings_theme_applied', { theme: label }));
  }
}

// In-App Phone Navigation to Settings
function navigateToSettings() {
  const navBtn = document.querySelector('.nav-item[data-tab="settingsScreen"]');
  if (navBtn) {
    navBtn.click();
  }
}

function showToast(msg) {
  // If paywall or subscription checkout modal is active, never display toast messages on the payment screen
  const isPaywallOpen = ['vipSaveLimitModal', 'vipDirectImportModal', 'razorpayModal'].some(id => {
    const el = document.getElementById(id);
    return el && el.style.display && el.style.display !== 'none';
  });
  if (isPaywallOpen) return;

  const toast = document.getElementById('toastMessage');
  if (!toast) return;
  toast.textContent = msg;
  toast.classList.add('show');
  clearTimeout(toast._toastTimer);
  toast._toastTimer = setTimeout(() => {
    toast.classList.remove('show');
  }, 3200);
}

// -------------------------------------------------------------
// UI RENDERING
// -------------------------------------------------------------

function renderAll(options = {}) {
  const storageNotice = document.getElementById('libraryStorageStatus');
  if (storageNotice && !storageNotice.hidden) storageNotice.textContent = libraryStorageText('saving');
  // Reconcile data independently of hidden card DOM. Each tab renders when visible.
  if (!options.reuseViews) reconcileTrashAlbums(window.LibraryViews.get(state).trash);
  const active = document.querySelector('.app-screen.active')?.id || state.activeTab || 'dockScreen';
  if (active === 'dockScreen') renderDock();
  else if (active === 'galleryScreen') renderGallery();
  else if (active === 'albumsScreen') { renderAlbumsScreen(); renderTags(); }
  else if (active === 'favoritesScreen') renderFavorites();
  else if (active === 'trashScreen') renderTrash();
  renderNavBadges();
  if (!options.reuseViews || active === 'settingsScreen') renderSettings();
  refreshActivePhotoWindow();
}
window.renderAll = renderAll;

let _photoEntryFrame = null;
function refreshActivePhotoWindow() {
  if (!window.AndroidApp) return;
  const refresh = () => {
    const viewport = document.querySelector('.app-viewport');
    if (!viewport) return;
    // All screens share this viewport, but retain separate virtual windows.
    // Reconcile the newly visible window even when no scroll event is emitted.
    if (document.getElementById('dockScreen')?.classList.contains('active')) {
      updateDockScrollWindow(viewport);
    } else if (document.getElementById('galleryScreen')?.classList.contains('active')) {
      updateGalleryScrollWindow(viewport);
    } else if (document.getElementById('trashScreen')?.classList.contains('active')) {
      updateTrashScrollWindow(viewport);
    }
  };
  refresh();
  if (_photoEntryFrame !== null) cancelAnimationFrame(_photoEntryFrame);
  _photoEntryFrame = requestAnimationFrame(() => {
    _photoEntryFrame = null;
    refresh();
  });
}

let _settingsMetricsCache = null;

// Render Settings Screen & Dynamic Controls
function renderSettings() {
  const isPro = !!state.isPro;

  // Profile VIP Tag & Header Status Badge
  const profileVipTag = document.getElementById('profileVipTag');
  if (profileVipTag) {
    profileVipTag.textContent = isPro
      ? (window.t ? window.t('settings_pro_vip') : 'AURA PRO')
      : (window.t ? window.t('settings_starter') : 'STARTER');
    profileVipTag.className = isPro ? 'vip-sparkle-tag pro-active' : 'vip-sparkle-tag';
  }

  const proStatusBadge = document.getElementById('settingsProStatusBadge');
  if (proStatusBadge) {
    proStatusBadge.textContent = isPro ? window.t('billing_active') : (window.t ? window.t('settings_free_tier') : 'FREE TIER');
    proStatusBadge.className = isPro ? 'pro-chip-pill pro-active' : 'pro-chip-pill';
  }

  // Profile status desc
  const profileStatusDesc = document.getElementById('profileStatusDesc');
  if (profileStatusDesc) {
    profileStatusDesc.textContent = isPro
      ? (window.t ? window.t('settings_storage_pro_active') : 'Aura Pro Membership Active · 100% Private On-Device & Secret Vault Unlocked')
      : (window.t ? window.t('settings_storage_private') : 'Standard local storage · 100% private');
  }

  // Pro Upgrade Card Button
  const startRazorpayBtn = document.getElementById('startRazorpayBtn');
  if (startRazorpayBtn) {
    startRazorpayBtn.classList.toggle('activated', isPro);
  }

  // Bottom Navigation Bar Pro Sparkle Badge
  const proBadgeNav = document.getElementById('proBadgeNav');
  if (proBadgeNav) {
    proBadgeNav.style.display = isPro ? 'inline-flex' : 'none';
  }

  // Active theme selector card
  const curTheme = state.themePref || 'dark';
  document.getElementById('themeOptDark')?.classList.toggle('active', curTheme === 'dark');
  document.getElementById('themeOptLight')?.classList.toggle('active', curTheme === 'light');
  document.getElementById('themeOptSystem')?.classList.toggle('active', curTheme === 'system');

  // Biometric toggle
  const bioToggle = document.getElementById('biometricLockToggle');
  if (bioToggle) {
    bioToggle.checked = !!state.biometricLock;
  }
  const appLockSub = document.getElementById('appLockSubControls');
  if (appLockSub) {
    appLockSub.style.display = state.biometricLock ? 'flex' : 'none';
  }

  window.PicShelfSettings?.refresh();

  // Location & GPS Metadata Toggles
  const gpsToggle = document.getElementById('gpsMetadataToggle');
  if (gpsToggle) {
    gpsToggle.checked = state.gpsMetadataEnabled !== false;
  }

  const locTagsToggle = document.getElementById('locationTagsToggle');
  if (locTagsToggle) {
    locTagsToggle.checked = state.locationTagsEnabled !== false;
  }

  const placeToggle = document.getElementById('locationTagPlaceToggle');
  if (placeToggle) {
    placeToggle.checked = state.locationTagPlace !== false;
  }

  const cityToggle = document.getElementById('locationTagCityToggle');
  if (cityToggle) {
    cityToggle.checked = state.locationTagCity !== false;
  }

  const countryToggle = document.getElementById('locationTagCountryToggle');
  if (countryToggle) {
    countryToggle.checked = state.locationTagCountry !== false;
  }
  const galleryLocBadgeToggle = document.getElementById('galleryLocationBadgeToggle');
  if (galleryLocBadgeToggle) {
    galleryLocBadgeToggle.checked = state.galleryShowLocationBadge === true;
  }

  const subTogglesContainer = document.getElementById('locationSubTogglesContainer');
  if (subTogglesContainer) {
    const isAvailable = state.locationTagsEnabled !== false;
    subTogglesContainer.style.opacity = isAvailable ? '1' : '0.4';
    subTogglesContainer.style.pointerEvents = isAvailable ? 'auto' : 'none';
  }

  if (document.getElementById('settingsScreen')?.classList.contains('active')) {
  // Accurate Multi-Media Storage Breakdown & Integrity Engine
  // All active items in local app storage must be counted, including duplicate photos, duplicate videos, dock items, and album items.
  const views = window.LibraryViews.get(state);
  if (!_settingsMetricsCache || _settingsMetricsCache.views !== views || _settingsMetricsCache.revision !== views.revision) {
    let audioCount = 0, videoCount = 0;
    for (const p of views.active) {
      const audio = p.mediaType === 'audio' || (p.displayName && /\.(mp3|wav|m4a|aac|ogg|flac|wma)$/i.test(p.displayName)) || (typeof p.dataUrl === 'string' && p.dataUrl.startsWith('data:audio/'));
      if (audio) audioCount++;
      else if (p.mediaType === 'video' || p.videoUrl || (p.displayName && /\.(mp4|webm|mov|m4v|mkv|avi)$/i.test(p.displayName)) || (typeof p.dataUrl === 'string' && p.dataUrl.startsWith('data:video/'))) videoCount++;
    }
    _settingsMetricsCache = { views, revision: views.revision, audioCount, videoCount, photoCount: views.active.length - audioCount - videoCount };
  }
  const metrics = _settingsMetricsCache;
  const { photoCount, videoCount, audioCount } = metrics;
  const trashItems = views.trash;
  const inTrashCount = trashItems.length + (Array.isArray(state.deletedAlbums) ? state.deletedAlbums.length : 0);

  // Update Media Count Indicators
  const storagePhotoCount = document.getElementById('storagePhotoCount');
  if (storagePhotoCount) storagePhotoCount.textContent = photoCount;

  const storageVideoCount = document.getElementById('storageVideoCount');
  if (storageVideoCount) storageVideoCount.textContent = videoCount;

  const storageAudioCount = document.getElementById('storageAudioCount');
  if (storageAudioCount) storageAudioCount.textContent = audioCount;

  const storageAudioLegend = document.getElementById('storageAudioLegend');
  if (storageAudioLegend) {
    storageAudioLegend.style.display = audioCount > 0 ? 'inline-flex' : 'none';
  }

  const storageTrashCount = document.getElementById('storageTrashCount');
  if (storageTrashCount) storageTrashCount.textContent = inTrashCount;

  const storageTagCount = document.getElementById('storageTagCount');
  if (storageTagCount) storageTagCount.textContent = state.tags.length;

  function formatStorageSize(bytes) {
    if (typeof bytes !== 'number' || isNaN(bytes) || bytes <= 0) return '0 B';
    if (bytes >= 1024 * 1024 * 1024) {
      return `${(bytes / (1024 * 1024 * 1024)).toFixed(2)} GB`;
    }
    if (bytes >= 1024 * 1024) {
      return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
    }
    if (bytes >= 1024) {
      return `${(bytes / 1024).toFixed(0)} KB`;
    }
    return `${bytes} B`;
  }

  function calculateMediaBytesBreakdown(idbSizes) {
    const sizes = idbSizes || window._cachedIDBMediaSizes || new Map();
    if (metrics.breakdown && metrics.sizes === sizes) return metrics.breakdown;
    let photoBytes = 0;
    let videoBytes = 0;
    let audioBytes = 0;
    let trashBytes = 0;

    state.photos.forEach(p => {
      let b = 0;
      if (typeof p.fileSize === 'number' && p.fileSize > 0) {
        b = p.fileSize;
      } else if (p.fileBlob && typeof p.fileBlob.size === 'number' && p.fileBlob.size > 0) {
        b = p.fileBlob.size;
        p.fileSize = b;
      } else if (sizes.has(p.id)) {
        b = sizes.get(p.id);
        p.fileSize = b;
      } else if (typeof p.dataUrl === 'string' && p.dataUrl.startsWith('data:')) {
        const commaIdx = p.dataUrl.indexOf(',');
        const b64 = commaIdx >= 0 ? p.dataUrl.length - commaIdx - 1 : p.dataUrl.length;
        b = Math.max(160000, Math.round(b64 * 0.75));
      }

      const isAud = p.mediaType === 'audio' || (p.displayName && p.displayName.match(/\.(mp3|wav|m4a|aac|ogg|flac|wma)$/i)) || (typeof p.dataUrl === 'string' && p.dataUrl.startsWith('data:audio/'));
      const isVid = !isAud && (p.mediaType === 'video' || p.videoUrl || (p.displayName && p.displayName.match(/\.(mp4|webm|mov|m4v|mkv|avi)$/i)) || (typeof p.dataUrl === 'string' && p.dataUrl.startsWith('data:video/')));

      if (b === 0) {
        if (isVid) {
          const dur = (typeof p.duration === 'number' && p.duration > 0) ? p.duration : 10;
          b = Math.max(25 * 1024 * 1024, Math.round(dur * 2.5 * 1024 * 1024));
        } else if (isAud) {
          b = 4.5 * 1024 * 1024;
        } else {
          b = 2.4 * 1024 * 1024;
        }
      }

      if (p.deletedAt) {
        trashBytes += b;
      } else {
        if (isVid) videoBytes += b;
        else if (isAud) audioBytes += b;
        else photoBytes += b;
      }
    });

    const totalBytes = Math.max(1.6 * 1024 * 1024, photoBytes + videoBytes + audioBytes + trashBytes + 512 * 1024);
    metrics.sizes = sizes;
    return metrics.breakdown = { totalBytes, photoBytes, videoBytes, audioBytes, trashBytes };
  }

  function updateMediaBreakdownUI(breakdown) {
    const elPhotos = document.getElementById('breakdownPhotosText');
    if (elPhotos) {
      elPhotos.innerHTML = `<i class="fa-regular fa-image" style="color:#f43f5e; margin-right:4px;"></i> ${escapeHtml(window.t('settings_legend_photos'))}: ${formatStorageSize(breakdown.photoBytes)}`;
    }
    const elVideos = document.getElementById('breakdownVideosText');
    if (elVideos) {
      elVideos.innerHTML = `<i class="fa-solid fa-film" style="color:#a855f7; margin-right:4px;"></i> ${escapeHtml(window.t('settings_legend_videos'))}: ${formatStorageSize(breakdown.videoBytes)}`;
    }
    const elAudios = document.getElementById('breakdownAudiosText');
    if (elAudios) {
      elAudios.style.display = breakdown.audioBytes > 0 ? 'inline-flex' : 'none';
      elAudios.innerHTML = `<i class="fa-solid fa-music" style="color:#38bdf8; margin-right:4px;"></i> ${escapeHtml(window.t('settings_legend_audios'))}: ${formatStorageSize(breakdown.audioBytes)}`;
    }
    const elTrash = document.getElementById('breakdownTrashText');
    if (elTrash) {
      elTrash.style.display = breakdown.trashBytes > 0 ? 'inline-flex' : 'none';
      elTrash.innerHTML = `<i class="fa-solid fa-trash-can" style="color:#fbbf24; margin-right:4px;"></i> ${escapeHtml(window.t('settings_legend_trash'))}: ${formatStorageSize(breakdown.trashBytes)}`;
    }
  }

  // Standard consumer smartphone storage tiers (16, 32, 64, 128, 256, 512, 1024 GB)
  function getStandardDeviceStorageTier(rawGb, usedBytes) {
    const nominalTiers = [16, 32, 64, 128, 256, 512, 1024];
    const usedGb = (typeof usedBytes === 'number' && usedBytes > 0) ? (usedBytes / (1024 * 1024 * 1024)) : 0;
    // Android/iOS system files & OS take ~8-14 GB, so total nominal capacity must fit used + OS headroom
    const minRequiredTier = usedGb + 10;
    
    let baseEstimate = (typeof rawGb === 'number' && rawGb > 0) ? rawGb : 128;
    for (const tier of nominalTiers) {
      if (baseEstimate >= tier * 0.78 && baseEstimate <= tier * 1.05) {
        baseEstimate = tier;
        break;
      }
    }
    const target = Math.max(baseEstimate, minRequiredTier);
    for (const tier of nominalTiers) {
      if (tier >= target) {
        return tier;
      }
    }
    return 128;
  }

  // Dynamic Real Device Storage Detection
  let breakdown = calculateMediaBytesBreakdown();
  let currentTotalBytes = breakdown.totalBytes;
  let totalGb = getStandardDeviceStorageTier(window._cachedStorageQuotaGb || 128, currentTotalBytes);
  let freeGb = null;

  function updateStorageMeterUI(usedBytes, totalCapacityGb, freeCapacityGb) {
    const el = document.getElementById('storageUsageText');
    if (el) {
      const formattedUsed = formatStorageSize(usedBytes);
      let usageStr = window.t('settings_storage_usage', { used: formattedUsed, total: totalCapacityGb });
      if (freeCapacityGb) {
        usageStr += ` (${window.t('settings_storage_free', { free: freeCapacityGb })})`;
      }
      el.textContent = usageStr;
    }
    const bar = document.getElementById('storageProgressBar');
    if (bar) {
      const quotaBytes = totalCapacityGb * 1024 * 1024 * 1024;
      const pct = Math.min(100, Math.max(1.5, (usedBytes / quotaBytes) * 100));
      bar.style.width = `${pct.toFixed(1)}%`;
    }
  }

  updateMediaBreakdownUI(breakdown);
  updateStorageMeterUI(currentTotalBytes, totalGb, freeGb);

  if (window.AndroidApp && typeof window.AndroidApp.getDeviceStorageInfo === 'function') {
    try {
      const infoStr = window.AndroidApp.getDeviceStorageInfo();
      const info = JSON.parse(infoStr);
      if (info && info.totalGb) {
        const standardTier = getStandardDeviceStorageTier(info.totalGb, currentTotalBytes);
        totalGb = standardTier;
        freeGb = info.freeGb;
      }
    } catch (_) { }
    updateStorageMeterUI(currentTotalBytes, totalGb, freeGb);
  } else if (navigator.storage && navigator.storage.estimate) {
    try {
      navigator.storage.estimate().then(est => {
        if (est) {
          if (est.quota) {
            const quotaGb = Math.round(est.quota / (1024 * 1024 * 1024));
            if (quotaGb > 0) {
              const standardTier = getStandardDeviceStorageTier(quotaGb, currentTotalBytes);
              window._cachedStorageQuotaGb = standardTier;
              totalGb = standardTier;
            }
          }
          updateStorageMeterUI(currentTotalBytes, totalGb, freeGb);
        }
      }).catch(() => { });
    } catch (_) { }
  }

  // Asynchronously query exact IndexedDB video blob sizes to update meter with 100% precision
  if (!metrics.idbQueried && typeof getStoredMediaSizesFromIDB === 'function') {
    metrics.idbQueried = true;
    getStoredMediaSizesFromIDB().then(idbSizes => {
      const current = window.LibraryViews.get(state);
      if (current !== metrics.views || current.revision !== metrics.revision) return;
      if (idbSizes && idbSizes.size > 0) {
        breakdown = calculateMediaBytesBreakdown(idbSizes);
        currentTotalBytes = breakdown.totalBytes;
        totalGb = getStandardDeviceStorageTier(totalGb, currentTotalBytes);
        updateMediaBreakdownUI(breakdown);
        updateStorageMeterUI(currentTotalBytes, totalGb, freeGb);
      }
    }).catch(() => {});
  }

  }

  renderThemeAccentPalette();
  renderSettingsLanguageUI();
  updateSubscriptionUI();
}

// Render Language Selector in Settings (Indian Regional & Global Support)
function renderSettingsLanguageUI() {
  const grid = document.getElementById('languageSelectorGrid');
  const hint = document.getElementById('currentLangHintBadge');
  if (!grid || !window.I18N_LANGUAGES) return;
  const currentLang = (window.state && window.state.language) || (typeof state !== 'undefined' && state.language) || localStorage.getItem('photo_org_language') || 'en';
  const activeObj = window.I18N_LANGUAGES.find(l => l.code === currentLang) || window.I18N_LANGUAGES[0];
  if (hint) {
    hint.textContent = `${activeObj.flag} ${activeObj.native}`;
  }
  const markup = window.I18N_LANGUAGES.map(lang => {
    const isSelected = lang.code === currentLang;
    return `
      <button type="button" class="language-option-card ${isSelected ? 'active' : ''}"
        onclick="setAppLanguage('${lang.code}')" aria-label="${escapeHtml(window.t('settings_language_' + lang.code))}">
        <div class="lang-flag-box">${lang.flag}</div>
        <div class="lang-text-meta">
          <span class="lang-native-name">${escapeHtml(lang.native)}</span>
          <span class="lang-english-name">${escapeHtml(window.t('settings_language_' + lang.code))}</span>
        </div>
        <i class="fa-solid fa-circle-check lang-check-icon"></i>
      </button>
    `;
  }).join('');
  if (grid._settingsMarkup !== markup || !grid.childElementCount) {
    grid.innerHTML = markup;
    grid._settingsMarkup = markup;
  }
}
window.renderSettingsLanguageUI = renderSettingsLanguageUI;
window.renderSettings = renderSettings;

