// Location & GPS Settings Toggles
function toggleGpsMetadataSetting(checked) {
  state.gpsMetadataEnabled = !!checked;
  window.MediaMetadata?.onSettingsChanged();
  // This is a preference, not a mutation of a million-item media catalog.
  try { localStorage.setItem('aura_gps_metadata_enabled', checked ? 'true' : 'false'); }
  catch (_) { saveState(true); }
  if (window.AndroidApp && typeof window.AndroidApp.setGpsMetadataEnabled === 'function') {
    try {
      window.AndroidApp.setGpsMetadataEnabled(state.gpsMetadataEnabled);
      if (checked) window.AndroidApp.requestMediaLocationAccess?.();
    } catch (e) {
      console.warn('AndroidApp.setGpsMetadataEnabled failed:', e);
    }
  }
  renderSettings();
  for (const gridId of ['dockPhotoGrid', 'galleryPhotoGrid', 'favoritesPhotoGrid']) {
    const cards = document.getElementById(gridId)?._cardMap;
    if (!cards) continue;
    let remaining = 128;
    for (const card of cards.values()) {
      if (card._metadataPhoto) refreshMediaLocationUI(card._metadataPhoto);
      if (--remaining === 0) break;
    }
  }
  if (state.activePhotoId) {
    const activePhoto = state.photos.find(p => p.id === state.activePhotoId);
    if (activePhoto) {
      renderDetailTags(activePhoto);
    }
  }
  showToast(window.t(checked ? 'settings_enabled' : 'settings_disabled', { setting: window.t('settings_gps_extraction') }));
}

function toggleLocationTagsSetting(checked) {
  state.locationTagsEnabled = !!checked;
  saveState();
  renderSettings();
  renderAll();
  if (state.activePhotoId) {
    const activePhoto = state.photos.find(p => p.id === state.activePhotoId);
    if (activePhoto) {
      renderDetailTags(activePhoto);
      updateDetailModalUI(activePhoto, true);
    }
  }
  showToast(window.t(checked ? 'settings_enabled' : 'settings_disabled', { setting: window.t('settings_location_tags') }));
}

function toggleLocationTagSubSetting(type, checked) {
  if (type === 'place') state.locationTagPlace = !!checked;
  else if (type === 'city') state.locationTagCity = !!checked;
  else if (type === 'country') state.locationTagCountry = !!checked;
  saveState();
  renderSettings();
  renderAll();
  if (state.activePhotoId) {
    const activePhoto = state.photos.find(p => p.id === state.activePhotoId);
    if (activePhoto) {
      renderDetailTags(activePhoto);
      updateDetailModalUI(activePhoto, true);
    }
  }
}

function toggleGalleryLocationBadgeSetting(checked) {
  state.galleryShowLocationBadge = !!checked;
  saveState();
  renderSettings();
  renderAll();
  showToast(window.t(checked ? 'settings_enabled' : 'settings_disabled', { setting: window.t('settings_gallery_location_badges') }));
}

