// USER BUGS & COMMUNITY FEEDBACK (Direct Firebase Integration)
// -------------------------------------------------------------
let currentFeedbackType = 'general';

function updateFeedbackSubjectCounter() {
  const subInput = document.getElementById('feedbackSubjectInput');
  const counter = document.getElementById('feedbackSubjectCounter');
  if (!subInput || !counter) return;

  if (subInput.value.length > 100) {
    subInput.value = subInput.value.substring(0, 100);
  }

  const len = subInput.value.length;
  counter.textContent = `${len} / 100`;
  if (len >= 100) {
    counter.style.color = '#f43f5e';
  } else if (len >= 85) {
    counter.style.color = '#fbbf24';
  } else {
    counter.style.color = 'var(--text-muted)';
  }
}

function updateFeedbackMessageCounter() {
  const msgInput = document.getElementById('feedbackMessageInput');
  const counter = document.getElementById('feedbackMessageCounter');
  if (!msgInput || !counter) return;

  if (msgInput.value.length > 400) {
    msgInput.value = msgInput.value.substring(0, 400);
  }

  const len = msgInput.value.length;
  counter.textContent = `${len} / 400`;
  if (len >= 400) {
    counter.style.color = '#f43f5e';
  } else if (len >= 340) {
    counter.style.color = '#fbbf24';
  } else {
    counter.style.color = 'var(--text-muted)';
  }
}

function openFeedbackModal() {
  const modal = document.getElementById('feedbackModal');
  if (!modal) return;

  // Always re-apply translations to DOM so every title, label, placeholder, and button matches the active language
  if (typeof window.applyTranslationsToDOM === 'function') {
    window.applyTranslationsToDOM();
  }

  // Ensure submit button has localized text and preserves data-i18n attribute
  const submitBtn = document.getElementById('submitFeedbackBtn');
  if (submitBtn) {
    submitBtn.disabled = false;
    submitBtn.innerHTML = `<i class="fa-solid fa-paper-plane"></i> <span data-i18n="feedback_submit_btn">${window.t ? window.t('feedback_submit_btn') : 'Submit Feedback'}</span>`;
  }

  // Reset inputs and counters cleanly
  const subInput = document.getElementById('feedbackSubjectInput');
  const msgInput = document.getElementById('feedbackMessageInput');
  const contactInput = document.getElementById('feedbackContactInput');
  if (subInput) subInput.value = '';
  if (msgInput) msgInput.value = '';
  if (contactInput) contactInput.value = '';
  updateFeedbackSubjectCounter();
  updateFeedbackMessageCounter();

  // First category: General (selected by default)
  selectFeedbackType('general');

  // Diagnostics info
  const diagEl = document.getElementById('feedbackDiagnosticsText');
  if (diagEl) {
    const lang = (window.state && window.state.language) || 'en';
    const os = navigator.userAgent.includes('Android') ? 'Android' : (navigator.platform || 'Device');
    diagEl.textContent = `Aura v2.4.0 · ${os} · Lang: ${lang} · Diagnostics Attached`;
  }

  modal.style.display = 'flex';
  if (subInput) {
    subInput.focus();
  }
}

function closeFeedbackModal() {
  const modal = document.getElementById('feedbackModal');
  if (modal) modal.style.display = 'none';
}

function selectFeedbackType(type) {
  currentFeedbackType = type || 'general';
  const genBtn = document.getElementById('feedbackTypeGeneralBtn');
  const featBtn = document.getElementById('feedbackTypeFeatureBtn');
  const bugBtn = document.getElementById('feedbackTypeBugBtn');

  if (genBtn) genBtn.classList.toggle('active', currentFeedbackType === 'general');
  if (featBtn) featBtn.classList.toggle('active', currentFeedbackType === 'feature');
  if (bugBtn) bugBtn.classList.toggle('active', currentFeedbackType === 'bug');
}

function submitUserFeedback(e) {
  if (e && e.preventDefault) e.preventDefault();

  const subInput = document.getElementById('feedbackSubjectInput');
  const msgInput = document.getElementById('feedbackMessageInput');
  const contactInput = document.getElementById('feedbackContactInput');
  const submitBtn = document.getElementById('submitFeedbackBtn');

  const subject = subInput ? subInput.value.trim() : '';
  const message = msgInput ? msgInput.value.trim() : '';
  const contact = contactInput ? contactInput.value.trim() : '';

  if (!subject || !message) {
    showToast(window.t ? window.t('feedback_validation_required', { defaultValue: 'Please enter a summary and details.' }) : 'Please enter a summary and details.');
    return;
  }

  if (subject.length > 100) {
    showToast('Summary is too long (maximum 100 characters).');
    return;
  }

  if (message.length > 400) {
    showToast('Details cannot exceed 400 characters.');
    return;
  }

  if (submitBtn) {
    submitBtn.disabled = true;
    submitBtn.innerHTML = `<i class="fa-solid fa-spinner fa-spin"></i> <span>...</span>`;
  }

  const feedbackPayload = {
    id: 'fb_' + Date.now() + '_' + Math.random().toString(36).substring(2, 8),
    timestamp: Date.now(),
    isoDate: new Date().toISOString(),
    category: currentFeedbackType,
    subject: subject,
    message: message,
    contactEmail: contact || null,
    deviceInfo: {
      appVersion: '2.4.0',
      language: (window.state && window.state.language) || 'en',
      theme: (window.state && window.state.theme) || 'dark',
      isPro: !!(window.state && window.state.isPro),
      screenResolution: `${window.innerWidth}x${window.innerHeight}`,
      userAgent: navigator.userAgent,
      timeZone: Intl.DateTimeFormat().resolvedOptions().timeZone || 'UTC'
    }
  };

  // Safe local persistence backup: always preserved on-device
  try {
    const history = JSON.parse(localStorage.getItem('aura_submitted_feedback') || '[]');
    history.unshift(feedbackPayload);
    if (history.length > 50) history.pop();
    localStorage.setItem('aura_submitted_feedback', JSON.stringify(history));
  } catch (err) {
    console.warn('Failed to cache feedback locally:', err);
  }

  // 1. Direct REST dispatch to Firebase Realtime Database
  const fbEndpoints = [
    'https://photoorganizer-31cf9-default-rtdb.firebaseio.com/feedback.json',
    'https://photoorganizer-31cf9.firebaseio.com/feedback.json'
  ];

  function tryPostToFirebase(idx = 0) {
    if (idx >= fbEndpoints.length) return;
    fetch(fbEndpoints[idx], {
      method: 'POST',
      headers: { 'Content-Type': 'application/json; charset=utf-8' },
      body: JSON.stringify(feedbackPayload)
    })
      .then(res => {
        if (!res.ok && res.status === 404 && idx === 0) {
          tryPostToFirebase(1);
        } else if (res.ok) {
          console.log('[Feedback] Successfully delivered to Firebase Realtime Database');
        }
      })
      .catch(() => {
        if (idx === 0) tryPostToFirebase(1);
      });
  }
  tryPostToFirebase(0);

  // 2. Dispatch to native Android bridge -> Firebase RTDB
  if (window.AndroidApp && typeof window.AndroidApp.submitFeedbackToFirebase === 'function') {
    try {
      window.AndroidApp.submitFeedbackToFirebase(JSON.stringify(feedbackPayload));
    } catch (err) {
      console.error('AndroidApp.submitFeedbackToFirebase error:', err);
    }
  }

  setTimeout(() => {
    if (submitBtn) {
      submitBtn.disabled = false;
      submitBtn.innerHTML = `<i class="fa-solid fa-paper-plane"></i> <span data-i18n="feedback_submit_btn">${window.t ? window.t('feedback_submit_btn') : 'Submit Feedback'}</span>`;
    }

    if (subInput) subInput.value = '';
    if (msgInput) msgInput.value = '';
    if (contactInput) contactInput.value = '';
    updateFeedbackSubjectCounter();
    updateFeedbackMessageCounter();

    closeFeedbackModal();

    const successMsg = window.t ? window.t('feedback_toast_success') : 'Your feedback has been submitted successfully!';
    showToast(successMsg);
  }, 400);
}

window.openFeedbackModal = openFeedbackModal;
window.closeFeedbackModal = closeFeedbackModal;
window.selectFeedbackType = selectFeedbackType;
window.submitUserFeedback = submitUserFeedback;
window.updateFeedbackSubjectCounter = updateFeedbackSubjectCounter;
window.updateFeedbackMessageCounter = updateFeedbackMessageCounter;

// Helper: Get filtered suggested location tags for a photo based on user settings
const locationResolutionJobs = new WeakSet();
const locationResolutionRetry = new WeakMap();
function persistResolvedMediaLocation(photo) {
  const checkpoint = window.MediaMetadata?.persistLocation?.(photo);
  if (checkpoint) Promise.resolve(checkpoint).then(saved => { if (!saved) saveState(true); }).catch(() => saveState(true));
  else saveState(true);
}
// Patch location affordances only; preserve the mounted card, image and controls.
function refreshMediaLocationUI(photo) {
  if (!photo) return;
  const loc = photo.location;
  const label = loc && (loc.city || loc.place || loc.country || loc.displayCoords || '');
  const suggestions = getSuggestedLocationTagsForPhoto(photo);
  for (const gridId of ['dockPhotoGrid', 'galleryPhotoGrid', 'favoritesPhotoGrid']) {
    const card = document.getElementById(gridId)?._cardMap?.get(photo.id);
    if (!card) continue;
    const dock = card.classList.contains('dock-card');
    const pillClass = dock ? 'dock-location-pill' : 'card-loc-pill';
    let pill = card.querySelector('.' + pillClass);
    if (state.galleryShowLocationBadge === true && label) {
      if (!pill) {
        pill = document.createElement('span'); pill.className = pillClass;
        if (!dock) pill.onclick = event => { event.stopPropagation(); openPhotoDetail(photo.id); };
        const parent = card.querySelector(dock ? '.card-image-box' : '.card-meta-row');
        if (parent) parent.prepend(pill);
      }
      pill.title = label;
      pill.innerHTML = '<i class="fa-solid fa-location-dot"></i> ' + escapeHtml(label);
    } else pill?.remove();
    if (dock) {
      let tags = card.querySelector('.dock-card-tags');
      tags?.querySelectorAll('.loc-suggestion-chip').forEach(chip => chip.remove());
      if (suggestions.length && !tags) {
        tags = document.createElement('div'); tags.className = 'dock-card-tags';
        card.insertBefore(tags, card.querySelector('.dock-card-action-suite'));
      }
      for (const suggestion of suggestions) {
        const added = photo.tags?.some(tag => tag.toLowerCase() === suggestion.label.toLowerCase());
        const button = document.createElement('button');
        button.className = 'photo-chip loc-suggestion-chip' + (added ? ' added' : '');
        button.innerHTML = '<i class="fa-solid ' + (added ? 'fa-check' : 'fa-location-dot') + '"></i> ' + escapeHtml(suggestion.label);
        button.onclick = event => { event.stopPropagation(); toggleLocationSuggestionForPhoto(photo.id, suggestion.label); };
        tags.appendChild(button);
      }
      if (tags && !tags.children.length) tags.remove();
    }
  }
  if (state.activePhotoId === photo.id) renderDetailTags(photo);
}
window.refreshMediaLocationUI = refreshMediaLocationUI;

function getSuggestedLocationTagsForPhoto(photo) {
  window.MediaMetadata?.request(photo);
  // If GPS extraction is off OR location tags suggestions is off, return NO suggestions
  if (state.gpsMetadataEnabled === false || state.locationTagsEnabled === false) return [];
  if (!photo || !photo.location) return [];
  const anyLocationTag = state.locationTagPlace !== false || state.locationTagCity !== false || state.locationTagCountry !== false;
  if (!anyLocationTag) return [];

  const loc = photo.location;
  const suggestions = [];

  if (state.locationTagPlace !== false && loc.place && typeof loc.place === 'string' && loc.place.trim()) {
    suggestions.push({ type: 'place', label: loc.place.trim() });
  }
  if (state.locationTagCity !== false && loc.city && typeof loc.city === 'string' && loc.city.trim()) {
    const city = loc.city.trim();
    if (!suggestions.some(s => s.label.toLowerCase() === city.toLowerCase())) {
      suggestions.push({ type: 'city', label: city });
    }
  }
  if (state.locationTagCountry !== false && loc.country && typeof loc.country === 'string' && loc.country.trim()) {
    const country = loc.country.trim();
    if (!suggestions.some(s => s.label.toLowerCase() === country.toLowerCase())) {
      suggestions.push({ type: 'country', label: country });
    }
  }

  // If coordinates exist and no named suggestion was found yet, offer coordinate tag
  if (suggestions.length === 0 && typeof loc.latitude === 'number' && typeof loc.longitude === 'number') {
    const coordsStr = loc.displayCoords || formatDisplayCoords(loc.latitude, loc.longitude);
    if (coordsStr) {
      suggestions.push({ type: 'coords', label: coordsStr });
    }
  }

  // Resolve names once per location; settings changes and manual edits win.
  if (anyLocationTag && Number.isFinite(loc.latitude) && Number.isFinite(loc.longitude) &&
      !loc.place && !loc.city && !loc.country && !locationResolutionJobs.has(loc) &&
      Date.now() >= (locationResolutionRetry.get(loc) || 0)) {
    locationResolutionJobs.add(loc);
    resolveLocationFromCoords(loc.latitude, loc.longitude).then(res => {
      if (photo.location !== loc || state.gpsMetadataEnabled === false || state.locationTagsEnabled === false) return;
      if (res && (res.place || res.city || res.country)) {
        photo.location = res;
        persistResolvedMediaLocation(photo);
        refreshMediaLocationUI(photo);
      } else locationResolutionRetry.set(loc, Date.now() + 60000);
    }).catch(() => { locationResolutionRetry.set(loc, Date.now() + 60000); })
      .finally(() => locationResolutionJobs.delete(loc));
  }

  return suggestions;
}
window.getSuggestedLocationTagsForPhoto = getSuggestedLocationTagsForPhoto;

// Helper: One-tap toggle to add or remove a location tag from a photo
function toggleLocationSuggestionForPhoto(photoId, tagName) {
  const photo = state.photos.find(p => p.id === photoId);
  if (!photo) return;
  if (!Array.isArray(photo.tags)) photo.tags = [];

  const cleanName = tagName.trim();
  const existingIdx = photo.tags.findIndex(t => t.toLowerCase() === cleanName.toLowerCase());

  if (existingIdx !== -1) {
    // Remove tag
    const removed = photo.tags.splice(existingIdx, 1)[0];
    saveState();
    if (state.activePhotoId === photoId) {
      renderDetailTags(photo);
    }
    renderAll();
    showToast(`Removed tag '${removed}'`);
  } else {
    // Add tag
    photo.tags.push(cleanName);
    // Ensure tag exists in global tags list
    if (!state.tags.some(t => t.name.toLowerCase() === cleanName.toLowerCase())) {
      const now = Date.now();
      state.tags.push({
        name: cleanName,
        color: PRESET_COLORS[Math.floor(Math.random() * PRESET_COLORS.length)],
        createdAt: now,
        lastModifiedAt: now,
        lastViewedAt: now,
        photoCount: 1
      });
    }
    saveState();
    if (state.activePhotoId === photoId) {
      renderDetailTags(photo);
    }
    renderAll();
    showToast(`Added location tag '${cleanName}'`);
  }
}
window.toggleLocationSuggestionForPhoto = toggleLocationSuggestionForPhoto;

// Storage Management Handlers
function clearAppCache() {
  showToast(window.t('settings_cache_cleaning'));
  if (window.AndroidApp && typeof window.AndroidApp.clearCache === 'function') {
    try { window.AndroidApp.clearCache(); } catch (_) { }
  }
  setTimeout(() => {
    showToast(window.t('settings_cache_cleared'));
    renderSettings();
  }, 400);
}

function emptyTrashFromSettings() {
  emptyTrash();
  renderSettings();
}

// Settings > Export / Import Backup (library_backup.js). A backup holds albums, favorites,
// Dock / Gallery / Trash status and names; import matches it to media already in the library
// and only adds or restores, after a preview, with Undo.
function exportFullDataBackup() {
  window.PicShelfBackup?.exportBackup();
}

function importFullDataBackup(event) {
  const input = event?.target;
  const file = input?.files?.[0];
  // Clear the input so choosing the same file again still opens the backup.
  if (input) input.value = '';
  if (file) window.PicShelfBackup?.importFile(file);
}

// A restored backup changes many items at once: rebuild every derived screen list.
window.refreshAfterLibraryRestore = function () {
  window.LibraryViews?.invalidate();
  _cachedGalleryPhotos = [];
  _cachedDockPhotos = [];
  _cachedTrashPhotos = [];
};

function renderNavBadges() {
  const pendingCount = window.LibraryViews.get(state).pending.length;
  // Albums are groupings of these same media, not additional deleted files.
  const trashCount = window.LibraryViews.get(state).trash.length;

  const dockBadge = document.getElementById('dockNavBadge');
  if (pendingCount > 0) {
    dockBadge.style.display = 'flex';
    dockBadge.textContent = pendingCount;
  } else {
    dockBadge.style.display = 'none';
  }

  const trashBadge = document.getElementById('trashNavBadge');
  if (trashCount > 0) {
    trashBadge.style.display = 'flex';
    trashBadge.textContent = trashCount;
  } else {
    trashBadge.style.display = 'none';
  }

  const favCount = window.LibraryViews.get(state).favorites.length;
  const favBadge = document.getElementById('favNavBadge');
  if (favBadge) {
    if (favCount > 0) {
      favBadge.style.display = 'flex';
      favBadge.textContent = favCount;
    } else {
      favBadge.style.display = 'none';
    }
  }

  // If user is currently viewing a specific album, ensure Albums tab in bottom dock remains highlighted
  if (state.activeAlbumView) {
    document.querySelectorAll('.nav-item').forEach(i => i.classList.remove('active'));
    document.querySelector('.nav-item[data-tab="albumsScreen"]')?.classList.add('active');
  }
}

// -------------------------------------------------------------
// PRO FEATURE: FREE PLAN 40 PHOTOS SAVE LIMIT IN GALLERY & ALBUMS
// -------------------------------------------------------------
const FREE_GALLERY_SAVE_LIMIT = 40;

function getSavedPhotosCount() {
  return window.LibraryViews.get(state).saved.length;
}

function getGallerySaveQuotaCount() {
  const views = window.LibraryViews.get(state);
  let count = Math.min(views.saved.length, FREE_GALLERY_SAVE_LIMIT + 1);
  // Favorites can include Dock items. Count that union without moving them or
  // scanning the unselected Dock. Backup IDs need not be unique; count records.
  if (count > FREE_GALLERY_SAVE_LIMIT) return count;
  for (const photo of views.favorites) {
    if (photo.isPending) count++;
    if (count > FREE_GALLERY_SAVE_LIMIT) return count;
  }
  return count;
}

function hasUnlimitedGallerySaves() {
  return window.PicShelfBilling ? window.PicShelfBilling.hasPro() : !!state.isPro;
}

function checkCanSavePhotosToGallery(countToSave = 1) {
  countToSave = Math.max(0, Number(countToSave) || 0);
  // Existing saved items can still be organized, including after Pro expires.
  if (countToSave === 0) return true;
  if (hasUnlimitedGallerySaves()) return true;
  const currentSaved = getGallerySaveQuotaCount();
  if (currentSaved + countToSave > FREE_GALLERY_SAVE_LIMIT) {
    openVipSaveLimitModal({ currentSaved, countToSave, limit: FREE_GALLERY_SAVE_LIMIT });
    return false;
  }
  return true;
}

function countPendingMediaToSave(photoIds) {
  const selected = photoIds instanceof Set ? photoIds : new Set(photoIds || []);
  let count = 0;
  for (const photo of window.LibraryViews.get(state).pending) {
    if (selected.has(photo.id) && !photo.isFavorite) count++;
  }
  return count;
}

function countSavedMediaToRestore(photos) {
  let count = 0;
  for (const photo of photos) {
    if (photo.deletedAt && (!photo.isPending || photo.isFavorite)) count++;
  }
  return count;
}

function openVipSaveLimitModal(details) {
  window.PicShelfBilling.open();
}

function closeVipSaveLimitModal() {
  window.PicShelfBilling?.cancelPendingCheckout();
  const modal = document.getElementById('vipSaveLimitModal');
  if (modal) modal.style.display = 'none';
  // Back in an open 3D Studio: show its Pro state as of now (e.g. just purchased).
  if (document.getElementById('album3DSurfaceModal')?.style.display === 'flex') render3DStudioProControls();
  if (state.moveCopyIsAlbumMode) {
    const targetAlbum = state.moveCopySourceAlbum;
    state.moveCopySourceAlbum = null;
    state.moveCopyIsAlbumMode = false;
    if (targetAlbum && window.highlightReturnedAlbumCard) {
      window.highlightReturnedAlbumCard(targetAlbum);
    }
  }
}
window.FREE_GALLERY_SAVE_LIMIT = FREE_GALLERY_SAVE_LIMIT;
window.getSavedPhotosCount = getSavedPhotosCount;
window.checkCanSavePhotosToGallery = checkCanSavePhotosToGallery;
window.openVipSaveLimitModal = openVipSaveLimitModal;
window.closeVipSaveLimitModal = closeVipSaveLimitModal;

// 1. Render Loading Dock (Decoupled Virtual Windowing for 200,000+ Photos)
let _dockVisibleStart = 0;
let _dockRowHeight = 330;
let _dockRowHeightMeasured = false;
let _cachedDockPhotos = [];
const DOCK_NATIVE_WINDOW_SIZE = 48;
let _dockLastLogicalScroll = 0;

let _galleryRowHeightMeasured = false;
let _trashRowHeightMeasured = false;

window.addEventListener('resize', () => {
  _galleryRowHeightMeasured = false;
  _dockRowHeightMeasured = false;
  _trashRowHeightMeasured = false;
}, { passive: true });


// =============================================================
// HIGH-PERFORMANCE THUMBNAIL CACHE & SAFE OBJECT-URL LIFECYCLE
// =============================================================
const _thumbMemoryCache = new Map(); // id -> blobUrl
const MAX_MEMORY_THUMBS = 8000;

const MAX_ACTIVE_OBJECT_URLS = 8000;
const _activeObjectUrlMap = new Map(); // id -> blobUrl
const _activeObjectUrlOrder = [];

function trackActiveObjectUrl(id, url) {
  if (!id || !url) return;
  _activeObjectUrlMap.set(id, url);
  _activeObjectUrlOrder.push(id);
  if (_activeObjectUrlOrder.length > MAX_ACTIVE_OBJECT_URLS * 1.5) {
    pruneOldObjectUrls();
  }
}
window._trackActiveObjectUrl = trackActiveObjectUrl;

function pruneOldObjectUrls() {
  if (_activeObjectUrlOrder.length <= MAX_ACTIVE_OBJECT_URLS) return;
  const mountedIds = new Set();
  document.querySelectorAll('.photo-card-elegant[data-id], .dock-card[data-id], .trash-card[data-id]').forEach(el => {
    if (el.dataset.id) mountedIds.add(el.dataset.id);
  });

  const nextOrder = [];
  for (let i = 0; i < _activeObjectUrlOrder.length; i++) {
    const id = _activeObjectUrlOrder[i];
    if (mountedIds.has(id)) {
      nextOrder.push(id);
    } else if (nextOrder.length + (_activeObjectUrlOrder.length - i) > MAX_ACTIVE_OBJECT_URLS) {
      // Bounded eviction: only drop from object url map, keep thumb in memory cache if needed
      _activeObjectUrlMap.delete(id);
    } else {
      nextOrder.push(id);
    }
  }
  _activeObjectUrlOrder.length = 0;
  _activeObjectUrlOrder.push(...nextOrder);
}

function getCachedThumbnail(id) {
  if (!id) return null;
  return _thumbMemoryCache.get(id) || null;
}
window.getCachedThumbnail = getCachedThumbnail;

function setCachedThumbnail(id, url) {
  if (!id || !url) return;
  if (_thumbMemoryCache.size >= MAX_MEMORY_THUMBS) {
    const firstKey = _thumbMemoryCache.keys().next().value;
    if (firstKey) _thumbMemoryCache.delete(firstKey);
  }
  _thumbMemoryCache.set(id, url);
}
window.setCachedThumbnail = setCachedThumbnail;

// Playback URLs are hydrated after indexing; keep cached media summaries in sync.
function setPhotoPlaybackUrl(photo, url) {
  const changedPresence = !!photo.videoUrl !== !!url;
  const previousView = changedPresence ? window.LibraryViews?.capture(photo) : null;
  photo.videoUrl = url;
  if (previousView) window.LibraryViews.update(state, photo, previousView);
}

function ensurePhotoDataUrlSync(photo) {
  if (!photo) return null;
  const resumePreview = window.VideoCardPreviews?.cardSource(photo);
  if (resumePreview) return resumePreview;
  if (window.ArchiveVideoPreviews?.supports(photo)) return window.ArchiveVideoPreviews.get(photo);
  if (photo.thumbUrl && !photo.thumbUrl.startsWith('data:image/svg')) return photo.thumbUrl;
  if (photo.dataUrl && !photo.dataUrl.startsWith('data:image/svg')) return photo.dataUrl;

  const cached = getCachedThumbnail(photo.id);
  if (cached) {
    photo.thumbUrl = cached;
    return cached;
  }

  const retainedUrl = !photo.lastEditedAt && window.ArchiveSources?.originalUrl(photo);
  if (retainedUrl) {
    photo.dataUrl = retainedUrl;
    photo.thumbUrl = retainedUrl;
    if (photo.mediaType === 'audio') setPhotoPlaybackUrl(photo, retainedUrl);
    setCachedThumbnail(photo.id, retainedUrl);
    return retainedUrl;
  }

  // Fast synchronous slice for TAR archives (0.005ms)
  if (photo.tarEntry && photo.tarEntry.tarFile) {
    try {
      const { tarFile, offset, size, baseName } = photo.tarEntry;
      if (tarFile && size > 0) {
        const mime = typeof guessMimeTypeFromFilename === 'function' ? guessMimeTypeFromFilename(baseName) : 'image/jpeg';
        const slice = tarFile.slice(offset, offset + size, mime);
        const url = URL.createObjectURL(slice);
        photo.dataUrl = url;
        photo.fileBlob = slice;
        photo.thumbUrl = url;
        trackActiveObjectUrl(photo.id, url);
        setCachedThumbnail(photo.id, url);
        return url;
      }
    } catch (_) {}
  }

  // Fast synchronous slice for uncompressed (STORE / method 0) ZIP entries
  if (photo.zipEntry && photo.zipEntry.zipFile && photo.zipEntry.method === 0) {
    try {
      const { zipFile, localOffset, compSize, baseName } = photo.zipEntry;
      const dataStart = 30 + (photo.zipEntry.fnLen || (photo.zipEntry.fn ? photo.zipEntry.fn.length : 128)) + (photo.zipEntry.extraLen || 0);
      const mime = typeof guessMimeTypeFromFilename === 'function' ? guessMimeTypeFromFilename(baseName) : 'image/jpeg';
      const slice = zipFile.slice(localOffset + dataStart, localOffset + dataStart + compSize, mime);
      const url = URL.createObjectURL(slice);
      photo.dataUrl = url;
      photo.fileBlob = slice;
      photo.thumbUrl = url;
      trackActiveObjectUrl(photo.id, url);
      setCachedThumbnail(photo.id, url);
      return url;
    } catch (_) {}
  }

  return null;
}
window.ensurePhotoDataUrlSync = ensurePhotoDataUrlSync;

// Self-Healing Image Error Recovery Handler
function handleCardImageError(imgEl, photoId) {
  if (!imgEl || !photoId) return;
  if (recoverResizedImageCardPreview(imgEl)) return;
  if (window.GalleryThumbnails?.handleError(imgEl, photoId)) return;
  imgEl._recoveryCount = (imgEl._recoveryCount || 0) + 1;
  if (imgEl._recoveryCount > 3) {
    imgEl.src = ZIP_PLACEHOLDER_DATA_URL;
    return;
  }

  _activeObjectUrlMap.delete(photoId);
  _thumbMemoryCache.delete(photoId);
  const photo = (typeof state !== 'undefined' && state.photos) ? state.photos.find(x => x.id === photoId) : null;
  if (!photo) return;

  if (photo.thumbUrl && photo.thumbUrl.startsWith('blob:')) {
    try { URL.revokeObjectURL(photo.thumbUrl); } catch (_) {}
  }
  photo.thumbUrl = null;
  photo.dataUrl = null;
  photo.fileBlob = null;

  imgEl.src = ZIP_PLACEHOLDER_DATA_URL;
  imgEl.classList.add('zip-deferred-thumb');

  if (typeof resolveZipPhotoDataUrl === 'function') {
    resolveZipPhotoDataUrl(photo).then(freshUrl => {
      if (freshUrl && imgEl) {
        imgEl.src = freshUrl;
        imgEl.classList.remove('zip-deferred-thumb');
      }
    }).catch(() => {});
  }
}
window.handleCardImageError = handleCardImageError;

// Viewport-only thumbnail scheduler.  Archive work is intentionally bounded: on
// Android WebView, allowing old fling requests to keep inflating images starves
// the compositor and leaves a black grid until every stale job completes.
let _thumbnailWorkGeneration = 0;

function hasDeferredArchiveThumbnail(photo) {
  return !!photo && (!photo.thumbUrl || photo.thumbUrl.startsWith('data:image/svg')) &&
    !!(photo.zipEntry || photo.tarEntry);
}

function schedulePrioritizedDecompression(visibleSlice, grid, cardSelector = '.photo-card-elegant', targetCenter = -1) {
  if (!visibleSlice || !grid || !visibleSlice.length) return;
  if (grid.id === 'dockPhotoGrid' && window.ArchiveVideoPreviews) {
    window.ArchiveVideoPreviews.scheduleDock(visibleSlice, grid, targetCenter);
    visibleSlice = visibleSlice.filter(photo => !window.ArchiveVideoPreviews.supports(photo));
    if (!visibleSlice.length) return;
  }
  if ((grid.id === 'galleryPhotoGrid' || (window.AndroidApp && grid.id === 'dockPhotoGrid')) && window.GalleryThumbnails) {
    window.GalleryThumbnails.schedule(visibleSlice, grid, Math.max(0, targetCenter));
    visibleSlice = visibleSlice.filter(photo => !window.GalleryThumbnails.supports(photo));
    if (!visibleSlice.length) return;
  }
  const generation = ++_thumbnailWorkGeneration;

  let center = targetCenter;
  if (center < 0) {
    const viewport = document.querySelector('.app-viewport') || document.documentElement;
    const scrollTop = (viewport && viewport.scrollTop !== undefined) ? viewport.scrollTop : (window.scrollY || 0);
    const relativeScroll = Math.max(0, scrollTop - (grid.offsetTop || 0));
    const rowHeight = (cardSelector === '.dock-card' ? _dockRowHeight :
      (cardSelector === '.trash-card' ? _trashRowHeight : _galleryRowHeight)) || 300;
    center = (Math.floor(relativeScroll / rowHeight) + 2) * 2;
  }

  const pending = visibleSlice
    .filter(hasDeferredArchiveThumbnail)
    .sort((a, b) => Math.abs((a._globalIndex || 0) - center) - Math.abs((b._globalIndex || 0) - center));
  if (!pending.length) return;

  // TAR and STORE-ZIP files can produce an object URL without inflating data.
  // Warm the actual viewport first (rather than the start of the virtual
  // window) so a fling always lands on real cards immediately.
  for (const photo of pending.slice(0, 24)) {
    if (photo.tarEntry || (photo.zipEntry && photo.zipEntry.method === 0)) {
      ensurePhotoDataUrlSync(photo);
    }
  }

  // Do not inflate compressed archives while fingers are moving. The next
  // stationary pass is scheduled by handleAppViewportScroll, so this does not
  // leave the current screen permanently deferred.
  if (document.body.classList.contains('is-scrolling')) return;

  const updateCardImage = (photo, url) => {
    if (!url || generation !== _thumbnailWorkGeneration) return;
    const card = grid._cardMap ? grid._cardMap.get(photo.id) : grid.querySelector(`${cardSelector}[data-id="${photo.id}"]`);
    const image = card && card.querySelector('img');
    if (image && (image.src.includes('data:image/svg') || image.classList.contains('zip-deferred-thumb') || !image.src || image.src.endsWith('/'))) {
      image.src = photo.thumbUrl || url;
      image.classList.remove('zip-deferred-thumb');
    }
  };

  // Eight near-viewport decodes are enough for a phone screen. A small second
  // batch gives forward look-ahead without monopolising WebView's JS thread.
  const process = async (batch) => {
    for (const photo of batch) {
      if (generation !== _thumbnailWorkGeneration || document.body.classList.contains('is-scrolling')) return;
      try {
        updateCardImage(photo, await resolveZipPhotoDataUrl(photo));
      } catch (_) {}
      await new Promise(resolve => setTimeout(resolve, 0));
    }
  };

  process(pending.slice(0, 8)).then(() => {
    if (generation === _thumbnailWorkGeneration && !document.body.classList.contains('is-scrolling')) {
      return process(pending.slice(8, 16));
    }
  });
}

function renderSingleDockCardHtml(photo, labels = {}) {
  const isSelected = state.selectedDockPhotoIds.has(photo.id);
  const locSuggestions = getSuggestedLocationTagsForPhoto(photo);
  const suggestedChipsHtml = locSuggestions.map(s => {
    const isAdded = Array.isArray(photo.tags) && photo.tags.some(t => t.toLowerCase() === s.label.toLowerCase());
    return `
      <button class="photo-chip loc-suggestion-chip ${isAdded ? 'added' : ''}" 
              onclick="event.stopPropagation(); toggleLocationSuggestionForPhoto('${photo.id}', '${escapeJs(s.label)}')" 
              title="${isAdded ? 'Click to remove tag' : 'Click to add location tag'}">
        <i class="fa-solid ${isAdded ? 'fa-check' : 'fa-location-dot'}"></i> ${escapeHtml(s.label)}
      </button>
    `;
  }).join('');

  const photoTags = Array.isArray(photo.tags) ? photo.tags : [];
  const tagHtml = (photoTags.length > 0 || locSuggestions.length > 0)
    ? `<div class="dock-card-tags">${photoTags.map(t => `<span class="photo-chip">${escapeHtml(t)}</span>`).join('')}${suggestedChipsHtml}</div>`
    : '';

  const pendingLabel = labels.pendingLabel || (window.t ? window.t('dock_card_pending') : 'Pending');
  const albumLabel = labels.albumLabel || (window.t ? window.t('dock_card_album') : 'Album');
  const saveLabel = labels.saveLabel || (window.t ? window.t('dock_card_save') : 'Save');
  const renameLabel = labels.renameLabel || (window.t ? window.t('dock_card_rename') : 'Rename');
  const trashLabel = labels.trashLabel || (window.t ? window.t('dock_card_trash') : 'Trash');

  const usesDockPreview = window.AndroidApp && window.GalleryThumbnails?.supports(photo);
  const syncUrl = window.ArchiveVideoPreviews?.supports(photo) ? window.ArchiveVideoPreviews.get(photo, false) : usesDockPreview ? window.GalleryThumbnails.get(photo) :
    ((typeof ensurePhotoDataUrlSync === 'function') ? ensurePhotoDataUrlSync(photo) : null);
  const imgSrc = usesDockPreview ? (syncUrl || ZIP_PLACEHOLDER_DATA_URL) :
    (syncUrl || photo.thumbUrl || photo.dataUrl || ZIP_PLACEHOLDER_DATA_URL);
  const isDeferred = (!imgSrc || imgSrc.startsWith('data:image/svg')) && (!!photo.zipEntry || !!photo.tarEntry);

  return `
    <div class="photo-card-elegant dock-card ${isSelected ? 'selected' : ''}" onclick="toggleDockSelect('${photo.id}')" data-id="${photo.id}">
      <div class="card-image-box">
        <img src="${escapeHtml(imgSrc)}" alt="${escapeHtml(photo.displayName || 'Photo')}" decoding="async" ${usesDockPreview ? 'loading="lazy"' : ''} class="${isDeferred ? 'zip-deferred-thumb' : ''}" onerror="if(this.isConnected && window.handleCardImageError) handleCardImageError(this, '${photo.id}')">
        <span class="dock-staging-pill">
          <span class="staging-pulse-dot"></span>
          <span>${pendingLabel}</span>
        </span>
        ${(photo.mediaType === 'video' || (photo.displayName && photo.displayName.match(/\.(mp4|webm|mov|m4v)$/i))) ? `
          <span class="card-video-pill">
            <i class="fa-solid fa-play"></i>
            <span>${window.ArchiveVideoPreviews?.supports(photo) ? window.ArchiveVideoPreviews.durationLabel(photo) : formatDuration(photo.duration || 6)}</span>
          </span>
        ` : (photo.mediaType === 'audio' || (photo.displayName && photo.displayName.match(/\.(mp3|wav|m4a|aac|ogg|flac|wma)$/i))) ? `
          <span class="card-video-pill" style="background: rgba(147, 51, 234, 0.88);">
            <i class="fa-solid fa-music"></i>
            <span>${formatDuration(photo.duration || 0)}</span>
          </span>
        ` : ''}
        ${(state.galleryShowLocationBadge === true && photo.location && typeof photo.location.latitude === 'number') ? `
          <span class="dock-location-pill" title="Location: ${escapeHtml(photo.location.city || photo.location.place || photo.location.country || photo.location.displayCoords || formatDisplayCoords(photo.location.latitude, photo.location.longitude))}">
            <i class="fa-solid fa-location-dot"></i> ${escapeHtml(photo.location.city || photo.location.place || photo.location.country || photo.location.displayCoords || formatDisplayCoords(photo.location.latitude, photo.location.longitude))}
          </span>
        ` : ''}
        <button class="card-preview-btn" onclick="event.stopPropagation(); openPhotoDetail('${photo.id}')" title="${escapeHtml(photo.displayName || 'Photo')}">
          <i class="fa-solid fa-expand"></i>
        </button>
        <div class="card-select-check ${isSelected ? 'checked' : ''}">
          ${isSelected ? '<i class="fa-solid fa-check"></i>' : ''}
        </div>
        <div class="card-overlay-bottom">
          <span class="card-title" onclick="event.stopPropagation(); openRenamePhotoModal('${photo.id}')" title="${escapeHtml(photo.displayName || 'Photo')}">
            ${escapeHtml(photo.displayName || 'Photo')} <i class="fa-solid fa-pen" style="font-size:10px; opacity:0.75; margin-left:4px;"></i>
          </span>
        </div>
      </div>
      ${tagHtml}
      <div class="dock-card-action-suite">
        <div class="dock-action-row dock-action-row-primary">
          <button class="btn-dock-lux btn-dock-album" onclick="event.stopPropagation(); openBatchTagModal(['${photo.id}'])" title="${albumLabel}">
            <i class="fa-solid fa-folder-plus"></i><span>${albumLabel}</span>
          </button>
          <button class="btn-dock-lux btn-dock-save" onclick="event.stopPropagation(); movePhotoToGallery('${photo.id}')" title="${saveLabel}">
            <i class="fa-solid fa-wand-magic-sparkles"></i><span>${saveLabel}</span>
          </button>
        </div>
        <div class="dock-action-row dock-action-row-sub">
          <button class="btn-dock-lux-sub btn-dock-rename" onclick="event.stopPropagation(); openRenamePhotoModal('${photo.id}')" title="${renameLabel}">
            <i class="fa-solid fa-pen-nib"></i><span>${renameLabel}</span>
          </button>
          <button class="btn-dock-lux-sub btn-dock-trash" onclick="event.stopPropagation(); moveToTrash('${photo.id}', false, true)" title="${trashLabel}">
            <i class="fa-solid fa-trash-can"></i><span>${trashLabel}</span>
          </button>
        </div>
      </div>
    </div>
  `;
}

// Ultra-fast dock slice render with incremental DOM reconciliation: runs in 0.05ms on scroll tick!

// =========================================================================
// HIGH-PERFORMANCE VIRTUALIZED GRID DOM RECONCILIATION
// Eliminates grid.innerHTML destruction, prevents tile invalidation & blank screens
// =========================================================================
function reconcileVirtualizedGrid(grid, visibleSlice, renderCardHtmlFn, topHeight, bottomHeight, cardSelector) {
  if (!grid) return;
  if (grid.id === 'galleryPhotoGrid' && window.GalleryViewport?.reconcile(
    grid, visibleSlice, renderCardHtmlFn, topHeight, bottomHeight, cardSelector,
    reconcileVirtualizedGrid, _galleryRowHeight || 300)) return;
  if (grid.id === 'dockPhotoGrid' && window.GalleryViewport?.reconcile(
    grid, visibleSlice, renderCardHtmlFn, topHeight, bottomHeight, cardSelector,
    reconcileVirtualizedGrid, _dockRowHeight || 330)) return;

  // 1. Ensure top and bottom spacers exist
  let topSpacer = grid.querySelector('.grid-spacer-top');
  let bottomSpacer = grid.querySelector('.grid-spacer-bottom');

  if (!topSpacer) {
    topSpacer = document.createElement('div');
    topSpacer.className = 'grid-spacer grid-spacer-top';
    topSpacer.style.gridColumn = '1 / -1';
    topSpacer.style.pointerEvents = 'none';
    grid.prepend(topSpacer);
  }
  if (!bottomSpacer) {
    bottomSpacer = document.createElement('div');
    bottomSpacer.className = 'grid-spacer grid-spacer-bottom';
    bottomSpacer.style.gridColumn = '1 / -1';
    bottomSpacer.style.pointerEvents = 'none';
    grid.append(bottomSpacer);
  }

  // 2. Adjust spacer heights and display
  topSpacer.style.height = topHeight + 'px';
  topSpacer.style.display = topHeight > 0 ? 'block' : 'none';
  bottomSpacer.style.height = bottomHeight + 'px';
  bottomSpacer.style.display = bottomHeight > 0 ? 'block' : 'none';

  if (!grid._cardMap) grid._cardMap = new Map();

  // 3. Track needed photo IDs in current viewport window
  const neededIds = new Set();
  for (let i = 0; i < visibleSlice.length; i++) {
    neededIds.add(visibleSlice[i].id);
  }

  // 4. Smoothly remove only the cards that fell outside the window
  const toDelete = [];
  grid._cardMap.forEach((card, id) => {
    if (!neededIds.has(id)) {
      if (card.parentNode === grid) {
        if (grid.id === 'galleryPhotoGrid' || grid.dataset.galleryViewport) {
          // Detached images can otherwise keep consuming the content-provider
          // read/decode queue after a fling has moved to different photos.
          const image = card.querySelector('img');
          if (image && (grid.dataset.trashViewport || !window.GalleryThumbnails?.retain(image))) image.removeAttribute('src');
        }
        card.remove();
      }
      toDelete.push(id);
    }
  });
  for (let i = 0; i < toDelete.length; i++) {
    grid._cardMap.delete(toDelete[i]);
  }

  // 5. Create newly entering cards
  const missingPhotos = [];
  for (let i = 0; i < visibleSlice.length; i++) {
    const photo = visibleSlice[i];
    if (!grid._cardMap.has(photo.id)) {
      missingPhotos.push(photo);
    }
  }

  if (missingPhotos.length > 0) {
    const tempDiv = document.createElement('div');
    tempDiv.innerHTML = missingPhotos.map(p => renderCardHtmlFn(p)).join('');
    const newCards = Array.from(tempDiv.children);
    for (let i = 0; i < missingPhotos.length; i++) {
      const card = newCards[i];
      if (card) {
        renderCardHtmlFn.attachImageSource?.(card, missingPhotos[i]);
        grid._cardMap.set(missingPhotos[i].id, card);
      }
    }
  }

  // 6. Ensure correct sequential order of cards between topSpacer and bottomSpacer
  let currentChild = topSpacer.nextSibling;
  for (let i = 0; i < visibleSlice.length; i++) {
    const photo = visibleSlice[i];
    const card = grid._cardMap.get(photo.id);
    if (!card) continue;
    card._metadataPhoto = photo;
    syncResizedImageCardPreview(card, photo);
    if (currentChild !== card) {
      grid.insertBefore(card, currentChild || bottomSpacer);
    } else {
      currentChild = currentChild.nextSibling;
    }
  }
  window.MediaMetadata?.schedule(visibleSlice);
}
window.reconcileVirtualizedGrid = reconcileVirtualizedGrid;

function renderDockWindow(options = {}) {
  const grid = document.getElementById('dockPhotoGrid');
  if (!grid) return;
  const pendingPhotos = _cachedDockPhotos;
  const total = pendingPhotos.length;
  if (total === 0) {
    grid.innerHTML = '';
    if (grid._cardMap) grid._cardMap.clear();
    window.GalleryViewport?.clear(grid);
    _dockVisibleStart = 0;
    return;
  }
  const WINDOW_SIZE = window.AndroidApp ? DOCK_NATIVE_WINDOW_SIZE : 160;

  if (options.resetScroll || _dockVisibleStart >= total) {
    _dockVisibleStart = 0;
    _dockLastLogicalScroll = 0;
    window.GalleryViewport?.reset(grid);
  }

  const maxStart = Math.max(0, (window.AndroidApp ? Math.ceil : Math.floor)(Math.max(0, total - WINDOW_SIZE) / 2) * 2);
  const safeStart = Math.min(maxStart, Math.max(0, Math.floor(_dockVisibleStart / 2) * 2));
  const startIdx = safeStart;
  const endIdx = Math.min(total, startIdx + WINDOW_SIZE);
  const rowsAbove = Math.floor(startIdx / 2);
  const rowsBelow = Math.ceil(Math.max(0, total - endIdx) / 2);

  const rowHeight = _dockRowHeight || 330;
  const topHeight = rowsAbove * rowHeight;
  const bottomHeight = rowsBelow * rowHeight;

  const pendingLabel = window.t ? window.t('dock_card_pending') : 'Pending';
  const albumLabel = window.t ? window.t('dock_card_album') : 'Album';
  const saveLabel = window.t ? window.t('dock_card_save') : 'Save';
  const renameLabel = window.t ? window.t('dock_card_rename') : 'Rename';
  const trashLabel = window.t ? window.t('dock_card_trash') : 'Trash';
  const labels = { pendingLabel, albumLabel, saveLabel, renameLabel, trashLabel };

  const visibleSlice = pendingPhotos.slice(startIdx, endIdx);
  for (let i = 0; i < visibleSlice.length; i++) {
    visibleSlice[i]._globalIndex = startIdx + i;
  }

  reconcileVirtualizedGrid(
    grid,
    visibleSlice,
    (photo) => renderSingleDockCardHtml(photo, labels),
    topHeight,
    bottomHeight,
    '.dock-card'
  );

  // Refresh selection on reused cards as well as newly rendered cards.
  visibleSlice.forEach(photo => {
    updateDockCardSelection(grid._cardMap.get(photo.id), state.selectedDockPhotoIds.has(photo.id));
  });

  const viewport = document.querySelector('.app-viewport') || document.documentElement;
  const scrollTop = (viewport && viewport.scrollTop !== undefined) ? viewport.scrollTop : (window.scrollY || 0);
  const gridOffsetTop = grid.offsetTop || 0;
  const relScroll = window.GalleryViewport?.relative(grid, viewport) ?? Math.max(0, scrollTop - gridOffsetTop);
  const curRow = Math.floor(relScroll / (_dockRowHeight || 330));
  const viewportCenterIdx = (curRow + 2) * 2;
  schedulePrioritizedDecompression(visibleSlice, grid, '.dock-card', viewportCenterIdx);

  if (!_dockRowHeightMeasured) {
    const firstCard = grid.querySelector('.dock-card');
    if (firstCard && firstCard.offsetHeight > 50) {
      const previousHeight = _dockRowHeight;
      _dockRowHeight = firstCard.offsetHeight + 10;
      _dockRowHeightMeasured = true;
      if (window.AndroidApp && Math.abs(previousHeight - _dockRowHeight) > 0.5) renderDockWindow();
    }
  }
}


function renderDock(options = {}) {
  const pendingPhotos = window.LibraryViews.get(state).pending;
  if (pendingPhotos.length === 1) {
    const singleId = pendingPhotos[0].id;
    if (state._autoSelectedSingleDockPhotoId !== singleId) {
      state._autoSelectedSingleDockPhotoId = singleId;
      state.selectedDockPhotoIds.clear();
      state.selectedDockPhotoIds.add(singleId);
    }
  } else {
    if (state._autoSelectedSingleDockPhotoId !== null) {
      state.selectedDockPhotoIds.delete(state._autoSelectedSingleDockPhotoId);
      state._autoSelectedSingleDockPhotoId = null;
    }
    if (pendingPhotos.length === 0) {
      state.selectedDockPhotoIds.clear();
    }
  }
  refreshDockMediaSummary(pendingPhotos);
  // The user's Dock sort (dock_sort.js); without it, library order as before.
  _cachedDockPhotos = window.DockSort ? window.DockSort.order(pendingPhotos) : pendingPhotos;
  const grid = document.getElementById('dockPhotoGrid');
  const empty = document.getElementById('dockEmptyState');
  const subtitle = document.getElementById('dockSubtitle');
  const actionStrip = document.getElementById('dockActionStrip');
  const quickTagBar = document.getElementById('dockQuickTagBar');
  const quickTagStrip = document.getElementById('dockQuickTagStrip');
  const selectAllBtnText = document.getElementById('dockSelectAllBtnText');
  const selectedBadge = document.getElementById('dockSelectedCountBadge');
  const hint = document.getElementById('dockQuickTagHint');

  const dockLimitIndicator = document.getElementById('dockLimitIndicator');
  if (dockLimitIndicator) {
    if (state.isPro) {
      dockLimitIndicator.style.display = 'none';
    } else {
      const currentSaved = getSavedPhotosCount();
      const limit = FREE_GALLERY_SAVE_LIMIT;
      dockLimitIndicator.style.display = 'inline-flex';
      const pillTemplate = window.t ? window.t('pro_save_limit_pill') : '{current} / {limit} Photos Saved (Free Tier)';
      const pillText = pillTemplate.replace('{current}', currentSaved).replace('{limit}', limit);
      // Every translation leads with "{current} / {limit}"; a tight Dock toolbar row shows that count alone.
      const limitAt = pillTemplate.startsWith('{current}') ? pillTemplate.indexOf('{limit}') : -1;
      const pillCount = limitAt > 0
        ? pillTemplate.slice(0, limitAt + '{limit}'.length).replace('{current}', currentSaved).replace('{limit}', limit) : '';
      const pillParts = pillCount && pillText.startsWith(pillCount)
        ? `<span class="dock-limit-count">${pillCount}</span><span class="dock-limit-label">${pillText.slice(pillCount.length)}</span>`
        : pillText;
      dockLimitIndicator.innerHTML = `<i class="fa-solid fa-cloud-arrow-up"></i> <span>${pillParts}</span>`;
      dockLimitIndicator.classList.toggle('limit-reached', currentSaved >= limit);
      dockLimitIndicator.title = currentSaved >= limit
        ? (window.t ? window.t('pro_save_limit_heading') : `Free Plan Limit Reached (${limit} Photos)`)
        : `Free plan: up to ${limit} photos in Gallery/Albums. Tap to upgrade!`;
    }
  }

  if (subtitle) {
    subtitle.textContent = pendingPhotos.length === 0
      ? (window.t ? window.t('dock_subtitle_clear') : 'All caught up')
      : screenMediaText('screen_media_pending', { media: formatScreenMediaCounts(_dockHeaderMediaCounts) });
  }

  const dockScreen = document.getElementById('dockScreen');
  if (dockScreen) dockScreen.classList.toggle('dock-has-media', pendingPhotos.length > 0);

  if (pendingPhotos.length === 0) {
    if (grid) { grid.innerHTML = ''; window.GalleryViewport?.clear(grid); }
    if (empty) empty.style.display = 'flex';
    if (actionStrip) actionStrip.style.display = 'none';
    if (quickTagBar) quickTagBar.style.display = 'none';
    _dockVisibleStart = 0;
    if (typeof renderNavBadges === 'function') renderNavBadges();
    return;
  }

  if (empty) empty.style.display = 'none';
  if (actionStrip) actionStrip.style.display = 'flex';
  if (quickTagBar) quickTagBar.style.display = 'block';

  // Render 1-Tap Quick Tag Strip with vibrant album colors
  const newAlbumLabel = window.t ? window.t('albums_new_btn') : 'New Album';
  if (quickTagStrip) {
    quickTagStrip.innerHTML = state.tags.map(tag => `
      <button class="quick-tag-chip" onclick="quickTagSelected('${tag.name}')" title="${escapeHtml(tag.name)}">
        <span class="tag-dot" style="background:${tag.color}; box-shadow: 0 0 6px ${tag.color};"></span>
        <span>${escapeHtml(tag.name)}</span>
      </button>
    `).join('') + `
      <button class="quick-tag-chip new-tag-chip" onclick="openNewAlbumModal()" title="${newAlbumLabel}">
        <i class="fa-solid fa-plus"></i> <span>${newAlbumLabel}</span>
      </button>
    `;
  }

  updateDockSelectionUI(pendingPhotos);

  renderDockWindow(options);
  if (typeof renderNavBadges === 'function') renderNavBadges();
}

function updateDockSelectionUI(photos) {
  const pendingPhotos = photos || _cachedDockPhotos || state.photos.filter(p => p.isPending && !p.deletedAt);
  const selectedCount = state.selectedDockPhotoIds.size;
  const allSelected = pendingPhotos.length > 0 && selectedCount === pendingPhotos.length;

  const saveDirectBtn = document.getElementById('dockBatchMoveBtn');
  if (saveDirectBtn) saveDirectBtn.disabled = selectedCount === 0;

  const selectAllBtnText = document.getElementById('dockSelectAllBtnText');
  if (selectAllBtnText) {
    const selectAllTemplate = window.t ? window.t('dock_select_all_count') : 'Select All ({count})';
    const countAt = selectAllTemplate.lastIndexOf(' ({count})');
    if (!allSelected && countAt > 0 && countAt + ' ({count})'.length === selectAllTemplate.length) {
      // "(N)" is its own span so a tight Dock toolbar row can drop it.
      selectAllBtnText.innerHTML = `${escapeHtml(selectAllTemplate.slice(0, countAt))}<span class="dock-select-all-count"> (${pendingPhotos.length})</span>`;
    } else {
      selectAllBtnText.textContent = allSelected
        ? (window.t ? window.t('dock_deselect_all') : 'Deselect All')
        : (window.t ? window.t('dock_select_all_count', { count: pendingPhotos.length }) : `Select All (${pendingPhotos.length})`);
    }
  }

  const selectedBadge = document.getElementById('dockSelectedCountBadge');
  if (selectedBadge) {
    selectedBadge.textContent = selectedCount === 0
      ? (window.t ? window.t('dock_selected_zero') : '0 Selected')
      : (window.t ? window.t('dock_selected_count', { count: selectedCount, total: pendingPhotos.length }) : `${selectedCount} of ${pendingPhotos.length} Selected`);
    selectedBadge.classList.toggle('has-selection', selectedCount > 0);
  }

  const hint = document.getElementById('dockQuickTagHint');
  if (hint) {
    hint.textContent = selectedCount === 0
      ? (window.t ? window.t('dock_hint_default') : 'Tap photos to select, then tap album')
      : (window.t ? window.t('dock_hint_selected', { count: selectedCount }) : `Tap an album above to organize ${selectedCount} photos!`);
  }
  window.DockToolbar?.fitSelectRow();
}

function updateDockCardSelection(card, isSelected) {
  if (!card) return;
  card.classList.toggle('selected', isSelected);
  const check = card.querySelector('.card-select-check');
  if (check) {
    check.classList.toggle('checked', isSelected);
    const markup = isSelected ? '<i class="fa-solid fa-check"></i>' : '';
    if (check.innerHTML !== markup) check.innerHTML = markup;
  }
}

function toggleDockSelect(id) {
  const isSelected = !state.selectedDockPhotoIds.has(id);
  if (isSelected) {
    state.selectedDockPhotoIds.add(id);
  } else {
    state.selectedDockPhotoIds.delete(id);
  }
  updateDockSelectionUI();
  const card = document.querySelector(`.dock-card[data-id="${id}"]`);
  updateDockCardSelection(card, isSelected);
}

function toggleSelectAllDock() {
  const pendingPhotos = window.LibraryViews.get(state).pending;
  if (state.selectedDockPhotoIds.size === pendingPhotos.length) {
    state.selectedDockPhotoIds.clear();
  } else {
    pendingPhotos.forEach(p => state.selectedDockPhotoIds.add(p.id));
  }
  updateDockSelectionUI(pendingPhotos);
  const grid = document.getElementById('dockPhotoGrid');
  if (grid?._cardMap) {
    grid._cardMap.forEach((card, id) => {
      if (grid.contains(card)) updateDockCardSelection(card, state.selectedDockPhotoIds.has(id));
    });
  } else if (grid) {
    grid.querySelectorAll('.dock-card').forEach(card => {
      updateDockCardSelection(card, state.selectedDockPhotoIds.has(card.dataset.id));
    });
  }
}

function quickTagSelected(tagName) {
  if (state.selectedDockPhotoIds.size === 0) {
    showToast(`Select photos below first, then tap '${tagName}' to organize!`);
    return;
  }

  const count = state.selectedDockPhotoIds.size;
  if (!hasUnlimitedGallerySaves() && !checkCanSavePhotosToGallery(countPendingMediaToSave(state.selectedDockPhotoIds))) {
    return;
  }

  const incremental = count <= 4;
  state.photos.forEach(photo => {
    if (state.selectedDockPhotoIds.has(photo.id)) {
      const previousView = incremental ? window.LibraryViews.capture(photo) : null;
      if (!photo.tags) photo.tags = [];
      if (!photo.tags.includes(tagName)) {
        photo.tags.push(tagName);
      }
      photo.isPending = false;
      if (incremental) window.LibraryViews.update(state, photo, previousView);
    }
  });

  state.selectedDockPhotoIds.clear();
  saveState(incremental);
  renderAll();
  showToast(`✨ Organized ${count} ${count === 1 ? 'photo' : 'photos'} into '${tagName}' album!`);
}

function openBatchTagModalFromDock() {
  if (state.selectedDockPhotoIds.size === 0) {
    showToast('Select photos to tag first!');
    return;
  }
  if (!hasUnlimitedGallerySaves() && !checkCanSavePhotosToGallery(countPendingMediaToSave(state.selectedDockPhotoIds))) {
    return;
  }
  openBatchTagModal(Array.from(state.selectedDockPhotoIds));
}

function moveSelectedDockDirect() {
  // Only save explicitly selected, live Dock items. Never infer "select all".
  const selectedIds = state.selectedDockPhotoIds;
  if (selectedIds.size === 0) return;
  const selectedPhotos = state.photos.filter(photo =>
    photo.isPending && !photo.deletedAt && selectedIds.has(photo.id));
  const count = selectedPhotos.length;
  if (count === 0 || (!hasUnlimitedGallerySaves() && !checkCanSavePhotosToGallery(selectedPhotos.filter(photo => !photo.isFavorite).length))) return;
  const incremental = selectedPhotos.length <= 4;
  for (const photo of selectedPhotos) {
    const previousView = incremental ? window.LibraryViews.capture(photo) : null;
    photo.isPending = false;
    if (incremental) window.LibraryViews.update(state, photo, previousView);
  }

  state.selectedDockPhotoIds.clear();
  if (!incremental) window.LibraryViews.invalidate();
  _cachedDockPhotos = [];
  _cachedGalleryPhotos = [];
  renderDock();
  renderGallery();
  if (typeof renderNavBadges === 'function') renderNavBadges();
  saveState(true);
  showToast(window.t ? window.t(count === 1 ? 'dock_save_direct_success_one' : 'dock_save_direct_success', { count }) : `Saved ${count} items to Gallery.`);
}

function deleteSelectedDockPhotos() {
  if (state.selectedDockPhotoIds.size === 0) {
    showToast('Select photos to delete first!');
    return;
  }
  const count = state.selectedDockPhotoIds.size;
  const now = Date.now();
  const incremental = state.selectedDockPhotoIds.size <= 4;
  for (let i = 0; i < state.photos.length; i++) {
    const photo = state.photos[i];
    if (state.selectedDockPhotoIds.has(photo.id)) {
      const previousView = incremental ? window.LibraryViews.capture(photo) : null;
      photo.deletedAt = now;
      if (incremental) window.LibraryViews.update(state, photo, previousView);
    }
  }
  state.selectedDockPhotoIds.clear();
  if (!incremental) window.LibraryViews.invalidate();
  _cachedDockPhotos = [];
  _cachedGalleryPhotos = [];
  _cachedTrashPhotos = [];
  renderDock();
  if (typeof renderTrash === 'function') renderTrash();
  if (typeof renderNavBadges === 'function') renderNavBadges();
  saveState(true);
  showToast(`Moved ${count} photos to Trash`);
}

// -------------------------------------------------------------
// GALLERY ALBUMS THREE-DOT MENU & POPOVER (Item 10)
// -------------------------------------------------------------
function toggleGalleryAlbumsMenu(event) {
  if (event) event.stopPropagation();
  const dropdown = document.getElementById('galleryAlbumsDropdown');
  if (!dropdown) return;
  const isVisible = dropdown.style.display === 'flex';
  if (isVisible) {
    dropdown.style.display = 'none';
  } else {
    renderGalleryAlbumsDropdown();
    dropdown.style.display = 'flex';
  }
}

function closeGalleryAlbumsMenu() {
  const dropdown = document.getElementById('galleryAlbumsDropdown');
  if (dropdown) dropdown.style.display = 'none';
}

function toggle3DEffectsFromMenu(event) {
  if (event) event.stopPropagation();

  // If user is not an Aura VIP pro member, show luxury VIP upgrade modal
  if (!state.isPro) {
    if (typeof openRazorpayModal === 'function') {
      openRazorpayModal();
    }
    const vipMsg = window.t ? window.t('gallery_3d_vip_only') : '👑 3D Effects are an Aura Pro exclusive feature!';
    showToast(vipMsg);
    if (navigator.vibrate) {
      try { navigator.vibrate([30, 40, 30]); } catch (e) { }
    }
    return;
  }

  // Determine current active status
  const currentlyActive = (state.albumPhotos3DEnabled !== false) && (state.global3DEnabled !== false);
  const newActiveState = !currentlyActive;

  state.albumPhotos3DEnabled = newActiveState;
  state.global3DEnabled = newActiveState;

  try {
    localStorage.setItem('aura_album_photos_3d_enabled', newActiveState ? 'true' : 'false');
    localStorage.setItem('photo_org_global_3d', newActiveState ? 'true' : 'false');
  } catch (err) { }

  saveState();
  renderGallery();
  renderGalleryAlbumsDropdown();

  if (typeof renderAlbumsScreen === 'function') {
    renderAlbumsScreen();
  }

  if (navigator.vibrate) {
    try { navigator.vibrate(newActiveState ? [30, 50, 40] : [40]); } catch (e) { }
  }

  const msg = newActiveState
    ? (window.t ? window.t('gallery_3d_effects_on_toast') : '✨ 3D Holographic Parallax & Depth Enabled!')
    : (window.t ? window.t('gallery_3d_effects_off_toast') : '3D Effects Disabled (Clean 2D Mode)');
  showToast(msg);
}
window.toggle3DEffectsFromMenu = toggle3DEffectsFromMenu;

function renderGalleryAlbumsDropdown() {
  const list = document.getElementById('dropdownAlbumsList');
  const badge = document.getElementById('dropdownAlbumsBadge');
  const toggleLabel = document.getElementById('carouselToggleLabel');
  if (!list) return;

  // Sync VIP 3D Effects Switch in 3-dot dropdown menu (Item 11)
  const is3DActive = !!state.isPro && (state.albumPhotos3DEnabled !== false) && (state.global3DEnabled !== false);
  const dropdown3DBtn = document.getElementById('dropdown3DEffectsBtn');
  const dropdown3DDesc = document.getElementById('dropdown3DDesc');
  const dropdown3DSwitchPill = document.getElementById('dropdown3DSwitchPill');

  if (dropdown3DBtn) {
    dropdown3DBtn.classList.toggle('active', is3DActive);
    dropdown3DBtn.classList.toggle('vip-locked', !state.isPro);
  }
  if (dropdown3DSwitchPill) {
    dropdown3DSwitchPill.classList.toggle('active', is3DActive);
    dropdown3DSwitchPill.classList.toggle('locked', !state.isPro);
  }
  if (dropdown3DDesc) {
    if (!state.isPro) {
      dropdown3DDesc.textContent = window.t ? window.t('gallery_3d_unlock_vip') : 'Unlock with Aura Pro';
    } else {
      dropdown3DDesc.textContent = is3DActive
        ? (window.t ? window.t('gallery_3d_effects_active') : '3D Tilt & Depth: Active')
        : (window.t ? window.t('gallery_3d_effects_off') : '3D Effects: Disabled (Flat 2D)');
    }
  }

  const validPhotos = window.LibraryViews.get(state).saved;
  const favCount = validPhotos.filter(p => p.isFavorite).length;
  const totalAlbums = state.tags.length + 1; // Favorites + custom tags

  if (badge) badge.textContent = `${totalAlbums} ${window.t ? window.t('gallery_albums_badge_unit') : 'Albums'}`;
  if (toggleLabel) toggleLabel.textContent = state.showFeaturedCarousel ? (window.t ? window.t('gallery_carousel_hide') : 'Hide Carousel') : (window.t ? window.t('gallery_carousel_show') : 'Show Carousel');

  const hasFilter = state.onlyFavorites || state.onlyUntagged || (state.selectedFilterTags && state.selectedFilterTags.size > 0);

  // 1. "All Photos" row
  const allPhotosTitle = window.t ? window.t('gallery_all_photos') : 'All Photos';
  const momentsUnit = window.t ? window.t('gallery_moments_count') : 'moments';
  let html = `
    <button type="button" class="dropdown-album-item ${!hasFilter ? 'active' : ''}" onclick="clearAllAlbumFilters()">
      <div class="dropdown-album-item-left">
        <i class="fa-solid fa-images" style="color: #60a5fa; font-size: 13px; width: 14px; text-align: center;"></i>
        <div>
          <div class="dropdown-album-name">${escapeHtml(allPhotosTitle)}</div>
          <div class="dropdown-album-count">${validPhotos.length} ${escapeHtml(momentsUnit)}</div>
        </div>
      </div>
      ${!hasFilter ? '<i class="fa-solid fa-check dropdown-album-check"></i>' : ''}
    </button>
  `;

  // 2. "Favorites" album row
  const favActive = state.onlyFavorites;
  const favTitle = window.t ? window.t('favorites_title') : 'Favorites';
  const favPhotoCount = window.t ? window.t('albums_photo_count', { count: favCount }) : (favCount === 1 ? '1 photo' : `${favCount} photos`);
  html += `
    <button type="button" class="dropdown-album-item ${favActive ? 'active' : ''}" onclick="selectGalleryAlbumFromMenu('favorites')">
      <div class="dropdown-album-item-left">
        <i class="fa-solid fa-heart" style="color: #f43f5e; font-size: 13px; width: 14px; text-align: center;"></i>
        <div>
          <div class="dropdown-album-name">${escapeHtml(favTitle)}</div>
          <div class="dropdown-album-count">${favPhotoCount}</div>
        </div>
      </div>
      ${favActive ? '<i class="fa-solid fa-check dropdown-album-check"></i>' : ''}
    </button>
  `;

  // 3. User custom albums (e.g. Wedding, Birthday, Job Offer, Vacation, etc.)
  state.tags.forEach(tag => {
    const isTagActive = state.selectedFilterTags.has(tag.name);
    const count = validPhotos.filter(p => Array.isArray(p.tags) && p.tags.includes(tag.name)).length;
    const tagPhotoCount = window.t ? window.t('albums_photo_count', { count }) : (count === 1 ? '1 photo' : `${count} photos`);
    html += `
      <button type="button" class="dropdown-album-item ${isTagActive ? 'active' : ''}" onclick="selectGalleryAlbumFromMenu('${escapeHtml(tag.name)}')">
        <div class="dropdown-album-item-left">
          <span class="dropdown-album-dot" style="background: ${tag.color};"></span>
          <div>
            <div class="dropdown-album-name">${escapeHtml(tag.name)}</div>
            <div class="dropdown-album-count">${tagPhotoCount}</div>
          </div>
        </div>
        ${isTagActive ? '<i class="fa-solid fa-check dropdown-album-check"></i>' : ''}
      </button>
    `;
  });

  list.innerHTML = html;
}

function selectGalleryAlbumFromMenu(albumName) {
  if (state.onlyUntagged) {
    state.onlyUntagged = false;
    getUntaggedGalleryPhotos().forEach(p => state.selectedGalleryPhotoIds.delete(p.id));
    updateGallerySelectionBar();
  }
  if (albumName === 'favorites') {
    state.onlyFavorites = true;
    state.selectedFilterTags.clear();
  } else {
    state.onlyFavorites = false;
    state.selectedFilterTags.clear();
    state.selectedFilterTags.add(albumName);
  }
  renderGallery();
  closeGalleryAlbumsMenu();
  showToast(`✨ Filtered by '${albumName === 'favorites' ? 'Favorites' : albumName}'`);
}

function clearAllAlbumFilters() {
  _galleryVisibleStart = 0;
  const _vp = document.querySelector('.app-viewport');
  if (_vp) _vp.scrollTop = 0;
  state.onlyFavorites = false;
  if (state.onlyUntagged) {
    state.onlyUntagged = false;
    getUntaggedGalleryPhotos().forEach(p => state.selectedGalleryPhotoIds.delete(p.id));
    updateGallerySelectionBar();
  }
  state.selectedFilterTags.clear();
  renderGallery();
  closeGalleryAlbumsMenu();
  showToast('✨ Showing all photos');
}

function toggleFeaturedCarouselVisibility() {
  state.showFeaturedCarousel = !state.showFeaturedCarousel;
  const section = document.getElementById('galleryAlbumsSection');
  if (section) section.style.display = state.showFeaturedCarousel ? 'block' : 'none';
  renderGalleryAlbumsDropdown();
  showToast(state.showFeaturedCarousel ? 'Featured albums carousel visible' : 'Featured albums carousel hidden');
}

function hideFeaturedAlbumsCarousel() {
  state.showFeaturedCarousel = false;
  const section = document.getElementById('galleryAlbumsSection');
  if (section) section.style.display = 'none';
  renderGalleryAlbumsDropdown();
  showToast('Featured albums carousel hidden');
}

// Screen summaries count metadata only; never load media or allocate per-type arrays.
function screenMediaKind(media) {
  if (['image', 'video', 'audio'].includes(media.mediaType)) return media.mediaType;
  const name = media.displayName || media.name || '';
  const mime = media.mimeType || media.fileBlob?.type || '';
  if (/^audio\//i.test(mime) || /\.(mp3|wav|m4a|aac|ogg|flac|wma|opus)$/i.test(name) || media.audioUrl || media.dataUrl?.startsWith('data:audio/')) return 'audio';
  if (/^video\//i.test(mime) || /\.(mp4|webm|mov|m4v|mkv|avi|3gp|wmv|flv|ts)$/i.test(name) || media.videoUrl || media.dataUrl?.startsWith('data:video/')) return 'video';
  return 'image';
}

function countScreenMedia(media) {
  if (window.LibraryViews) return window.LibraryViews.summarize(media);
  const counts = { image: 0, video: 0, audio: 0 };
  for (const item of media) if (item) counts[screenMediaKind(item)]++;
  return counts;
}

function screenMediaText(key, params) {
  const templates = {
    screen_media_pending: '{media} pending review', screen_media_found: '{media} found',
    screen_media_search: '{media} matching “{query}”', screen_media_untagged: 'Untagged: {media}',
    screen_media_favorites: 'Favorites: {media}', screen_media_album: '{media} in {album}',
    screen_media_tags: '{media} ({tags} tags)', screen_media_gallery: '{media} in Gallery'
  };
  return window.t ? window.t(key, params) : templates[key].replace(/\{(\w+)\}/g, (_, name) => params[name]);
}

function formatScreenMediaCounts(countsOrMedia) {
  const counts = Array.isArray(countsOrMedia) ? countScreenMedia(countsOrMedia) : countsOrMedia;
  const parts = [];
  for (const [kind, singular, plural] of [['image', 'photo', 'photos'], ['video', 'video', 'videos'], ['audio', 'audio', 'audios']]) {
    const count = counts[kind];
    if (!count && (kind !== 'image' || counts.video || counts.audio)) continue;
    const key = `organize_${count === 1 ? singular + '_singular' : plural + '_plural'}`;
    const noun = window.t ? window.t(key) : (kind === 'audio' ? (count === 1 ? 'audio file' : 'audio files') : (count === 1 ? singular : plural));
    parts.push(`${count.toLocaleString(state.language || 'en')} ${noun}`);
  }
  return parts.join(' · ');
}

let _dockHeaderMediaCounts = { image: 0, video: 0, audio: 0 };
let _dockHeaderMediaSource = null;
let _dockHeaderMediaLength = 0;
function refreshDockMediaSummary(pendingMedia) {
  if (pendingMedia) {
    _dockHeaderMediaCounts = { ...countScreenMedia(pendingMedia) };
  } else {
    if (_dockHeaderMediaSource !== state.photos || state.photos.length < _dockHeaderMediaLength) {
      _dockHeaderMediaCounts = { image: 0, video: 0, audio: 0 };
      _dockHeaderMediaLength = 0;
    }
    // Streaming batches append to this array: only inspect newly received metadata.
    for (let i = _dockHeaderMediaLength; i < state.photos.length; i++) {
      const media = state.photos[i];
      if (media.isPending && !media.deletedAt) _dockHeaderMediaCounts[screenMediaKind(media)]++;
    }
  }
  _dockHeaderMediaSource = state.photos;
  _dockHeaderMediaLength = state.photos.length;
}

// Format album item count with accurate singular/plural and multimedia (photos & videos) breakdown
function formatAlbumPhotoCount(countOrItems) {
  if (Array.isArray(countOrItems)) {
    const items = countOrItems;
    const { videoCount } = window.LibraryViews.albumSummary(items);
    const photoCount = items.length - videoCount;

    if (photoCount > 0 && videoCount > 0) {
      const pStr = photoCount === 1 ? '1 photo' : `${photoCount} photos`;
      const vStr = videoCount === 1 ? '1 video' : `${videoCount} videos`;
      return `${pStr}, ${vStr}`;
    } else if (videoCount > 0) {
      return videoCount === 1 ? '1 video' : `${videoCount} videos`;
    } else {
      const num = photoCount;
      if (num === 1) {
        return window.t && window.t('albums_photo_count_single')
          ? window.t('albums_photo_count_single')
          : '1 photo';
      }
      return window.t
        ? window.t('albums_photo_count', { count: num })
        : `${num} photos`;
    }
  }

  const num = typeof countOrItems === 'number' ? countOrItems : (parseInt(countOrItems, 10) || 0);
  if (num === 1) {
    return window.t && window.t('albums_photo_count_single')
      ? window.t('albums_photo_count_single')
      : '1 photo';
  }
  return window.t
    ? window.t('albums_photo_count', { count: num })
    : `${num} photos`;
}
window.formatAlbumPhotoCount = formatAlbumPhotoCount;

function formatAlbumPhotoIcon(items) {
  if (Array.isArray(items)) {
    const { videoCount } = window.LibraryViews.albumSummary(items);
    const photoCount = items.length - videoCount;
    if (photoCount > 0 && videoCount > 0) return 'fa-photo-film';
    if (videoCount > 0) return 'fa-video';
  }
  return 'fa-images';
}
window.formatAlbumPhotoIcon = formatAlbumPhotoIcon;

// 2. Render Featured Albums Carousel with Live Counts
function renderAlbumsCarousel() {
  const section = document.getElementById('galleryAlbumsSection');
  if (section) {
    section.style.display = state.showFeaturedCarousel ? 'block' : 'none';
  }

  const container = document.getElementById('albumsCarouselContainer');
  const summary = document.getElementById('albumCountSummary');
  if (!container) return;

  const validPhotos = window.LibraryViews.get(state).saved;
  const favoritePhotos = window.LibraryViews.get(state).favorites;
  const favCount = favoritePhotos.length;

  const q = (state.searchQuery || '').trim().toLowerCase();

  // Filter visible albums if search query is active
  const matchingTags = q
    ? state.tags.filter(t => t.name.toLowerCase().includes(q))
    : state.tags;

  const favMatches = !q || 'favorites'.includes(q) || 'favourite'.includes(q) || 'loved'.includes(q);

  if (summary) {
    summary.textContent = `${matchingTags.length + (favMatches ? 1 : 0)} Albums`;
  }

  const carouselSources = [];
  const repFavPhoto = favoritePhotos[0];
  if (favMatches) carouselSources.push(repFavPhoto?.dataUrl || null);
  const favBgStyle = repFavPhoto
    ? `background-size: cover; background-position: center;`
    : `background: linear-gradient(135deg, #f43f5e, #9333ea);`;

  const favoritesCardHtml = favMatches ? `
    <div class="album-card ${state.onlyFavorites ? 'active-filter' : ''}" style="${favBgStyle}" onclick="toggleFavoriteFilter()">
      <div class="album-card-overlay">
        <span class="album-card-badge" style="background:#f43f5e;"><i class="fa-solid fa-heart"></i> ${formatAlbumPhotoCount(favoritePhotos)}</span>
        <span class="album-card-title"><i class="fa-solid fa-heart" style="color:#f43f5e; margin-right:4px;"></i>Favorites</span>
        <span class="album-card-count">${formatAlbumPhotoCount(favoritePhotos)}</span>
      </div>
    </div>
  ` : '';

  const tagStats = window.LibraryViews.get(state).savedTagStats;

  const tagsCardsHtml = matchingTags.map(tag => {
    const stat = tagStats.get(tag.name);
    const count = stat ? stat.count : 0;
    const repPhoto = stat ? stat.repPhoto : null;
    const countFormatted = stat ? (
      (stat.photoCount > 0 && stat.videoCount > 0)
        ? `${stat.photoCount} photo${stat.photoCount === 1 ? '' : 's'}, ${stat.videoCount} video${stat.videoCount === 1 ? '' : 's'}`
        : (stat.videoCount > 0)
          ? `${stat.videoCount} video${stat.videoCount === 1 ? '' : 's'}`
          : formatAlbumPhotoCount(stat.count)
    ) : formatAlbumPhotoCount(0);

    carouselSources.push(repPhoto?.dataUrl || null);
    const bgStyle = repPhoto
      ? `background-size: cover; background-position: center;`
      : `background: linear-gradient(135deg, ${tag.color}, #f43f5e);`;

    const isFiltered = state.selectedFilterTags.has(tag.name);

    return `
      <div class="album-card ${isFiltered ? 'active-filter' : ''}" style="${bgStyle}" onclick="toggleTagFilter('${escapeHtml(tag.name)}')">
        <div class="album-card-overlay">
          <span class="album-card-badge">${countFormatted}</span>
          <span class="album-card-title">${escapeHtml(tag.name)}</span>
          <span class="album-card-count">${countFormatted}</span>
        </div>
      </div>
    `;
  }).join('');

  const carouselMarkup = favoritesCardHtml + tagsCardsHtml;
  if (container._carouselMarkup !== carouselMarkup) {
    container.innerHTML = carouselMarkup;
    container._carouselMarkup = carouselMarkup;
  }
  Array.from(container.children).forEach((card, index) => {
    const source = carouselSources[index];
    if ((source || card._albumBackgroundSource) && card._albumBackgroundSource !== source) {
      card.style.backgroundImage = source ? 'url(' + JSON.stringify(source) + ')' : ''; 
      card._albumBackgroundSource = source;
    }
  });
}

// 3. Render Gallery (Elegant 2-column cards, virtual sliding window for 200,000+ photos)
let _galleryVisibleStart = 0;
const GALLERY_WINDOW_SIZE = 48;
let _lastRenderedAlbum = null;
let _galleryRowHeight = 270;
let _cachedGalleryPhotos = [];
let _lastGalleryPhotos = [];
let _cachedGalleryMeta = {
  activeAlbumName: null,
  isAlbumPhoto3DActive: false,
  activeAlbumSurfaceStyle: 'holo'
};

function renderGalleryTagBadgeHtml(photo) {
  const tagObj = (photo.tags || []).length ? state.tags.find(t => t.name === photo.tags[0]) : null;
  const tagColor = tagObj ? tagObj.color : '#f43f5e';
  const allTagsTitle = window.t ? window.t('gallery_all_tags', { count: (photo.tags || []).length }) : `All Tags (${(photo.tags || []).length})`;
  return (photo.tags && photo.tags.length > 0) ? `
            <div class="tags-badge-wrapper" title="${escapeHtml(photo.tags.join(', '))}" onclick="event.stopPropagation(); toggleTagsTooltip(this);">
              <span class="tag-badge-pill" style="background:${tagColor}">${escapeHtml(photo.tags[0])}${photo.tags.length > 1 ? ` +${photo.tags.length - 1}` : ''}</span>
              <div class="all-tags-tooltip">
                <span class="tooltip-title">${allTagsTitle}</span>
                <div class="tooltip-chips-row">
                  ${photo.tags.map(t => {
                    const tObj = state.tags.find(tag => tag.name === t);
                    const color = tObj ? tObj.color : '#f43f5e';
                    return `<span class="tooltip-tag-chip" style="background:${color}">${escapeHtml(t)}</span>`;
                  }).join('')}
                </div>
              </div>
            </div>
          ` : '<span class="card-tag-placeholder"></span>';
}

// Organizer actions update only mounted tag badges. Keep image nodes, scroll
// positions and the thumbnail scheduler intact; offscreen cards use fresh data.
function refreshOrganizedCardTags(changedIds) {
  const cardsById = new Map();
  document.querySelectorAll('.photo-card-elegant[data-id]').forEach(card => {
    const id = card.dataset.id;
    if (!changedIds.has(id)) return;
    if (!cardsById.has(id)) cardsById.set(id, []);
    cardsById.get(id).push(card);
  });
  for (const photo of state.photos) {
    if (!cardsById.size) break;
    const cards = cardsById.get(photo.id);
    if (!cards) continue;
    for (const card of cards) {
      const badge = card.querySelector('.tags-badge-wrapper, .card-tag-placeholder');
      if (!badge) continue;
      const template = document.createElement('template');
      template.innerHTML = renderGalleryTagBadgeHtml(photo);
      badge.replaceWith(template.content.firstElementChild);
    }
    cardsById.delete(photo.id);
  }
  _cachedGalleryPhotos = [];
  _cachedDockPhotos = [];
  _cachedTrashPhotos = [];
}

function renderSingleGalleryCardHtml(photo, meta, labels, imageSources = null) {
  window.MediaMetadata?.request(photo);
  const isSelected = state.selectedGalleryPhotoIds.has(photo.id);
  const metaDate = formatCardDateTime(photo.createdAt);

  let card3DClass = '';
  let shineOverlayHtml = '';
  const is3DEffectsOn = !!state.isPro && (state.albumPhotos3DEnabled !== false) && (state.global3DEnabled !== false);
  if (is3DEffectsOn) {
    if (meta && meta.isAlbumPhoto3DActive) {
      card3DClass = `card-3d surface-${meta.activeAlbumSurfaceStyle || 'holo'}`;
      shineOverlayHtml = '<div class="album-3d-shine"></div>';
    } else if (photo.tags && photo.tags.length > 0) {
      const pTag = state.tags.find(t => t.name === photo.tags[0]);
      const pStyle = (pTag && pTag.surface3DStyle && pTag.surface3DStyle !== 'none') ? pTag.surface3DStyle : null;
      if (pStyle) {
        card3DClass = `card-3d surface-${pStyle}`;
        shineOverlayHtml = '<div class="album-3d-shine"></div>';
      }
    }
  }

  const lblSelect = (labels && labels.lblSelect) || 'Select';
  const lblFav = (labels && labels.lblFav) || 'Favorite';
  const lblCrop = (labels && labels.lblCrop) || 'Crop';
  const lblRename = (labels && labels.lblRename) || 'Rename';
  const lblDownload = (labels && labels.lblDownload) || 'Download';
  const lblShare = (labels && labels.lblShare) || 'Share';
  const lblDelete = (labels && labels.lblDelete) || 'Delete';

  const usesCardPreview = window.GalleryThumbnails?.supports(photo);
  const syncUrl = usesCardPreview ? window.GalleryThumbnails.get(photo) : ensurePhotoDataUrlSync(photo);
  const imgSrc = usesCardPreview ? (syncUrl || ZIP_PLACEHOLDER_DATA_URL) :
    (syncUrl || photo.thumbUrl || photo.dataUrl || ZIP_PLACEHOLDER_DATA_URL);
  const isDeferred = (!imgSrc || imgSrc.startsWith('data:image/svg')) && (!!photo.zipEntry || !!photo.tarEntry);
  if (imageSources) imageSources.set(photo.id, imgSrc);

  return `
    <div class="photo-card-elegant ${card3DClass} ${isSelected ? 'selected' : ''}" data-id="${photo.id}">
      <div class="card-image-box">
        <img ${imageSources ? '' : `src="${imgSrc}"`} alt="${escapeHtml(photo.displayName)}" loading="lazy" decoding="async" class="${isDeferred ? 'zip-deferred-thumb' : ''}" onerror="if(this.isConnected && window.handleCardImageError) handleCardImageError(this, '${photo.id}')">
        ${shineOverlayHtml}
        ${(photo.mediaType === 'video' || (photo.displayName && photo.displayName.match(/\\.(mp4|webm|mov|m4v)$/i))) ? `
          <span class="card-video-pill">
            <i class="fa-solid fa-play"></i>
            <span>${window.ArchiveVideoPreviews?.supports(photo) ? window.ArchiveVideoPreviews.durationLabel(photo) : formatDuration(photo.duration || 6)}</span>
          </span>
        ` : (photo.mediaType === 'audio' || (photo.displayName && photo.displayName.match(/\\.(mp3|wav|m4a|aac|ogg|flac|wma)$/i))) ? `
          <span class="card-video-pill" style="background: rgba(147, 51, 234, 0.88);">
            <i class="fa-solid fa-music"></i>
            <span>${formatDuration(photo.duration || 0)}</span>
          </span>
        ` : ''}
        
        <button class="card-select-btn" onclick="event.stopPropagation(); toggleGallerySelect('${photo.id}')" title="${lblSelect}">
          ${isSelected ? '<i class="fa-solid fa-check"></i>' : ''}
        </button>

        <button class="card-fav-btn ${photo.isFavorite ? 'active' : ''}" onclick="event.stopPropagation(); toggleFavorite('${photo.id}')" title="${lblFav}">
          <i class="fa-${photo.isFavorite ? 'solid' : 'regular'} fa-heart" style="${photo.isFavorite ? 'color:#f43f5e !important;' : ''}"></i>
        </button>
      </div>

      <div class="card-content">
        <div class="card-title-text" title="Tap to rename: ${escapeHtml(photo.displayName)}" onclick="event.stopPropagation(); openRenamePhotoModal('${photo.id}')">${escapeHtml(photo.displayName)}</div>
        
        <div class="card-meta-row">
          ${(state.galleryShowLocationBadge === true && photo.location && typeof photo.location.latitude === 'number') ? `
            <span class="card-loc-pill" title="Location: ${escapeHtml(photo.location.city || photo.location.place || photo.location.country || photo.location.displayCoords || formatDisplayCoords(photo.location.latitude, photo.location.longitude))}" onclick="event.stopPropagation(); openPhotoDetail('${photo.id}')">
              <i class="fa-solid fa-location-dot"></i> ${escapeHtml(photo.location.city || photo.location.place || photo.location.country || photo.location.displayCoords || formatDisplayCoords(photo.location.latitude, photo.location.longitude))}
            </span>
          ` : ''}
          ${renderGalleryTagBadgeHtml(photo)}
          <span class="card-date-time" title="Created: ${metaDate.full}">
            <i class="fa-regular fa-clock"></i>
            <span class="card-date-part">${metaDate.date}</span>
            <span class="card-time-sep">·</span>
            <span class="card-time-part">${metaDate.time}</span>
          </span>
        </div>

        <div class="card-hover-actions">
          <button class="card-action-icon-btn" onclick="event.stopPropagation(); openCropEditorModal('${photo.id}')" title="${lblCrop}">
            <i class="fa-solid fa-crop-simple"></i><span class="card-btn-label"> ${lblCrop}</span>
          </button>
          <button class="card-action-icon-btn" onclick="event.stopPropagation(); openRenamePhotoModal('${photo.id}')" title="${lblRename}">
            <i class="fa-solid fa-pen"></i><span class="card-btn-label"> ${lblRename}</span>
          </button>
          <button class="card-action-icon-btn" onclick="event.stopPropagation(); downloadSinglePhoto('${photo.id}')" title="${lblDownload}">
            <i class="fa-solid fa-download"></i><span class="card-btn-label"> ${lblDownload}</span>
          </button>
          <button class="card-action-icon-btn" onclick="event.stopPropagation(); shareSinglePhoto('${photo.id}')" title="${lblShare}">
            <i class="fa-solid fa-share-nodes"></i><span class="card-btn-label"> ${lblShare}</span>
          </button>
          <button class="card-action-icon-btn danger" onclick="event.stopPropagation(); moveToTrash('${photo.id}', false, true)" title="${lblDelete}">
            <i class="fa-solid fa-trash-can"></i><span class="card-btn-label"> ${lblDelete}</span>
          </button>
        </div>
      </div>
    </div>
  `;
}

// Incremental gallery rendering retains existing cards within the virtual window.
function renderGalleryWindow(options = {}) {
  const grid = document.getElementById('galleryPhotoGrid');
  if (!grid) return;
  const photos = _cachedGalleryPhotos || [];
  const total = photos.length;
  if (total === 0) {
    grid.innerHTML = '';
    if (grid._cardMap) grid._cardMap.clear();
    window.GalleryViewport?.clear(grid);
    _galleryVisibleStart = 0;
    return;
  }
  // The bounded raster surface needs only a few screens of cards, not a
  // large offscreen DOM. Keep this independent of the library's item count.
  const WINDOW_SIZE = GALLERY_WINDOW_SIZE;

  if (options.resetScroll || _galleryVisibleStart >= total) {
    _galleryVisibleStart = 0;
    window.GalleryViewport?.reset(grid);
  }

  // Strict boundary clamping: startIdx can NEVER overshoot total - WINDOW_SIZE
  const maxStart = Math.max(0, Math.ceil(Math.max(0, total - WINDOW_SIZE) / 2) * 2);
  const safeStart = Math.min(maxStart, Math.max(0, Math.floor(_galleryVisibleStart / 2) * 2));
  const startIdx = safeStart;
  const endIdx = Math.min(total, startIdx + WINDOW_SIZE);
  const rowsAbove = Math.floor(startIdx / 2);
  const rowsBelow = Math.ceil(Math.max(0, total - endIdx) / 2);

  const rowHeight = _galleryRowHeight || 300;
  const topHeight = rowsAbove * rowHeight;
  const bottomHeight = rowsBelow * rowHeight;

  const lblSelect = window.t ? window.t('dock_select_all') : 'Select';
  const lblFav = window.t ? window.t('favorites_title') : 'Favorite';
  const lblCrop = window.t ? window.t('detail_crop') : 'Crop';
  const lblRename = window.t ? window.t('detail_rename') : 'Rename';
  const lblDownload = window.t ? window.t('detail_download') : 'Download';
  const lblShare = window.t ? window.t('detail_share') : 'Share';
  const lblDelete = window.t ? window.t('detail_trash') : 'Delete';
  const labels = { lblSelect, lblFav, lblCrop, lblRename, lblDownload, lblShare, lblDelete };

  const visibleSlice = photos.slice(startIdx, endIdx);
  for (let i = 0; i < visibleSlice.length; i++) {
    visibleSlice[i]._globalIndex = startIdx + i;
  }

  // Keep large preview data outside the HTML parser. Sources live only for
  // this bounded render and are attached before the new cards enter the DOM.
  const imageSources = new Map();
  const renderCard = photo => renderSingleGalleryCardHtml(photo, _cachedGalleryMeta, labels, imageSources);
  renderCard.attachImageSource = (card, photo) => {
    const image = card.querySelector('.card-image-box img');
    if (image && imageSources.has(photo.id)) image.src = imageSources.get(photo.id);
  };

  // Smooth DOM reconciliation: only add/remove edge cards, keep all visible cards and raster tiles intact!
  reconcileVirtualizedGrid(
    grid,
    visibleSlice,
    renderCard,
    topHeight,
    bottomHeight,
    '.photo-card-elegant'
  );

  // Selection can change while virtualized cards are reused.
  visibleSlice.forEach(photo => {
    const card = grid._cardMap.get(photo.id);
    if (!card) return;
    const title = card.querySelector('.card-title-text');
    if (title && title.textContent !== photo.displayName) {
      title.textContent = photo.displayName;
      title.title = 'Tap to rename: ' + photo.displayName;
      const image = card.querySelector('img');
      if (image) image.alt = photo.displayName;
    }
    const favorite = card.querySelector('.card-fav-btn');
    if (favorite && favorite.classList.contains('active') !== !!photo.isFavorite) {
      favorite.classList.toggle('active', !!photo.isFavorite);
      favorite.innerHTML = photo.isFavorite ? '<i class="fa-solid fa-heart" style="color:#f43f5e !important;"></i>' : '<i class="fa-regular fa-heart"></i>';
    }
    const selected = state.selectedGalleryPhotoIds.has(photo.id);
    card.classList.toggle('selected', selected);
    const button = card.querySelector('.card-select-btn');
    const markup = selected ? '<i class="fa-solid fa-check"></i>' : '';
    if (button && button.innerHTML !== markup) button.innerHTML = markup;
  });

  // Prioritized on-demand decompression of visible viewport cards
  const viewport = document.querySelector('.app-viewport') || document.documentElement;
  const scrollTop = (viewport && viewport.scrollTop !== undefined) ? viewport.scrollTop : (window.scrollY || 0);
  const gridOffsetTop = grid.offsetTop || 0;
  const relScroll = window.GalleryViewport?.relative(grid, viewport) ?? Math.max(0, scrollTop - gridOffsetTop);
  const curRow = Math.floor(relScroll / (_galleryRowHeight || 300));
  const viewportCenterIdx = (curRow + 2) * 2;
  schedulePrioritizedDecompression(visibleSlice, grid, '.photo-card-elegant', viewportCenterIdx);

  if (!grid._delegatedEventsAttached) {
    grid._delegatedEventsAttached = true;
    grid.addEventListener('click', (e) => {
      const card = e.target.closest('.photo-card-elegant');
      if (!card) return;
      if (e.target.closest('button') || e.target.closest('.card-title-text') || e.target.closest('.card-loc-pill') || e.target.closest('.tags-badge-wrapper')) return;
      const id = card.dataset.id;
      if (!id) return;
      if (state.selectedGalleryPhotoIds.size > 0) {
        toggleGallerySelect(id);
      } else {
        const curPhotos = _cachedGalleryPhotos && _cachedGalleryPhotos.length ? _cachedGalleryPhotos : state.photos;
        openPhotoDetail(id, curPhotos, (_cachedGalleryMeta && _cachedGalleryMeta.activeAlbumName) || (state.searchQuery ? `Search: "${state.searchQuery.trim()}"` : 'Gallery'));
      }
    });
    grid.addEventListener('contextmenu', (e) => {
      e.preventDefault();
      const card = e.target.closest('.photo-card-elegant');
      if (card && card.dataset.id) toggleGallerySelect(card.dataset.id);
    });
  }

  if (!_galleryRowHeightMeasured) {
    const firstCard = grid.querySelector('.photo-card-elegant');
    if (firstCard && firstCard.offsetHeight > 50) {
      const previousHeight = _galleryRowHeight;
      _galleryRowHeight = firstCard.offsetHeight + 10;
      _galleryRowHeightMeasured = true;
      if (Math.abs(previousHeight - _galleryRowHeight) > 0.5) renderGalleryWindow();
    }
  }
}


function updateGallerySelectionBar() {
  const selBar = document.getElementById('gallerySelectionBar');
  if (!selBar) return;
  const count = state.selectedGalleryPhotoIds.size;
  if (count > 0) {
    selBar.style.display = 'flex';
    const textEl = document.getElementById('selectionCountText');
    if (textEl) textEl.textContent = window.t ? window.t('gallery_selected_count', { count }) : `${count} Selected`;
    const isSingle = count === 1;
    const renameBtn = document.getElementById('renameSelectedBtn');
    const cropBtn = document.getElementById('cropSelectedBtn');
    const resizeBtn2 = document.getElementById('resizeSelectedBtn');
    if (renameBtn) renameBtn.style.display = isSingle ? 'inline-flex' : 'none';
    if (cropBtn) cropBtn.style.display = isSingle ? 'inline-flex' : 'none';
    if (resizeBtn2) resizeBtn2.style.display = isSingle ? 'inline-flex' : 'none';
  } else {
    selBar.style.display = 'none';
  }
}

function getUntaggedGalleryPhotos(photosList) {
  return window.LibraryViews.get(state).untaggedSaved;
}

function updateSelectUntaggedBtnState(photosList) {
  const btn = document.getElementById('selectUntaggedBtn');
  if (!btn) return;
  const untagged = getUntaggedGalleryPhotos(photosList);
  const count = untagged.length;
  const countBadge = document.getElementById('untaggedCountBadge');
  const btnText = document.getElementById('selectUntaggedBtnText');

  if (count === 0 && !state.onlyUntagged) {
    btn.style.display = 'none';
    btn.classList.remove('active');
    return;
  }

  btn.style.display = 'inline-flex';
  if (countBadge) {
    countBadge.textContent = count > 999 ? `${(count / 1000).toFixed(1)}k` : count;
  }

  const isFilterActive = !!state.onlyUntagged;
  btn.classList.toggle('active', isFilterActive);

  if (btnText) {
    btnText.textContent = window.t ? window.t('gallery_select_untagged') : 'Untagged';
  }

  btn.title = isFilterActive
    ? (window.t ? window.t('gallery_deselect_untagged') : 'Restore previous view')
    : (window.t ? window.t('gallery_select_untagged_title') : 'Show and select untagged items');

  const iconEl = btn.querySelector('i');
  if (iconEl) {
    iconEl.className = isFilterActive ? 'fa-solid fa-check-double' : 'fa-solid fa-tags';
  }
}

let _galleryBeforeUntagged = null;

function toggleSelectUntaggedGalleryPhotos() {
  const untagged = getUntaggedGalleryPhotos();
  if (untagged.length === 0 && !state.onlyUntagged) {
    showToast(window.t ? window.t('gallery_no_untagged') : 'No untagged items found.');
    return;
  }

  if (state.onlyUntagged) {
    state.onlyUntagged = false;
    untagged.forEach(p => state.selectedGalleryPhotoIds.delete(p.id));
    if (_galleryBeforeUntagged) {
      const previous = _galleryBeforeUntagged;
      state.onlyFavorites = previous.onlyFavorites;
      state.selectedFilterTags = new Set(previous.tags);
      state.startDate = previous.startDate;
      state.endDate = previous.endDate;
      state.searchQuery = previous.searchQuery;
      state.gallerySort = previous.gallerySort;
      state.selectedGalleryPhotoIds = new Set(previous.selection);
      _galleryVisibleStart = previous.visibleStart;
      const viewport = document.querySelector('.app-viewport');
      if (viewport) viewport.scrollTop = previous.scrollTop;
      const search = document.getElementById('gallerySearchInput');
      if (search) search.value = previous.searchQuery || '';
      const clearSearch = document.getElementById('clearSearchBtn');
      if (clearSearch) clearSearch.style.display = previous.searchQuery ? 'flex' : 'none';
      _galleryBeforeUntagged = null;
    }
    const msg = window.t
      ? window.t('gallery_untagged_deselected_toast')
      : 'Untagged selection cleared. Previous view restored.';
    showToast(msg);
  } else {
    _galleryBeforeUntagged = {
      onlyFavorites: state.onlyFavorites, tags: Array.from(state.selectedFilterTags),
      startDate: state.startDate, endDate: state.endDate, searchQuery: state.searchQuery,
      gallerySort: state.gallerySort, selection: Array.from(state.selectedGalleryPhotoIds),
      visibleStart: _galleryVisibleStart,
      scrollTop: document.querySelector('.app-viewport')?.scrollTop || 0
    };
    state.onlyUntagged = true;
    state.onlyFavorites = false;
    state.selectedFilterTags.clear();
    untagged.forEach(p => state.selectedGalleryPhotoIds.add(p.id));
    const msg = window.t
      ? window.t('gallery_untagged_selected_toast', { count: untagged.length })
      : `Selected ${untagged.length} untagged items.`;
    showToast(msg);
  }

  renderGallery();
  updateGallerySelectionBar();
  updateSelectUntaggedBtnState();
}

function resetUntaggedGalleryAfterTagging() {
  _galleryBeforeUntagged = null;
  state.onlyUntagged = false;
  state.onlyFavorites = false;
  state.selectedFilterTags.clear();
  state.startDate = null;
  state.endDate = null;
  state.searchQuery = '';
  const search = document.getElementById('gallerySearchInput');
  if (search) search.value = '';
  const clearSearch = document.getElementById('clearSearchBtn');
  if (clearSearch) clearSearch.style.display = 'none';
  const grid = document.getElementById('galleryPhotoGrid');
  if (grid) grid._cardMap = new Map();
  _galleryVisibleStart = 0;
  window.GalleryViewport?.reset(grid);
  const viewport = document.querySelector('.app-viewport');
  if (viewport) viewport.scrollTop = 0;
}

function tagSelectedGalleryPhotos() {
  const ids = Array.from(state.selectedGalleryPhotoIds);
  if (!ids.length) {
    showToast(window.t ? window.t('gallery_select_first') : 'Select media first!');
    return;
  }
  openBatchTagModal(ids);
}

function renderGallery(options = {}) {
  const curActiveAlbum = (state.selectedFilterTags && state.selectedFilterTags.size === 1) ? Array.from(state.selectedFilterTags)[0] : null;
  const isNavigatingFilter = options.resetScroll || 
    (options.filterChanged) || 
    (_lastRenderedAlbum !== curActiveAlbum);

  if (isNavigatingFilter) {
    _lastRenderedAlbum = curActiveAlbum;
    _galleryVisibleStart = 0;
    window.GalleryViewport?.reset(document.getElementById('galleryPhotoGrid'));
    const _viewport = document.querySelector('.app-viewport');
    if (_viewport) _viewport.scrollTop = 0;
    if (typeof window !== 'undefined' && window.scrollTo) window.scrollTo(0, 0);
  }
  renderAlbumsCarousel();

  // Update 3-dot menu active indicator dot if an album filter is active (Item 10)
  const menuDot = document.getElementById('albumsMenuActiveDot');
  if (menuDot) {
    const hasFilter = state.onlyFavorites || state.onlyUntagged || (state.selectedFilterTags && state.selectedFilterTags.size > 0);
    menuDot.style.display = hasFilter ? 'block' : 'none';
  }

  const q = (state.searchQuery || '').trim().toLowerCase();
  const photos = window.LibraryViews.gallery(state);

  _cachedGalleryPhotos = photos;
  _lastGalleryPhotos = photos;

  // Update Sort Trigger UI Label and State
  updateSortUI();

  // Count the filtered result, including media outside the rendered viewport.
  const galleryMediaSummary = formatScreenMediaCounts(photos);
  const countEl = document.getElementById('galleryCountText');
  if (countEl) {
    const params = { media: galleryMediaSummary };
    let key = 'screen_media_found';
    countEl.title = '';
    if (q) {
      key = 'screen_media_search';
      params.query = state.searchQuery.trim();
    } else if (state.onlyUntagged) {
      key = 'screen_media_untagged';
    } else if (state.onlyFavorites) {
      key = 'screen_media_favorites';
    } else if (state.selectedFilterTags.size > 0) {
      const selectedTags = Array.from(state.selectedFilterTags);
      countEl.title = selectedTags.join(', ');
      if (selectedTags.length === 1) {
        key = 'screen_media_album';
        params.album = selectedTags[0];
      } else {
        key = 'screen_media_tags';
        params.tags = selectedTags.length;
      }
    }
    countEl.textContent = screenMediaText(key, params);
  }

  updateSelectUntaggedBtnState();

  // Filter chips
  renderFilterStrip();

  // Album Active View Banner & Direct Import (VIP Item 3)
  const activeAlbumName = state.selectedFilterTags.size === 1 ? Array.from(state.selectedFilterTags)[0] : null;
  const albumBanner = document.getElementById('albumActiveBanner');
  const albumEmptyBtn = document.getElementById('albumEmptyImportBtn');
  const album3DToggleBtn = document.getElementById('albumView3DToggleBtn');

  let isAlbumPhoto3DActive = false;
  let activeAlbumSurfaceStyle = 'holo';

  if (activeAlbumName) {
    const albumTag = state.tags.find(t => t.name === activeAlbumName);
    const albumColor = albumTag ? albumTag.color : '#f43f5e';
    activeAlbumSurfaceStyle = (albumTag && albumTag.surface3DStyle && albumTag.surface3DStyle !== 'none')
      ? albumTag.surface3DStyle
      : 'holo';
    isAlbumPhoto3DActive = !!state.isPro && (state.albumPhotos3DEnabled !== false) && (state.global3DEnabled !== false) && (!albumTag || !albumTag.disablePhoto3D);

    if (album3DToggleBtn) {
      album3DToggleBtn.style.display = 'inline-flex';
      album3DToggleBtn.classList.toggle('active', isAlbumPhoto3DActive);
      const label = album3DToggleBtn.querySelector('.toggle-3d-label');
      if (label) {
        label.textContent = isAlbumPhoto3DActive
          ? ((window.t && window.t('album_3d_fx_on')) || '3D FX ON')
          : ((window.t && window.t('album_3d_fx_off')) || '3D FX OFF');
        label.setAttribute('data-i18n', isAlbumPhoto3DActive ? 'album_3d_fx_on' : 'album_3d_fx_off');
      }
      album3DToggleBtn.title = isAlbumPhoto3DActive
        ? ((window.t && window.t('album_3d_fx_active_title')) || '3D Card FX Active (Click to disable)')
        : ((window.t && window.t('album_3d_fx_disabled_title')) || '3D Card FX Disabled (Click to enable)');
      album3DToggleBtn.setAttribute('data-i18n-title', isAlbumPhoto3DActive ? 'album_3d_fx_active_title' : 'album_3d_fx_disabled_title');
      album3DToggleBtn.setAttribute('aria-label', album3DToggleBtn.title);
    }

    if (albumBanner) {
      albumBanner.style.display = 'flex';
      const dot = document.getElementById('albumBannerDot');
      const title = document.getElementById('albumBannerTitle');
      const sub = document.getElementById('albumBannerSubtitle');
      if (dot) dot.style.backgroundColor = albumColor;
      if (title) {
        title.textContent = activeAlbumName;
        title.title = activeAlbumName;
      }
      if (sub) sub.textContent = galleryMediaSummary;
    }
    if (albumEmptyBtn) albumEmptyBtn.style.display = 'inline-flex';
  } else {
    if (album3DToggleBtn) album3DToggleBtn.style.display = 'none';
    if (albumBanner) albumBanner.style.display = 'none';
    if (albumEmptyBtn) albumEmptyBtn.style.display = 'none';
  }

  _cachedGalleryMeta = {
    activeAlbumName,
    isAlbumPhoto3DActive,
    activeAlbumSurfaceStyle
  };

  updateGallerySelectionBar();

  const grid = document.getElementById('galleryPhotoGrid');
  grid?.classList.toggle('album-media-grid', !!activeAlbumName);
  const empty = document.getElementById('galleryEmptyState');

  if (photos.length === 0) {
    if (grid) { grid.innerHTML = ''; window.GalleryViewport?.clear(grid); }
    _galleryVisibleStart = 0;
    if (empty) empty.style.display = 'flex';

    const emptyTitle = document.getElementById('galleryEmptyTitle');
    const emptyDesc = document.getElementById('galleryEmptyDesc');
    const clearBtn = document.getElementById('clearAllFiltersBtn');
    const albumEmptyBtnText = document.getElementById('albumEmptyImportBtnText');

    if (activeAlbumName) {
      if (emptyTitle) emptyTitle.textContent = window.t ? window.t('gallery_empty_album_title') : 'This Album is Empty';
      if (emptyDesc) emptyDesc.textContent = window.t ? window.t('gallery_empty_album_desc') : 'No photos have been added to this album yet. Tap below to import photos directly, or organize photos from the Loading Dock.';
      if (albumEmptyBtn) {
        albumEmptyBtn.style.display = 'inline-flex';
      }
      if (albumEmptyBtnText) {
        albumEmptyBtnText.textContent = window.t ? window.t('album_banner_import_btn') : 'Import Photos from Gallery (Pro)';
      }
      if (clearBtn) {
        clearBtn.textContent = window.t ? window.t('album_back_to_all_photos') : 'View All Photos';
      }
    } else {
      if (emptyTitle) emptyTitle.textContent = window.t ? window.t('gallery_empty_title') : 'No Moments Match';
      if (emptyDesc) emptyDesc.textContent = window.t ? window.t('gallery_empty_desc') : 'Try switching tags, clearing date ranges, or moving new photos from the Loading Dock.';
      if (albumEmptyBtn) {
        albumEmptyBtn.style.display = 'none';
      }
      if (clearBtn) {
        clearBtn.textContent = window.t ? window.t('gallery_reset_filters') : 'Reset All Filters';
      }
    }
    return;
  }

  if (empty) empty.style.display = 'none';

  renderGalleryWindow(options);
}

function toggleTagsTooltip(el) {
  const isAlreadyActive = el.classList.contains('active');
  document.querySelectorAll('.tags-badge-wrapper.active').forEach(b => b.classList.remove('active'));
  if (!isAlreadyActive) {
    el.classList.add('active');
  }
}

document.addEventListener('click', (e) => {
  if (!e.target.closest('.tags-badge-wrapper')) {
    document.querySelectorAll('.tags-badge-wrapper.active').forEach(b => b.classList.remove('active'));
  }
});

// -------------------------------------------------------------
// VIRTUAL WINDOWING SCROLL LISTENER (Dock & Gallery)
// Smoothly re-renders windowed chunks and prunes off-screen cards
// -------------------------------------------------------------
let _scrollRafId = null;
let _scrollEndTimer = null;
let _lastScrollTop = 0;
let _scrollDirection = 'down';

function triggerStationaryDecompression() {
  if (document.body.classList.contains('is-scrolling')) return;

  const galleryScreen = document.getElementById('galleryScreen');
  if (galleryScreen && galleryScreen.classList.contains('active')) {
    const grid = document.getElementById('galleryPhotoGrid');
    const photos = _cachedGalleryPhotos && _cachedGalleryPhotos.length ? _cachedGalleryPhotos : _lastGalleryPhotos;
    if (grid && photos && photos.length > 0) {
      const viewport = document.querySelector('.app-viewport') || document.documentElement;
      const scrollTop = (viewport && viewport.scrollTop !== undefined) ? viewport.scrollTop : (window.scrollY || 0);
      const gridOffsetTop = grid.offsetTop || 0;
      const relScroll = Math.max(0, scrollTop - gridOffsetTop);
      const logicalScroll = window.GalleryViewport?.relative(grid, viewport) ?? relScroll;
      const curRow = Math.floor(logicalScroll / (_galleryRowHeight || 270));
      const viewportCenterIdx = (curRow + 2) * 2;
      const startIdx = Math.max(0, Math.min(photos.length - 1, Math.floor(_galleryVisibleStart / 2) * 2));
      const visibleSlice = photos.slice(startIdx, startIdx + GALLERY_WINDOW_SIZE);
      schedulePrioritizedDecompression(visibleSlice, grid, '.photo-card-elegant', viewportCenterIdx);
    }
    return;
  }

  const dockScreen = document.getElementById('dockScreen');
  if (dockScreen && dockScreen.classList.contains('active')) {
    const grid = document.getElementById('dockPhotoGrid');
    if (grid && _cachedDockPhotos && _cachedDockPhotos.length > 0) {
      const viewport = document.querySelector('.app-viewport') || document.documentElement;
      const scrollTop = (viewport && viewport.scrollTop !== undefined) ? viewport.scrollTop : (window.scrollY || 0);
      const gridOffsetTop = grid.offsetTop || 0;
      const relScroll = Math.max(0, scrollTop - gridOffsetTop);
      const logicalScroll = window.GalleryViewport?.relative(grid, viewport) ?? relScroll;
      const curRow = Math.floor(logicalScroll / (_dockRowHeight || 330));
      const viewportCenterIdx = (curRow + 2) * 2;
      const startIdx = Math.max(0, Math.min(_cachedDockPhotos.length - 1, Math.floor(_dockVisibleStart / 2) * 2));
      const visibleSlice = _cachedDockPhotos.slice(startIdx, startIdx + (window.AndroidApp ? DOCK_NATIVE_WINDOW_SIZE : 240));
      schedulePrioritizedDecompression(visibleSlice, grid, '.dock-card', viewportCenterIdx);
    }
    return;
  }

  if (document.getElementById('trashScreen')?.classList.contains('active')) {
    updateTrashScrollWindow(document.querySelector('.app-viewport') || document.documentElement);
  }
}
window.triggerStationaryDecompression = triggerStationaryDecompression;

// Dock-only Android fast path. Gallery/album virtualization remains unchanged.
function updateDockScrollWindow(viewport) {
  const grid = document.getElementById('dockPhotoGrid');
  const photos = _cachedDockPhotos;
  if (!grid || !photos?.length) return;
  const relative = window.GalleryViewport?.relative(grid, viewport, true) ?? Math.max(0, viewport.scrollTop - grid.offsetTop);
  const up = relative < _dockLastLogicalScroll;
  _dockLastLogicalScroll = relative;
  const rowHeight = _dockRowHeight || 330;
  const firstRow = Math.floor(relative / rowHeight);
  const lastRow = Math.ceil((relative + viewport.clientHeight) / rowHeight);
  const maxStart = Math.max(0, Math.ceil(Math.max(0, photos.length - DOCK_NATIVE_WINDOW_SIZE) / 2) * 2);
  const target = Math.min(maxStart, Math.max(0, firstRow - (up ? 16 : 6)) * 2);
  const outside = firstRow * 2 < _dockVisibleStart ||
    Math.min(photos.length, lastRow * 2) > _dockVisibleStart + DOCK_NATIVE_WINDOW_SIZE;
  if (outside || Math.abs(target - _dockVisibleStart) >= 12 ||
      (target === 0 && _dockVisibleStart !== 0) || (target === maxStart && _dockVisibleStart !== maxStart)) {
    _dockVisibleStart = target;
    renderDockWindow();
  } else {
    const slice = photos.slice(_dockVisibleStart, _dockVisibleStart + DOCK_NATIVE_WINDOW_SIZE);
    window.GalleryThumbnails?.schedule(slice, grid, (firstRow + 2) * 2);
    window.ArchiveVideoPreviews?.scheduleDock(slice, grid, (firstRow + 2) * 2);
  }
  window.GalleryViewport?.position(grid);
}

function updateGalleryScrollWindow(viewport) {
  const grid = document.getElementById('galleryPhotoGrid');
  const photos = _cachedGalleryPhotos;
  if (!grid || !photos?.length) return;
  const relative = window.GalleryViewport?.relative(grid, viewport, true) ?? Math.max(0, viewport.scrollTop - grid.offsetTop);
  const scrollTop = relative + grid.offsetTop;
  const up = scrollTop < _lastScrollTop;
  _lastScrollTop = scrollTop;
  _scrollDirection = up ? 'up' : 'down';
  const rowHeight = _galleryRowHeight || 300;
  const firstRow = Math.floor(relative / rowHeight);
  const lastRow = Math.ceil((relative + viewport.clientHeight) / rowHeight);
  const maxStart = Math.max(0, Math.ceil(Math.max(0, photos.length - GALLERY_WINDOW_SIZE) / 2) * 2);
  const target = Math.min(maxStart, Math.max(0, firstRow - (up ? 16 : 6)) * 2);
  // Hysteresis must never leave the viewport inside a spacer, especially
  // when returning to the top with fewer than 12 items left to shift.
  const outsideWindow = firstRow * 2 < _galleryVisibleStart ||
    Math.min(photos.length, lastRow * 2) > _galleryVisibleStart + GALLERY_WINDOW_SIZE;
  if (outsideWindow || Math.abs(target - _galleryVisibleStart) >= 12 ||
      (target === 0 && _galleryVisibleStart !== 0) ||
      (target === maxStart && _galleryVisibleStart !== maxStart)) {
    _galleryVisibleStart = target;
    renderGalleryWindow();
  } else if (window.GalleryThumbnails) {
    window.GalleryThumbnails.schedule(photos.slice(_galleryVisibleStart, _galleryVisibleStart + GALLERY_WINDOW_SIZE), grid, (firstRow + 2) * 2);
  }
  window.GalleryViewport?.position(grid);
}

function handleAppViewportScroll() {
  if (!document.body.classList.contains('is-scrolling')) {
    document.body.classList.add('is-scrolling');
  }
  if (_scrollEndTimer) clearTimeout(_scrollEndTimer);
  _scrollEndTimer = setTimeout(() => {
    document.body.classList.remove('is-scrolling');
    triggerStationaryDecompression();
  }, 180);

  if (document.getElementById('galleryScreen')?.classList.contains('active')) {
    // Scroll events are already frame-aligned. Do not wait another animation
    // frame to replace a spacer after an Android compositor fling.
    updateGalleryScrollWindow(document.querySelector('.app-viewport') || document.documentElement);
    return;
  }

  if (window.AndroidApp && document.getElementById('dockScreen')?.classList.contains('active')) {
    updateDockScrollWindow(document.querySelector('.app-viewport') || document.documentElement);
    return;
  }

  if (document.getElementById('trashScreen')?.classList.contains('active')) {
    updateTrashScrollWindow(document.querySelector('.app-viewport') || document.documentElement);
    return;
  }

  if (_scrollRafId) return;
  _scrollRafId = requestAnimationFrame(() => {
    _scrollRafId = null;
    const viewport = document.querySelector('.app-viewport') || document.documentElement;
    const scrollTop = (viewport && viewport.scrollTop !== undefined) ? viewport.scrollTop : (window.scrollY || 0);

    if (scrollTop > _lastScrollTop) {
      _scrollDirection = 'down';
    } else if (scrollTop < _lastScrollTop) {
      _scrollDirection = 'up';
    }
    _lastScrollTop = scrollTop;

    const dockScreen = document.getElementById('dockScreen');
    if (dockScreen && dockScreen.classList.contains('active')) {
      if (window.AndroidApp) { updateDockScrollWindow(viewport); return; }
      const pendingPhotos = _cachedDockPhotos;
      if (pendingPhotos && pendingPhotos.length > 0) {
        const total = pendingPhotos.length;
        const grid = document.getElementById('dockPhotoGrid');
        if (grid) {
          const gridOffsetTop = grid.offsetTop || 0;
          const relativeScroll = Math.max(0, scrollTop - gridOffsetTop);
          const rowHeight = _dockRowHeight || 330;
          const currentRow = Math.floor(relativeScroll / rowHeight);
          const WINDOW_SIZE = 160;
          const rowsAboveTarget = (_scrollDirection === 'up') ? 56 : 24;
          const targetRow = Math.max(0, currentRow - rowsAboveTarget);
          const maxStart = Math.max(0, Math.floor(Math.max(0, total - WINDOW_SIZE) / 2) * 2);
          const targetStart = Math.min(maxStart, targetRow * 2);

          const isNearEdges = relativeScroll < 100 || targetStart >= maxStart;
          const threshold = isNearEdges ? 4 : 12;

          if (Math.abs(targetStart - _dockVisibleStart) >= threshold) {
            _dockVisibleStart = targetStart;
            renderDockWindow();
          }
        }
      }
      return;
    }

    const galleryScreen = document.getElementById('galleryScreen');
    if (galleryScreen && galleryScreen.classList.contains('active')) {
      updateGalleryScrollWindow(viewport);
      return;
    }

  });
}
window.handleAppViewportScroll = handleAppViewportScroll;

function initViewportScrollListener() {
  const viewport = document.querySelector('.app-viewport');
  if (viewport && !viewport._virtualScrollAttached) {
    viewport._virtualScrollAttached = true;
    viewport.addEventListener('scroll', handleAppViewportScroll, { passive: true });
  }
  if (!window._virtualScrollAttached) {
    window._virtualScrollAttached = true;
    window.addEventListener('scroll', handleAppViewportScroll, { passive: true });
  }
}
if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', initViewportScrollListener);
} else {
  initViewportScrollListener();
}

// -------------------------------------------------------------
// GALLERY SORT LOGIC
// -------------------------------------------------------------
function updateSortUI() {
  const triggerText = document.getElementById('sortTriggerText');
  const triggerIcon = document.getElementById('sortTriggerIcon');
  const options = document.querySelectorAll('.sort-option-btn');
  const sortMode = state.gallerySort || 'date-desc';

  const sortConfig = {
    'date-desc': { text: (window.t ? window.t('gallery_sort_newest') : 'Newest'), icon: 'fa-solid fa-arrow-down-short-wide' },
    'date-asc': { text: (window.t ? window.t('gallery_sort_oldest') : 'Oldest'), icon: 'fa-solid fa-arrow-up-wide-short' },
    'name-asc': { text: (window.t ? window.t('gallery_sort_name_asc') : 'Name A-Z'), icon: 'fa-solid fa-arrow-down-a-z' },
    'name-desc': { text: (window.t ? window.t('gallery_sort_name_desc') : 'Name Z-A'), icon: 'fa-solid fa-arrow-down-z-a' }
  };

  const current = sortConfig[sortMode] || sortConfig['date-desc'];
  if (triggerText) triggerText.textContent = current.text;
  if (triggerIcon) triggerIcon.className = current.icon;

  const sortBtn = document.getElementById('sortTriggerBtn');
  if (sortBtn) {
    const sortTitle = window.t ? window.t('gallery_sort_trigger_title') : 'Sort gallery photos';
    sortBtn.title = sortTitle;
    sortBtn.setAttribute('data-i18n-title', 'gallery_sort_trigger_title');
    sortBtn.setAttribute('aria-label', sortTitle);
  }

  options.forEach(btn => {
    const isCurrent = btn.dataset.sort === sortMode;
    btn.classList.toggle('active', isCurrent);
  });
}

