function toggleFavorite(id) {
  const photo = state.photos.find(p => p.id === id);
  if (photo) {
    if (!checkCanSavePhotosToGallery(photo.isPending && !photo.isFavorite && !photo.deletedAt ? 1 : 0)) return;
    const previousView = window.LibraryViews.capture(photo);
    photo.isFavorite = !photo.isFavorite;
    window.LibraryViews.update(state, photo, previousView);
    saveState(true);

    // Update all mounted copies, including the hidden gallery behind Favorites.
    document.querySelectorAll(`.photo-card-elegant[data-id="${CSS.escape(String(id))}"]`).forEach(card => {
      const favBtn = card.querySelector('.card-fav-btn');
      if (favBtn) {
        favBtn.classList.toggle('active', photo.isFavorite);
        favBtn.innerHTML = `<i class="fa-${photo.isFavorite ? 'solid' : 'regular'} fa-heart" style="${photo.isFavorite ? 'color:#f43f5e !important;' : ''}"></i>`;
      }
    });
    renderFavorites();
    renderNavBadges();

    if (state.onlyFavorites) {
      renderGallery();
    } else {
      renderAlbumsCarousel();
      renderFilterStrip();
    }

    showToast(photo.isFavorite ? 'Added to Favorites ❤️' : 'Removed from Favorites');
  }
}

