// Album Activity & Sorting Engine (Item 11)
function recordAlbumActivity(tagName, actionType = 'modified') {
  if (!tagName) return;
  const tag = state.tags.find(t => t.name.toLowerCase() === tagName.toLowerCase());
  if (!tag) return;
  const now = Date.now();
  if (actionType === 'viewed') {
    // Only track viewing timestamp for telemetry without modifying sort or position
    tag.lastViewedAt = now;
    return;
  } else if (actionType === 'added') {
    tag.createdAt = tag.createdAt || now;
    tag.lastModifiedAt = now;
  } else if (actionType === 'favorited') {
    tag.lastModifiedAt = now;
  } else {
    tag.lastModifiedAt = now;
  }
  saveState();
}

function getAlbumRecentActivityTime(tag, albumPhotos = []) {
  const latestPhotoTime = albumPhotos.reduce((max, p) => Math.max(max, p.createdAt || 0, p.modifiedAt || 0), 0);
  // Only actual content modifications determine recent activity (never casual album viewing)
  return Math.max(
    tag.lastModifiedAt || 0,
    latestPhotoTime,
    tag.createdAt || 0
  );
}

function formatRelativeTime(ts) {
  if (!ts) return 'recently';
  const diff = Date.now() - ts;
  if (diff < 60000) return 'just now';
  const mins = Math.floor(diff / 60000);
  if (mins < 60) return `${mins}m ago`;
  const hours = Math.floor(mins / 60);
  if (hours < 24) return `${hours}h ago`;
  const days = Math.floor(hours / 24);
  if (days < 7) return `${days}d ago`;
  const d = new Date(ts);
  return d.toLocaleDateString(undefined, { month: 'short', day: 'numeric' });
}

function toggleAlbumFavorite(tagName) {
  const tag = state.tags.find(t => t.name === tagName);
  if (!tag) return;
  tag.isFavorite = !tag.isFavorite;
  tag.lastModifiedAt = Date.now();
  // Album metadata does not change the indexed media lists.
  saveState(true);
  renderAlbumsScreen(tagName);
  showToast(tag.isFavorite ? `Marked '${tagName}' as Favorite album` : `Removed '${tagName}' from Favorite albums`);
}

// A favorite toggle must not recreate decoded covers or reset card motion.
// Use the normal renderer's markup/order so filters and labels stay identical.
function reconcileAlbumFavoriteCards(grid, markup) {
  const template = document.createElement('template');
  template.innerHTML = markup;
  const key = card => `${card.classList.contains('favorites-album-card') ? 'featured' : 'album'}:${card.dataset.album}`;
  const current = new Map(Array.from(grid.children, card => [key(card), card]));
  const desired = Array.from(template.content.children);
  // A different view may not have mounted these cards yet. Use its normal render.
  if (desired.some(card => !current.has(key(card)))) return false;

  const ordered = desired.map(next => {
    const card = current.get(key(next));
    const button = card.querySelector('.album-cover-fav-btn');
    const nextButton = next.querySelector('.album-cover-fav-btn');
    if (button && nextButton) {
      for (const attr of ['class', 'title', 'aria-label']) {
        if (button.getAttribute(attr) !== nextButton.getAttribute(attr)) {
          button.setAttribute(attr, nextButton.getAttribute(attr));
        }
      }
      const icon = button.querySelector('i');
      const nextIcon = nextButton.querySelector('i');
      if (icon && nextIcon && icon.className !== nextIcon.className) icon.className = nextIcon.className;
    }
    for (const selector of ['.album-title-text', '.album-subtitle-text', '.album-activity-pill']) {
      const item = card.querySelector(selector);
      const nextItem = next.querySelector(selector);
      if (!item || !nextItem) continue;
      if (item.className !== nextItem.className) item.className = nextItem.className;
      if (item.innerHTML !== nextItem.innerHTML) item.innerHTML = nextItem.innerHTML;
    }
    return card;
  });
  const retained = new Set(ordered);
  for (const card of Array.from(grid.children)) {
    if (!retained.has(card)) card.remove();
  }
  let cursor = grid.firstElementChild;
  for (const card of ordered) {
    if (card !== cursor) grid.insertBefore(card, cursor);
    cursor = card.nextElementSibling;
  }
  return true;
}

