  // Organizer-only media typing: audio playback URLs must not imply video.
  function organizeMediaKind(photo) {
    if (['image', 'video', 'audio'].includes(photo?.mediaType)) return photo.mediaType;
    const name = photo?.displayName || '';
    if (/\.(mp3|wav|m4a|aac|ogg|flac|wma|opus)$/i.test(name) || photo?.audioUrl || photo?.dataUrl?.startsWith('data:audio/')) return 'audio';
    if (/\.(mp4|webm|mov|m4v|mkv|avi|3gp|wmv|flv|ts)$/i.test(name) || photo?.videoUrl || photo?.dataUrl?.startsWith('data:video/')) return 'video';
    return 'image';
  }

  // Get intelligent media descriptor based on selected or candidate items (Video / Photo / Audio / Mixed)
  function getSelectedMediaDescriptor(targetIdsOrItems) {
    let items = [];
    if (Array.isArray(targetIdsOrItems)) {
      if (targetIdsOrItems.length > 0 && typeof targetIdsOrItems[0] === 'object' && targetIdsOrItems[0] !== null) {
        items = targetIdsOrItems;
      } else {
        const idSet = new Set(targetIdsOrItems);
        items = (state.photos || []).filter(p => idSet.has(p.id) && !p.deletedAt);
      }
    } else if (_moveCopyTargetIdSet && _moveCopyTargetIdSet.size > 0) {
      items = (_cachedMoveCopyPhotos || []).filter(p => _moveCopyTargetIdSet.has(p.id));
      if (!items.length) {
        items = (state.photos || []).filter(p => _moveCopyTargetIdSet.has(p.id) && !p.deletedAt);
      }
    } else if (state.moveCopyTargetIds && state.moveCopyTargetIds.length > 0) {
      const idSet = new Set(state.moveCopyTargetIds);
      items = (state.photos || []).filter(p => idSet.has(p.id) && !p.deletedAt);
    } else if (_cachedMoveCopyPhotos && _cachedMoveCopyPhotos.length > 0) {
      items = _cachedMoveCopyPhotos;
    }

    let videoCount = 0;
    let audioCount = 0;
    let photoCount = 0;

    for (let i = 0; i < items.length; i++) {
      const p = items[i];
      if (!p) continue;
      const isVideo = organizeMediaKind(p) === 'video';
      const isAudio = organizeMediaKind(p) === 'audio';
      if (isVideo) {
        videoCount++;
      } else if (isAudio) {
        audioCount++;
      } else {
        photoCount++;
      }
    }

    const total = items.length;
    const t = window.t || ((k) => k);

    if (videoCount > 0 && photoCount === 0 && audioCount === 0) {
      return {
        type: 'video',
        videoCount,
        photoCount,
        audioCount,
        count: total,
        nounSingular: t('organize_video_singular') || 'video',
        nounPlural: t('organize_videos_plural') || 'videos',
        copyLabel: t('organize_copy_videos') || 'Copy Videos',
        moveLabel: t('organize_move_videos') || 'Move Videos',
        modalTitle: t('organize_videos_title') || 'Organize Videos',
        selectCopyLabel: t('organize_select_to_copy', { noun: t('organize_videos_plural') || 'Videos' }) || 'Select Videos to Copy',
        selectMoveLabel: t('organize_select_to_move', { noun: t('organize_videos_plural') || 'Videos' }) || 'Select Videos to Move',
        railKey: 'fusion_album_of_videos'
      };
    } else if (photoCount > 0 && videoCount === 0 && audioCount === 0) {
      return {
        type: 'photo',
        videoCount,
        photoCount,
        audioCount,
        count: total,
        nounSingular: t('organize_photo_singular') || 'photo',
        nounPlural: t('organize_photos_plural') || 'photos',
        copyLabel: t('organize_copy_photos') || 'Copy Photos',
        moveLabel: t('organize_move_photos') || 'Move Photos',
        modalTitle: t('organize_photos_title') || 'Organize Photos',
        selectCopyLabel: t('organize_select_to_copy', { noun: t('organize_photos_plural') || 'Photos' }) || 'Select Photos to Copy',
        selectMoveLabel: t('organize_select_to_move', { noun: t('organize_photos_plural') || 'Photos' }) || 'Select Photos to Move',
        railKey: 'fusion_album_of_photos'
      };
    } else if (audioCount > 0 && videoCount === 0 && photoCount === 0) {
      return {
        type: 'audio',
        videoCount,
        photoCount,
        audioCount,
        count: total,
        nounSingular: t('organize_audio_singular') || 'audio',
        nounPlural: t('organize_audios_plural') || 'audios',
        copyLabel: t('organize_copy_audios') || 'Copy Audio',
        moveLabel: t('organize_move_audios') || 'Move Audio',
        modalTitle: t('organize_media_title') || 'Organize Audio',
        selectCopyLabel: t('organize_select_to_copy', { noun: t('organize_audios_plural') || 'Audio' }) || 'Select Audio to Copy',
        selectMoveLabel: t('organize_select_to_move', { noun: t('organize_audios_plural') || 'Audio' }) || 'Select Audio to Move',
        railKey: 'fusion_album_of_items'
      };
    } else {
      // Mixed media (e.g. 5 videos and 2 photos = items) or 0 items
      return {
        type: 'mixed',
        videoCount,
        photoCount,
        audioCount,
        count: total,
        nounSingular: t('organize_item_singular') || 'item',
        nounPlural: t('organize_items_plural') || 'items',
        copyLabel: t('organize_copy_items') || 'Copy Items',
        moveLabel: t('organize_move_items') || 'Move Items',
        modalTitle: t('organize_media_title') || 'Organize Media',
        selectCopyLabel: t('organize_select_to_copy', { noun: t('organize_items_plural') || 'Items' }) || 'Select Items to Copy',
        selectMoveLabel: t('organize_select_to_move', { noun: t('organize_items_plural') || 'Items' }) || 'Select Items to Move',
        railKey: 'fusion_album_of_items'
      };
    }
  }
  window.getSelectedMediaDescriptor = getSelectedMediaDescriptor;

