  // Each explicit opening starts with its source summary and preview rail in view.
  // Do this synchronously so there is no first frame at the old scroll position.
  function showOrganizeStudioStart(bodyId) {
    document.getElementById('moveCopyModal')?.classList.toggle('organize-fusion-open', bodyId === 'multiTagBuilderBody');
    for (const id of ['multiTagToggleBtn', 'singleTagToggleBtn']) {
      const toggle = document.getElementById(id);
      toggle?.parentElement.classList.toggle('organize-expanded', toggle.getAttribute('aria-expanded') === 'true');
    }
    for (const el of [document.querySelector('#moveCopyModal > .dialog-card'),
      document.getElementById('moveCopyDialogBody'), document.getElementById(bodyId)]) {
      if (el) el.scrollTop = 0;
    }
    const body = document.getElementById(bodyId);
    for (const rail of body?.querySelectorAll('.move-copy-preview-rail') || []) {
      if (rail.clientWidth && rail._organizeScrollbar) {
        rail._organizeScrollbar._seek(rail._organizeLogicalOffset || 0);
      }
    }
  }

