  // State & Virtual Sliding Window variables for 50k+ photos
  let _cachedMoveCopyPhotos = [];
  let _moveCopyTargetIdSet = null;
  let _moveCopyRailStartIdx = 0;
  let _moveCopyRailBaseIdx = 0;
  const MOVE_COPY_RAIL_RANGE = 128;

  // The physical strip stays small, but its scrollbar represents ALL photos.
  // A native scrollbar on the rebased strip otherwise keeps jumping backwards.
  function syncOrganizeRailScrollbar(rail, total, base, seek) {
    let bar = rail._organizeScrollbar;
    if (!bar || !bar.isConnected) {
      bar = document.createElement('div');
      bar.className = 'organize-rail-scrollbar';
      bar.tabIndex = 0;
      bar.setAttribute('role', 'scrollbar');
      bar.setAttribute('aria-orientation', 'horizontal');
      bar.setAttribute('aria-label', window.t('organize_rail_position'));
      bar.setAttribute('aria-controls', rail.id);
      const thumb = document.createElement('div');
      thumb.className = 'organize-rail-scrollbar-thumb';
      bar.appendChild(thumb);
      rail.after(bar);
      rail._organizeScrollbar = bar;
      let grabOffset = null;
      const drag = event => {
        const rect = bar.getBoundingClientRect();
        const width = thumb.getBoundingClientRect().width;
        const fraction = (event.clientX - rect.left - grabOffset) / Math.max(1, rect.width - width);
        bar._seek(Math.max(0, Math.min(1, fraction)) * bar._max);
      };
      bar.addEventListener('pointerdown', event => {
        if (event.button !== 0) return;
        event.preventDefault();
        const rect = thumb.getBoundingClientRect();
        grabOffset = event.target === thumb ? event.clientX - rect.left : rect.width / 2;
        bar.setPointerCapture(event.pointerId);
        drag(event);
      });
      bar.addEventListener('pointermove', event => { if (grabOffset !== null) drag(event); });
      const endDrag = () => { grabOffset = null; };
      bar.addEventListener('pointerup', endDrag);
      bar.addEventListener('pointercancel', endDrag);
      bar.addEventListener('lostpointercapture', endDrag);
      bar.addEventListener('keydown', event => {
        const values = { Home: 0, End: bar._max, ArrowLeft: bar._value - 62,
          ArrowRight: bar._value + 62, PageUp: bar._value - rail.clientWidth,
          PageDown: bar._value + rail.clientWidth };
        if (!(event.key in values)) return;
        event.preventDefault();
        bar._seek(Math.max(0, Math.min(bar._max, values[event.key])));
      });
    }
    bar._seek = seek;
    bar._base = base;
    bar._total = total;
    const update = () => {
      if (!rail.isConnected || !rail.clientWidth) return;
      const max = organizeRailMaxOffset(rail, bar._total);
      const value = Math.max(0, Math.min(max, bar._base * 62 + rail.scrollLeft));
      bar._max = max; bar._value = value;
      rail._organizeLogicalOffset = value;
      bar.hidden = max === 0 || bar._total === 0;
      const thumbWidth = Math.min(bar.clientWidth, Math.max(24, bar.clientWidth * rail.clientWidth / Math.max(1, bar._total * 62)));
      bar.firstElementChild.style.width = `${thumbWidth}px`;
      bar.firstElementChild.style.transform = `translateX(${max ? value / max * (bar.clientWidth - thumbWidth) : 0}px)`;
      bar.setAttribute('aria-valuemin', '0');
      bar.setAttribute('aria-valuemax', String(Math.round(max)));
      bar.setAttribute('aria-valuenow', String(Math.round(value)));
      bar.setAttribute('aria-valuetext', `${Math.min(bar._total, Math.floor(value / 62) + 1)}–${Math.min(bar._total, Math.ceil((value + rail.clientWidth) / 62))} / ${bar._total.toLocaleString()}`);
    };
    if (!bar._update) {
      bar._update = update;
      rail.addEventListener('scroll', () => bar._update(), { passive: true });
    }
    bar._update = update;
    update();
    // Opening a hidden studio gives the rail its width after this render.
    requestAnimationFrame(update);
  }

  function organizeRailMaxOffset(rail, total) {
    const style = getComputedStyle(rail);
    const padding = (parseFloat(style.paddingLeft) || 0) + (parseFloat(style.paddingRight) || 0);
    return Math.max(0, total * 62 - 8 + padding - rail.clientWidth);
  }

  function organizeRailSeekPosition(rail, total, offset) {
    const logical = Math.max(0, Math.min(organizeRailMaxOffset(rail, total), offset));
    const index = Math.floor(logical / 62);
    const base = Math.max(0, Math.min(Math.max(0, total - MOVE_COPY_RAIL_RANGE), index - 48));
    return { base, start: Math.max(base, Math.min(Math.max(0, total - 24), index - 6)), left: logical - base * 62 };
  }

  const _organizePreviewSessions = new Map();
  let _organizePhotoLookup = null;
  let _organizeFallbackQueue = [];
  let _organizeFallbackActive = 0;

  function releaseOrganizePreviews() {
    if (_moveCopyRailScrollRaf) cancelAnimationFrame(_moveCopyRailScrollRaf);
    _moveCopyRailScrollRaf = null;
    for (const raf of Object.values(_fusionRailScrollRaf)) cancelAnimationFrame(raf);
    _fusionRailScrollRaf = {};
    for (const session of _organizePreviewSessions.values()) session?.dispose();
    _organizePreviewSessions.clear();
    _organizeFallbackQueue = [];
  }

  async function pumpOrganizeFallbacks() {
    while (_organizeFallbackActive < 2 && _organizeFallbackQueue.length) {
      const job = _organizeFallbackQueue.shift();
      if (!job.img.isConnected) continue;
      _organizeFallbackActive++;
      Promise.resolve().then(() => resolveZipPhotoDataUrl(job.photo)).then(url => {
        if (url && job.img.isConnected) job.img.src = url;
      }).catch(() => {}).finally(() => {
        _organizeFallbackActive--;
        pumpOrganizeFallbacks();
      });
    }
  }

  // Both studios use this loader, with at most 24 mounted previews per rail.
  // Independent sessions preserve the Gallery/Dock scheduler and cache.
  function bindOrganizePreviews(rail, photos) {
    for (const [oldRail, session] of _organizePreviewSessions) {
      if (!oldRail.isConnected) {
        // Fusion rebuilds its rail nodes when switching panels. Transfer the
        // same bounded cache instead of decoding those previews again.
        if (oldRail.id === rail.id && !_organizePreviewSessions.has(rail)) {
          _organizePreviewSessions.set(rail, session);
        } else {
          session?.dispose();
        }
        _organizePreviewSessions.delete(oldRail);
      }
    }
    if (!_organizePreviewSessions.has(rail)) {
      _organizePreviewSessions.set(rail, window.GalleryThumbnails?.createSession() || null);
    }
    const session = _organizePreviewSessions.get(rail);
    const cards = rail.querySelectorAll('.move-copy-thumb-card');
    rail._cardMap = new Map();
    photos.forEach((photo, index) => {
      const card = cards[index], img = card?.querySelector('img');
      if (!img) return;
      rail._cardMap.set(photo.id, card);
      const kind = organizeMediaKind(photo);
      if (kind !== 'image') {
        const icon = kind === 'audio' ? '♫' : '▶';
        const fallback = 'data:image/svg+xml,' + encodeURIComponent('<svg xmlns="http://www.w3.org/2000/svg" width="80" height="80" viewBox="0 0 80 80"><rect width="80" height="80" rx="10" fill="#182338"/><text x="40" y="53" text-anchor="middle" font-size="38" fill="#b4ddff">' + icon + '</text></svg>');
        const cached = [photo.thumbUrl, photo.posterUrl, photo.dataUrl].find(url => /^data:image\//i.test(url || '') && url !== window.ZIP_PLACEHOLDER_DATA_URL);
        img.src = cached || fallback;
        img.onerror = () => { img.onerror = null; img.src = fallback; };
        const typeBadge = document.createElement('span');
        typeBadge.className = 'organize-media-type'; typeBadge.textContent = icon;
        typeBadge.title = window.t(kind === 'audio' ? 'organize_audio_singular' : 'organize_video_singular');
        card.appendChild(typeBadge);
        if (kind === 'video' && window.ArchiveVideoPreviews?.supports(photo)) {
          window.ArchiveVideoPreviews.resolve(photo, 100 + photos.length - index, 'organizer').then(url => {
            if (url && img.isConnected && card.dataset.id === String(photo.id)) img.src = url;
          }).catch(() => {});
        }
        return;
      }
      const archived = session?.supports(photo);
      let retried = false;
      const fallback = () => {
        if (retried || !img.isConnected) return;
        retried = true;
        img.src = window.ZIP_PLACEHOLDER_DATA_URL;
        _organizeFallbackQueue.push({ photo, img });
        pumpOrganizeFallbacks();
      };
      img.onerror = () => {
        if (session?.handleError(img, photo.id)) return;
        fallback();
      };
      // Show an already-cached Gallery preview while this independent session
      // prepares its own copy. Gallery scheduling and scroll state stay intact.
      const url = archived ? (session.get(photo) || window.GalleryThumbnails?.get(photo)) : ensurePhotoDataUrlSync(photo);
      // Assign via the DOM: SVG placeholders and data URLs may contain quotes.
      img.src = url || photo.thumbUrl || photo.posterUrl || photo.dataUrl || window.ZIP_PLACEHOLDER_DATA_URL;
      if (!archived && !url && (photo.zipEntry || photo.tarEntry)) fallback();
    });
    session?.schedule(photos.filter(photo => organizeMediaKind(photo) === 'image'), rail, photos[0]?._globalIndex || 0);
  }
  let _moveCopyRailScrollRaf = null;
  let _moveCopyIsRendering = false;

  function onMoveCopyRailScroll(e) {
    if (_moveCopyIsRendering || !e.target?.clientWidth) return;
    const rail = e.target;
    if (!rail) return;
    if (_moveCopyRailScrollRaf) cancelAnimationFrame(_moveCopyRailScrollRaf);
    _moveCopyRailScrollRaf = requestAnimationFrame(() => {
      if (!rail.isConnected || !rail.clientWidth) return;
      const totalCount = (_cachedMoveCopyPhotos || []).length;
      const windowSize = 24;
      if (totalCount <= windowSize) return;

      const scrollLeft = rail.scrollLeft;
      const currentItemIdx = _moveCopyRailBaseIdx + Math.floor(scrollLeft / 62);
      const buffer = 6;
      // Rebase a short physical strip while retaining the logical photo index.
      // Large empty spacers can exhaust Android WebView's raster surface.
      const oldBase = _moveCopyRailBaseIdx;
      const physicalIndex = currentItemIdx - oldBase;
      if (physicalIndex < 24 || physicalIndex > MOVE_COPY_RAIL_RANGE - 48) {
        _moveCopyRailBaseIdx = Math.max(0, Math.min(totalCount - MOVE_COPY_RAIL_RANGE,
          currentItemIdx - 48));
      }
      const rangeEnd = Math.min(totalCount, _moveCopyRailBaseIdx + MOVE_COPY_RAIL_RANGE);
      const newStart = Math.max(_moveCopyRailBaseIdx,
        Math.min(rangeEnd - windowSize, currentItemIdx - buffer));
      if (oldBase !== _moveCopyRailBaseIdx || Math.abs(newStart - _moveCopyRailStartIdx) >= 3 || newStart === 0 || newStart === totalCount - windowSize) {
        _moveCopyRailStartIdx = newStart;
        renderMoveCopyPreviewRail({ preserveScroll: true, scrollOnly: true,
          scrollLeft: scrollLeft + (oldBase - _moveCopyRailBaseIdx) * 62 });
      }
    });
  }

  function renderMoveCopyPreviewRail(options = {}) {
    const rail = document.getElementById('moveCopyPreviewRail');
    const summary = document.getElementById('moveCopyPreviewSummary');
    const selectAllBtn = document.getElementById('moveCopySelectAllBtn');
    if (!rail) return;

    const photos = _cachedMoveCopyPhotos || [];
    const totalCount = photos.length;
    if (!_moveCopyTargetIdSet) {
      _moveCopyTargetIdSet = new Set(state.moveCopyTargetIds || []);
    }
    const selectedCount = _moveCopyTargetIdSet.size;

    if (totalCount === 0) {
      if (rail._organizeScrollbar) rail._organizeScrollbar.hidden = true;
      rail.innerHTML = `<div style="padding: 12px; color: var(--text-muted); font-size: 12px; text-align: center; width: 100%;">${window.t ? window.t('organize_no_source_photos') : 'No source photos available'}</div>`;
      if (summary) summary.textContent = window.t ? `0 ${window.t('organize_items_plural')}` : '0 items selected';
      if (selectAllBtn) selectAllBtn.style.display = 'none';
      return;
    }

    if (selectAllBtn) {
      selectAllBtn.style.display = 'inline-flex';
      const allSelected = totalCount > 0 && selectedCount === totalCount;
      const selectAllSpan = selectAllBtn.querySelector('span');
      const selectAllIcon = selectAllBtn.querySelector('i');
      if (allSelected) {
        if (selectAllSpan) selectAllSpan.textContent = window.t ? window.t('organize_deselect_all') : 'Deselect All';
        if (selectAllIcon) selectAllIcon.className = 'fa-solid fa-square-minus';
      } else {
        if (selectAllSpan) selectAllSpan.textContent = window.t ? window.t('organize_select_all') : 'Select All';
        if (selectAllIcon) selectAllIcon.className = 'fa-solid fa-check-double';
      }
    }

    if (summary && !options.scrollOnly) {
      const descriptor = getSelectedMediaDescriptor(_cachedMoveCopyPhotos);
      if (state.moveCopyIsAlbumMode && state.moveCopySourceAlbum) {
        summary.textContent = window.t
          ? window.t(descriptor.railKey, { selected: selectedCount.toLocaleString(), total: totalCount.toLocaleString(), album: state.moveCopySourceAlbum })
          : `${selectedCount.toLocaleString()} of ${totalCount.toLocaleString()} ${descriptor.nounPlural} from '${state.moveCopySourceAlbum}'`;
      } else {
        const noun = selectedCount === 1 ? descriptor.nounSingular : descriptor.nounPlural;
        summary.textContent = window.t
          ? window.t('organize_selected_items_summary', { selected: selectedCount.toLocaleString(), total: totalCount.toLocaleString(), noun, album: state.moveCopySourceAlbum || window.t('organize_selected_photos') })
          : `${selectedCount.toLocaleString()} of ${totalCount.toLocaleString()} ${noun} selected`;
      }
    }

    // High performance horizontal virtual sliding window for 50k+ photos
    const windowSize = 24;
    const pitch = 62; // 54px thumb card + 8px gap
    const gap = 8;

    if (!options.preserveScroll || totalCount <= windowSize) _moveCopyRailBaseIdx = 0;
    _moveCopyRailBaseIdx = Math.min(_moveCopyRailBaseIdx, Math.max(0, totalCount - MOVE_COPY_RAIL_RANGE));
    if (totalCount <= windowSize) {
      _moveCopyRailStartIdx = 0;
    } else {
      if (!options.preserveScroll) {
        _moveCopyRailStartIdx = 0;
        rail.scrollLeft = 0;
      } else {
        _moveCopyRailStartIdx = Math.max(0, Math.min(totalCount - windowSize, _moveCopyRailStartIdx));
      }
    }

    const startIdx = _moveCopyRailStartIdx;
    const endIdx = Math.min(totalCount, startIdx + windowSize);
    const visiblePhotos = photos.slice(startIdx, endIdx);

    const leftWidth = startIdx > _moveCopyRailBaseIdx ? ((startIdx - _moveCopyRailBaseIdx) * pitch - gap) : 0;
    const remaining = Math.min(totalCount, _moveCopyRailBaseIdx + MOVE_COPY_RAIL_RANGE) - endIdx;
    const rightWidth = remaining > 0 ? (remaining * pitch - gap) : 0;

    const leftSpacer = leftWidth > 0
      ? `<div class="move-copy-rail-spacer" style="flex:0 0 ${leftWidth}px; width:${leftWidth}px; height:54px; pointer-events:none;"></div>`
      : '';
    const rightSpacer = rightWidth > 0
      ? `<div class="move-copy-rail-spacer" style="flex:0 0 ${rightWidth}px; width:${rightWidth}px; height:54px; pointer-events:none;"></div>`
      : '';

    const cardsHtml = visiblePhotos.map(p => {
      const isSelected = _moveCopyTargetIdSet.has(p.id);
      const cardClass = isSelected ? 'move-copy-thumb-card selected' : 'move-copy-thumb-card deselected';
      const badgeIcon = isSelected ? '<i class="fa-solid fa-check"></i>' : '';
      const escapedTitle = escapeHtml(p.displayName || 'Photo');

      return `
        <div class="${cardClass}" data-id="${p.id}" data-title="${escapedTitle}" onclick="toggleMoveCopyPhotoSelection('${p.id}')" title="${escapedTitle} (${escapeHtml(window.t(isSelected ? 'organize_media_selected' : 'organize_media_unselected'))})">
          <img alt="${escapedTitle}" class="move-copy-thumb-img" loading="eager" decoding="async">
          <div class="move-copy-thumb-badge">${badgeIcon}</div>
          <div class="move-copy-thumb-remove" onclick="event.stopPropagation(); removeMoveCopyPhoto('${p.id}')" title="${escapeHtml(window.t('organize_remove_from_batch'))}">
            <i class="fa-solid fa-xmark"></i>
          </div>
        </div>
      `;
    }).join('');

    const prevScroll = options.preserveScroll ? (options.scrollLeft ?? rail.scrollLeft) : 0;
    rail._organizeLogicalOffset = _moveCopyRailBaseIdx * 62 + prevScroll;
    _moveCopyIsRendering = true;
    rail.innerHTML = leftSpacer + cardsHtml + rightSpacer;
    bindOrganizePreviews(rail, visiblePhotos);
    if (Math.abs(rail.scrollLeft - prevScroll) > 1) {
      rail.scrollTo({ left: prevScroll, behavior: 'instant' });
    }
    _moveCopyIsRendering = false;

    syncOrganizeRailScrollbar(rail, totalCount, _moveCopyRailBaseIdx, offset => {
      const position = organizeRailSeekPosition(rail, totalCount, offset);
      _moveCopyRailBaseIdx = position.base;
      _moveCopyRailStartIdx = position.start;
      renderMoveCopyPreviewRail({ preserveScroll: true, scrollOnly: true, scrollLeft: position.left });
    });

    if (!rail._hasVirtualScrollListener) {
      rail.addEventListener('scroll', onMoveCopyRailScroll, { passive: true });
      rail._hasVirtualScrollListener = true;
    }

    if (!options.scrollOnly) updateMoveCopyOptionRowAndHint();
  }

  function updateMoveCopyOptionRowAndHint() {
    const mode = state.moveCopyMode || 'copy';
    const hint = document.getElementById('moveCopyModeHint');
    const optionRow = document.getElementById('moveCopyOptionRow');
    const deleteSourceCheck = document.getElementById('moveCopyDeleteSourceCheck');

    if (!optionRow) return;
    const descriptor = getSelectedMediaDescriptor(_cachedMoveCopyPhotos);
    const nounPlural = descriptor.nounPlural;
    const nounSingular = descriptor.nounSingular;

    if (state.moveCopyIsAlbumMode && state.moveCopySourceAlbum) {
      const sourceAlbum = state.moveCopySourceAlbum;
      const totalCount = (_cachedMoveCopyPhotos || []).length;
      const selectedCount = _moveCopyTargetIdSet ? _moveCopyTargetIdSet.size : ((state.moveCopyTargetIds || []).length);
      const remainingCount = totalCount - selectedCount;

      if (mode === 'copy') {
        optionRow.style.display = 'none';
        if (deleteSourceCheck) deleteSourceCheck.checked = false;
        if (hint) {
          hint.textContent = window.t ? window.t('organize_hint_copy_items', { noun: nounPlural, album: sourceAlbum }) : `Duplicates selected ${nounPlural} in '${sourceAlbum}' into destination album. '${sourceAlbum}' remains intact.`;
        }
      } else {
        // Move mode
        if (remainingCount === 0 && totalCount > 0) {
          // All items in source album are selected to be moved -> source album will be completely empty!
          optionRow.style.display = 'block';
          if (hint) {
            hint.textContent = window.t ? window.t('organize_hint_move_items', { noun: nounPlural, album: sourceAlbum }) : `Relocates all ${nounPlural} from '${sourceAlbum}' into destination album.`;
          }
        } else {
          // At least 1 item remains in source album -> do NOT show empty album warning checkbox!
          optionRow.style.display = 'none';
          if (deleteSourceCheck) deleteSourceCheck.checked = false;
          if (hint) {
            hint.textContent = window.t('organize_move_hint_source', { album: sourceAlbum }) + ' ' + window.t('organize_remaining_items', { count: remainingCount, album: sourceAlbum });
          }
        }
      }
    } else {
      optionRow.style.display = 'none';
      if (deleteSourceCheck) deleteSourceCheck.checked = false;
      const activeTag = state.moveCopySourceAlbum;
      if (hint) {
        if (mode === 'copy') {
          hint.textContent = activeTag
            ? (window.t ? window.t('organize_copy_hint_source', { album: activeTag }) : `Adds ${nounPlural} to destination album. They will also remain in '${activeTag}'.`)
            : (window.t ? window.t('organize_copy_hint_general') : `Adds ${nounPlural} to destination album. They will also remain in their current album(s).`);
        } else {
          hint.textContent = activeTag
            ? (window.t ? window.t('organize_move_hint_source', { album: activeTag }) : `Moves ${nounPlural} to destination album and removes them from '${activeTag}'.`)
            : (window.t ? window.t('organize_move_hint_general') : `Relocates ${nounPlural} to destination album. Originals remain safe in your library.`);
        }
      }
    }
  }

  function updateMoveCopyRailSummaryOnly() {
    const summary = document.getElementById('moveCopyPreviewSummary');
    const selectAllBtn = document.getElementById('moveCopySelectAllBtn');
    const totalCount = (_cachedMoveCopyPhotos || []).length;
    const selectedCount = _moveCopyTargetIdSet ? _moveCopyTargetIdSet.size : 0;

    if (selectAllBtn) {
      const allSelected = totalCount > 0 && selectedCount === totalCount;
      const selectAllSpan = selectAllBtn.querySelector('span');
      const selectAllIcon = selectAllBtn.querySelector('i');
      if (allSelected) {
        if (selectAllSpan) selectAllSpan.textContent = window.t ? window.t('organize_deselect_all') : 'Deselect All';
        if (selectAllIcon) selectAllIcon.className = 'fa-solid fa-square-minus';
      } else {
        if (selectAllSpan) selectAllSpan.textContent = window.t ? window.t('organize_select_all') : 'Select All';
        if (selectAllIcon) selectAllIcon.className = 'fa-solid fa-check-double';
      }
    }

    if (summary) {
      const descriptor = getSelectedMediaDescriptor(_cachedMoveCopyPhotos);
      if (state.moveCopyIsAlbumMode && state.moveCopySourceAlbum) {
        summary.textContent = window.t
          ? window.t(descriptor.railKey, { selected: selectedCount.toLocaleString(), total: totalCount.toLocaleString(), album: state.moveCopySourceAlbum })
          : `${selectedCount.toLocaleString()} of ${totalCount.toLocaleString()} ${descriptor.nounPlural} from '${state.moveCopySourceAlbum}'`;
      } else {
        const noun = selectedCount === 1 ? descriptor.nounSingular : descriptor.nounPlural;
        summary.textContent = window.t
          ? window.t('organize_selected_items_summary', { selected: selectedCount.toLocaleString(), total: totalCount.toLocaleString(), noun, album: state.moveCopySourceAlbum || window.t('organize_selected_photos') })
          : `${selectedCount.toLocaleString()} of ${totalCount.toLocaleString()} ${noun} selected`;
      }
    }
  }

  window.toggleMoveCopyPhotoSelection = function (photoId) {
    if (!_moveCopyTargetIdSet) {
      _moveCopyTargetIdSet = new Set(state.moveCopyTargetIds || []);
    }
    if (_moveCopyTargetIdSet.has(photoId)) {
      _moveCopyTargetIdSet.delete(photoId);
    } else {
      _moveCopyTargetIdSet.add(photoId);
    }
    state.moveCopyTargetIds = Array.from(_moveCopyTargetIdSet);

    // Instant local card update without re-rendering rail
    const rail = document.getElementById('moveCopyPreviewRail');
    if (rail) {
      const card = rail.querySelector(`.move-copy-thumb-card[data-id="${photoId}"]`);
      if (card) {
        const isSelected = _moveCopyTargetIdSet.has(photoId);
        card.className = isSelected ? 'move-copy-thumb-card selected' : 'move-copy-thumb-card deselected';
        const badge = card.querySelector('.move-copy-thumb-badge');
        if (badge) badge.innerHTML = isSelected ? '<i class="fa-solid fa-check"></i>' : '';
        const title = card.getAttribute('data-title') || 'Photo';
        card.title = `${title} (${window.t(isSelected ? 'organize_media_selected' : 'organize_media_unselected')})`;
      }
    }

    updateMoveCopyRailSummaryOnly();
    updateMoveCopyOptionRowAndHint();
    updateMoveCopyConfirmButton();
  };

  window.removeMoveCopyPhoto = function (photoId) {
    if (_cachedMoveCopyPhotos) {
      _cachedMoveCopyPhotos = _cachedMoveCopyPhotos.filter(p => p.id !== photoId);
    }
    if (state.moveCopyAllSourcePhotoIds) {
      state.moveCopyAllSourcePhotoIds = state.moveCopyAllSourcePhotoIds.filter(id => id !== photoId);
    }
    if (_moveCopyTargetIdSet) {
      _moveCopyTargetIdSet.delete(photoId);
    }
    if (state.moveCopyTargetIds) {
      state.moveCopyTargetIds = state.moveCopyTargetIds.filter(id => id !== photoId);
    }
    renderMoveCopyPreviewRail({ preserveScroll: true });
    updateMoveCopyConfirmButton();
  };

  window.toggleMoveCopySelectAllPhotos = function () {
    const totalCount = (_cachedMoveCopyPhotos || []).length;
    if (!_moveCopyTargetIdSet) {
      _moveCopyTargetIdSet = new Set(state.moveCopyTargetIds || []);
    }
    const allSelected = totalCount > 0 && _moveCopyTargetIdSet.size === totalCount;
    if (allSelected) {
      _moveCopyTargetIdSet.clear();
      state.moveCopyTargetIds = [];
    } else {
      _moveCopyTargetIdSet = new Set((_cachedMoveCopyPhotos || []).map(p => p.id));
      state.moveCopyTargetIds = Array.from(_moveCopyTargetIdSet);
    }
    renderMoveCopyPreviewRail({ preserveScroll: true });
    updateMoveCopyConfirmButton();
  };

  window.setMoveCopyMode = function (mode) {
    state.moveCopyMode = mode;
    const copyBtn = document.getElementById('modeCopyBtn');
    const moveBtn = document.getElementById('modeMoveBtn');

    if (copyBtn) copyBtn.classList.toggle('active', mode === 'copy');
    if (moveBtn) moveBtn.classList.toggle('active', mode === 'move');

    const descriptor = getSelectedMediaDescriptor(state.moveCopyTargetIds && state.moveCopyTargetIds.length ? state.moveCopyTargetIds : _cachedMoveCopyPhotos);
    const copyBtnSpan = document.querySelector('#modeCopyBtn span');
    const moveBtnSpan = document.querySelector('#modeMoveBtn span');
    if (copyBtnSpan) copyBtnSpan.textContent = descriptor.copyLabel;
    if (moveBtnSpan) moveBtnSpan.textContent = descriptor.moveLabel;

    updateMoveCopyOptionRowAndHint();
    updateMoveCopyConfirmButton();
    window.renderMoveCopyAlbumsList();
  };

  window.handleMoveCopySearch = function (query) {
    state.moveCopySearchQuery = (query || '').trim().toLowerCase();
    const quickCreateBtn = document.getElementById('moveCopyQuickCreateBtn');

    // Check if album name already matches query
    const exists = state.tags.some(t => t.name.toLowerCase() === state.moveCopySearchQuery);
    if (quickCreateBtn) {
      quickCreateBtn.style.display = (state.moveCopySearchQuery && !exists) ? 'inline-flex' : 'none';
      quickCreateBtn.innerHTML = `<i class="fa-solid fa-plus"></i> Create '${escapeHtml(query.trim())}'`;
    }

    window.renderMoveCopyAlbumsList();
  };

  window.quickCreateMoveCopyAlbum = function () {
    const input = document.getElementById('moveCopyAlbumSearchInput');
    const name = input ? input.value.trim() : '';
    if (!name) return;

    let tag = state.tags.find(t => t.name.toLowerCase() === name.toLowerCase());
    if (!tag) {
      const now = Date.now();
      tag = {
        name,
        color: PRESET_COLORS[Math.floor(Math.random() * PRESET_COLORS.length)],
        createdAt: now,
        lastModifiedAt: now,
        lastViewedAt: now,
        isFavorite: false
      };
      state.tags.push(tag);
      saveState();
      renderAlbumsScreen();
    }

    window.selectMoveCopyDestination(name);
    if (input) input.value = '';
    const quickCreateBtn = document.getElementById('moveCopyQuickCreateBtn');
    if (quickCreateBtn) quickCreateBtn.style.display = 'none';
    state.moveCopySearchQuery = '';
    window.renderMoveCopyAlbumsList();
    showToast(window.t('organize_album_added', { album: name, count: 0 }));
  };

  window.selectMoveCopyDestination = function (albumName) {
    if (state.moveCopyIsMultiTagDest) {
      state.moveCopyIsMultiTagDest = false;
      state.moveCopyDestinationTags = null;
      state.moveCopySelectedDestinations = [];
    }
    if (!state.moveCopySelectedDestinations) {
      state.moveCopySelectedDestinations = [];
    }

    const idx = state.moveCopySelectedDestinations.indexOf(albumName);
    if (idx >= 0) {
      state.moveCopySelectedDestinations.splice(idx, 1);
    } else {
      state.moveCopySelectedDestinations.push(albumName);
    }

    state.moveCopyDestinationAlbum = state.moveCopySelectedDestinations.join(' + ') || null;
    updateMoveCopyConfirmButton();
    window.renderMoveCopyAlbumsList();
    if (typeof window.updateMultiTagIntersection === 'function') {
      window.updateMultiTagIntersection();
    }
  };

  function updateMoveCopyConfirmButton() {
    const btn = document.getElementById('confirmMoveCopyBtn');
    const icon = document.getElementById('confirmMoveCopyIcon');
    const text = document.getElementById('confirmMoveCopyText');
    if (!btn || !text) return;

    const targetIds = state.moveCopyTargetIds || [];
    const itemCount = targetIds.length;
    const mode = state.moveCopyMode || 'copy';
    const isCopy = mode === 'copy';

    // Get descriptor for currently selected items
    const descriptor = getSelectedMediaDescriptor(targetIds.length ? targetIds : _cachedMoveCopyPhotos);
    const countNoun = itemCount === 1 ? descriptor.nounSingular : descriptor.nounPlural;

    // Update mode button spans in case items changed
    const copyBtnSpan = document.querySelector('#modeCopyBtn span');
    const moveBtnSpan = document.querySelector('#modeMoveBtn span');
    if (copyBtnSpan) copyBtnSpan.textContent = descriptor.copyLabel;
    if (moveBtnSpan) moveBtnSpan.textContent = descriptor.moveLabel;

    if (itemCount === 0) {
      btn.disabled = true;
      const emptyLabel = isCopy ? descriptor.selectCopyLabel : descriptor.selectMoveLabel;
      text.textContent = emptyLabel;
      btn.title = emptyLabel;
      if (icon) icon.className = isCopy ? 'fa-solid fa-copy' : 'fa-solid fa-arrow-right-arrow-left';
      return;
    }

    const selectedDests = state.moveCopySelectedDestinations || [];
    if (state.moveCopyIsMultiTagDest && state.moveCopyDestinationTags && state.moveCopyDestinationTags.length > 0) {
      btn.disabled = false;
      const combinedName = state.moveCopyDestinationTags.join(' + ');
      const tagCount = state.moveCopyDestinationTags.length;

      let actionLabel;
      if (combinedName.length <= 18) {
        actionLabel = window.t
          ? window.t(isCopy ? 'organize_action_btn_copy' : 'organize_action_btn_move', { count: itemCount, noun: countNoun, dest: combinedName, verb: isCopy ? 'Copy' : 'Move' })
          : `${isCopy ? 'Copy' : 'Move'} ${itemCount} ${countNoun} to '${combinedName}'`;
      } else {
        actionLabel = window.t
          ? window.t(isCopy ? 'organize_action_btn_copy_multi' : 'organize_action_btn_move_multi', { count: itemCount, noun: countNoun, dests: tagCount, verb: isCopy ? 'Copy' : 'Move' })
          : `${isCopy ? 'Copy' : 'Move'} ${itemCount} ${countNoun} to ${tagCount} Destination Tags`;
      }

      text.textContent = actionLabel;
      btn.title = `1-to-Many Mapping: ${isCopy ? 'Copy' : 'Move'} ${itemCount} ${countNoun} into all ${tagCount} destination tags (${combinedName})`;
      if (icon) icon.className = isCopy ? 'fa-solid fa-copy' : 'fa-solid fa-arrow-right-arrow-left';
      return;
    }

    if (!selectedDests.length) {
      btn.disabled = true;
      text.textContent = window.t ? window.t('organize_select_dest') : 'Select Destination';
      btn.title = window.t ? window.t('organize_select_dest') : 'Select one or more destination albums to proceed';
      if (icon) icon.className = isCopy ? 'fa-solid fa-copy' : 'fa-solid fa-arrow-right-arrow-left';
      return;
    }

    btn.disabled = false;
    if (selectedDests.length === 1) {
      const dest = selectedDests[0];
      // Format destination name for button text to ensure it never overflows on small mobile devices
      const destDisplay = dest.length > 18 ? (dest.slice(0, 16) + '…') : dest;
      const actionLabel = window.t
        ? window.t(isCopy ? 'organize_action_btn_copy' : 'organize_action_btn_move', { count: itemCount, noun: countNoun, dest: destDisplay, verb: isCopy ? 'Copy' : 'Move' })
        : `${isCopy ? 'Copy' : 'Move'} ${itemCount} ${countNoun} to '${destDisplay}'`;
      const fullActionLabel = `${isCopy ? 'Copy' : 'Move'} ${itemCount} ${countNoun} to '${dest}'`;

      text.textContent = actionLabel;
      btn.title = fullActionLabel;
    } else {
      const combined = selectedDests.join(' + ');
      let actionLabel;
      if (combined.length <= 16) {
        actionLabel = window.t
          ? window.t(isCopy ? 'organize_action_btn_copy' : 'organize_action_btn_move', { count: itemCount, noun: countNoun, dest: combined, verb: isCopy ? 'Copy' : 'Move' })
          : `${isCopy ? 'Copy' : 'Move'} ${itemCount} ${countNoun} to '${combined}'`;
      } else {
        actionLabel = window.t
          ? window.t(isCopy ? 'organize_action_btn_copy_multi' : 'organize_action_btn_move_multi', { count: itemCount, noun: countNoun, dests: selectedDests.length, verb: isCopy ? 'Copy' : 'Move' })
          : `${isCopy ? 'Copy' : 'Move'} ${itemCount} ${countNoun} to ${selectedDests.length} Destination Albums`;
      }
      text.textContent = actionLabel;
      btn.title = `${isCopy ? 'Copy' : 'Move'} ${itemCount} ${countNoun} into ${selectedDests.length} destination albums (${combined})`;
    }
    if (icon) icon.className = isCopy ? 'fa-solid fa-copy' : 'fa-solid fa-arrow-right-arrow-left';
  }



  window.renderMoveCopyAlbumsList = function () {
    const list = document.getElementById('moveCopyAlbumsList');
    if (!list) return;

    const destPill = document.getElementById('moveCopyDestSelectionPill');
    const selectedDestCount = (state.moveCopySelectedDestinations || []).length;
    if (destPill) {
      if (selectedDestCount > 0) {
        destPill.style.display = 'inline-flex';
        destPill.innerHTML = `<i class="fa-solid fa-check"></i> ${selectedDestCount} Selected`;
      } else {
        destPill.style.display = 'none';
      }
    }

    const q = state.moveCopySearchQuery || '';
    const sourceAlbum = state.moveCopySourceAlbum;

    let availableTags = state.tags || [];
    if (q) {
      availableTags = availableTags.filter(t => t.name.toLowerCase().includes(q));
    }

    if (!availableTags.length) {
      list.innerHTML = `
        <div style="text-align: center; padding: 20px; color: var(--text-muted); font-size: 13px;">
          No matching albums found. Tap "Create" above to make a new one!
        </div>
      `;
      return;
    }

    const validPhotos = state.photos.filter(p => !p.isPending && !p.deletedAt);
    const tagCounts = new Map();
    for (let i = 0; i < validPhotos.length; i++) {
      const p = validPhotos[i];
      if (Array.isArray(p.tags)) {
        for (let j = 0; j < p.tags.length; j++) {
          const tn = p.tags[j];
          tagCounts.set(tn, (tagCounts.get(tn) || 0) + 1);
        }
      }
    }

    // Multi-tag combined row at top if >= 2 valid tags
    const multiTags = (state.moveCopyMultiTags || []).filter(t => t && t.trim().length > 0);
    let multiTagTopRowHtml = '';
    if (multiTags.length >= 2) {
      const combinedName = multiTags.join(' + ');
      const isMultiSelected = !!state.moveCopyIsMultiTagDest;
      const matchCount = validPhotos.filter(p =>
        multiTags.every(vt => p.tags && p.tags.some(pt => pt.toLowerCase() === vt.toLowerCase()))
      ).length;
      const countNoun = matchCount === 1
        ? (window.t ? window.t('organize_item_singular') : 'item')
        : (window.t ? window.t('organize_items_plural') : 'items');

      const dotStackHtml = multiTags.map(t => {
        const tagObj = (state.tags || []).find(tag => tag.name.toLowerCase() === t.toLowerCase());
        const color = tagObj ? tagObj.color : '#fbbf24';
        return `<span class="multitag-stack-dot" style="background: ${color};" title="${escapeHtml(t)}"></span>`;
      }).join('');

      multiTagTopRowHtml = `
        <div class="move-copy-album-row multitag-combined-row ${isMultiSelected ? 'selected' : ''}" 
             onclick="selectMultiTagAsDestination()" title="Select 1-to-Many combined destination: ${escapeHtml(combinedName)}">
          <div class="album-row-left multitag-combined-left">
            <div class="multitag-result-dot-stack">
              ${dotStackHtml}
            </div>
            <div class="multitag-combined-info">
              <div class="multitag-combined-header">
                <span class="multitag-combined-title" title="${escapeHtml(combinedName)}">${escapeHtml(combinedName)}</span>
                <span class="multitag-vip-pill" title="1-to-Many: Photos will be assigned to all ${multiTags.length} destination tags"><i class="fa-solid fa-diagram-project"></i> 1-to-Many Pro</span>
              </div>
              <div class="multitag-combined-sub">
                <span class="multitag-combined-desc"><i class="fa-solid fa-arrows-split-up-and-left" style="font-size: 10px;"></i> Mapped to all ${multiTags.length} tags</span>
                <span class="multitag-combined-sep">•</span>
                <span class="multitag-combined-match">${matchCount} ${escapeHtml(countNoun)} match</span>
              </div>
            </div>
          </div>
          <div class="album-row-radio">
            <i class="fa-solid fa-check"></i>
          </div>
        </div>
      `;
    }

    list.innerHTML = multiTagTopRowHtml + availableTags.map(tag => {
      const isSelected = (state.moveCopySelectedDestinations || []).includes(tag.name);
      // In album mode, disable source album for both copy and move (cannot copy/move an album into itself)
      // In photo mode, only disable source in move mode
      const isSource = sourceAlbum && sourceAlbum.toLowerCase() === tag.name.toLowerCase();
      const isDisabled = state.moveCopyIsAlbumMode ? isSource : (state.moveCopyMode === 'move' && isSource);
      const count = tagCounts.get(tag.name) || 0;

      let clickHandler = `selectMoveCopyDestination('${escapeHtml(tag.name)}')`;
      if (isDisabled) {
        if (state.moveCopyIsAlbumMode) {
          clickHandler = `showToast(window.t('organize_source_destination_error'))`;
        } else {
          clickHandler = `showToast(window.t('organize_source_destination_error'))`;
        }
      }

      const sourceTagLabel = window.t ? window.t('organize_source_tag') : 'Source Album';
      const countNoun = window.t(count === 1 ? 'organize_item_singular' : 'organize_items_plural');

      return `
        <div class="move-copy-album-row ${isSelected ? 'selected' : ''} ${isDisabled ? 'disabled' : ''}" 
             onclick="${clickHandler}">
          <div class="album-row-left">
            <span class="album-row-dot" style="background: ${tag.color};"></span>
            <div class="album-row-info">
              <div class="album-row-name" title="${escapeHtml(tag.name)}">
                ${escapeHtml(tag.name)}
                ${isSource ? `<span class="source-album-label-pill">(${escapeHtml(sourceTagLabel)})</span>` : ''}
              </div>
              <div class="album-row-count">${count} ${escapeHtml(countNoun)}</div>
            </div>
          </div>
          <div class="album-row-radio">
            <i class="fa-solid fa-check"></i>
          </div>
        </div>
      `;
    }).join('');
  };

