  // Direct year entry complements the calendar for older dates.
  const localDateInput = timestamp => {
    if (timestamp == null) return '';
    const date = new Date(timestamp);
    return date.getFullYear().toString().padStart(4, '0') + '-' + String(date.getMonth()+1).padStart(2,'0') + '-' + String(date.getDate()).padStart(2,'0');
  };
  for (const prefix of ['from', 'to']) {
    const dateInput = document.getElementById(prefix + 'DatePicker');
    const yearInput = document.getElementById(prefix + 'DateYear');
    dateInput.addEventListener('change', () => {
      yearInput.value = dateInput.value ? Number(dateInput.value.split('-')[0]) : '';
      document.getElementById('toDatePicker').setCustomValidity('');
    });
    yearInput.addEventListener('input', () => {
      if (!yearInput.checkValidity() || yearInput.value.length !== 4) return;
      const year = Number(yearInput.value);
      const parts = (dateInput.value || localDateInput(Date.now())).split('-').map(Number);
      const maxDay = new Date(2000, parts[1], 0);
      maxDay.setFullYear(year, parts[1], 0);
      dateInput.value = String(year).padStart(4,'0') + '-' + String(parts[1]).padStart(2,'0') + '-' + String(Math.min(parts[2], maxDay.getDate())).padStart(2,'0');
      document.getElementById('toDatePicker').setCustomValidity('');
    });
  }

  // Date Range Picker Modal
  const revealDateYear = () => requestAnimationFrame(() => {
    const modal = document.getElementById('datePickerModal');
    const active = document.activeElement;
    if (modal.style.display === 'none' || !modal.contains(active) || !active.matches('.date-year-entry input')) return;
    const body = modal.querySelector('.date-form-scroll');
    if (getComputedStyle(body).display === 'contents') return;
    const box = active.closest('.dialog-field-group').getBoundingClientRect();
    const visible = body.getBoundingClientRect();
    if (box.bottom > visible.bottom) body.scrollTop += box.bottom - visible.bottom;
    else if (box.top < visible.top) body.scrollTop -= visible.top - box.top;
  });
  document.getElementById('datePickerModal').addEventListener('focusin', revealDateYear);
  window.visualViewport?.addEventListener('resize', revealDateYear, { passive: true });
  new MutationObserver(revealDateYear).observe(document.documentElement, { attributes: true, attributeFilter: ['style', 'class'] });
  document.getElementById('dateFilterChip')?.addEventListener('click', (e) => {
    if (e.target.id === 'clearDateBtn') return;
    for (const [prefix, timestamp] of [['from', state.startDate], ['to', state.endDate]]) {
      const input = document.getElementById(prefix + 'DatePicker');
      input.value = localDateInput(timestamp);
      input.setCustomValidity('');
      document.getElementById(prefix + 'DateYear').value = input.value ? Number(input.value.split('-')[0]) : '';
    }
    document.getElementById('datePickerModal').style.display = 'flex';
  });

